// RULE: ntrs-extraction-fidelity
// FAMILY: extraction-artifact (a verification detector: fires on DIVERGENCE)
//
// STATEMENT: for the NTRS white-papers slice of live_priors, the .txt body
// (everything after the YAML frontmatter's closing "---" line, plus the
// separator blank line the frontmatter-prepend step adds) is a byte-exact
// `pdftotext -layout` of the ORIGINAL PDF named by the frontmatter's
// source_url — not a re-typed, hand-edited, or differently-piped copy.
// Measured 6/6 on the sampled originals (19650003019, 19650011211,
// 19660007927, 19660017568, 19880012630, 19880020389): every one reproduced
// character-for-character once the frontmatter/separator and trailing
// form-feed/newline runs are stripped from both sides.
//
// SCOPE: this is a POSITIVE finding for THIS territory (ntrs-white-papers)
// only. It says nothing about other live_priors collections (Wikisource,
// Gutenberg, GRETIL, ...) where the seed rules document real extraction
// damage — this detector exists precisely so a future reader can CHECK
// whether that same fidelity holds for a given NTRS record, rather than
// assuming it from these 6 samples.
//
// `text` = the live_priors .txt file's full content (frontmatter + body).
// `ctx.freshLayoutText` = a fresh `pdftotext -layout` run on the original
// PDF fetched from the frontmatter's source_url (or the NTRS downloads API).
// `fired: true` means a MISMATCH was found — the cached .txt does NOT match
// a fresh re-extraction of the original, i.e. don't trust this .txt.
export function detect(text, ctx = {}) {
  if (!ctx.freshLayoutText || typeof ctx.freshLayoutText !== "string") {
    return { fired: false, evidence: { skipped: true, reason: "ctx.freshLayoutText not supplied — nothing to compare against" } };
  }
  const stripFrontmatter = (s) => {
    if (s.startsWith("---\n")) {
      const idx = s.indexOf("\n---\n", 4);
      if (idx !== -1) return s.slice(idx + 5);
    }
    return s;
  };
  let a = stripFrontmatter(text);
  if (a.startsWith("\n")) a = a.slice(1); // the frontmatter-prepend step's own separator blank line
  a = a.replace(/[\x0c\n]+$/, "");
  const b = ctx.freshLayoutText.replace(/[\x0c\n]+$/, "");

  if (a === b) {
    return { fired: false, evidence: { match: true, bodyLength: a.length } };
  }
  // find first divergence for a concrete, quotable pointer
  let i = 0;
  const minLen = Math.min(a.length, b.length);
  while (i < minLen && a[i] === b[i]) i++;
  return {
    fired: true,
    evidence: {
      match: false,
      cachedLength: a.length,
      freshLength: b.length,
      firstDivergenceAt: i,
      cachedContext: a.slice(Math.max(0, i - 40), i + 40),
      freshContext: b.slice(Math.max(0, i - 40), i + 40),
    },
  };
}

// RULE: wide-whitespace-lone-signal-false-positive
// FAMILY: extraction-artifact (critiques an existing detector's behavior on
//         this source family: eoreader7 organs/look.js::weirdFormattingScore)
//
// STATEMENT: on Acrobat-Capture-OCR'd technical-report scans (the NTRS
// white-papers texture: old, justified, proportionally-spaced typewriter/
// phototype originals), weirdFormattingScore's `wide_whitespace_runs` signal
// (>=30% of content lines contain a run of 4+ spaces) fires on the large
// majority of ALL pages, including ordinary run-on prose paragraphs, because
// the old OCR reconstructs justified-line spacing unevenly. Firing on this
// ONE signal alone is a weak reason to spend a CV/vision call.
//
// MEASURED (148 non-empty pages across the 6 sampled originals):
//   86.5% (128/148) of pages trip weirdFormattingScore > 0 at all.
//   60.2% of those (77/128 triggered pages = 52.0% of ALL pages) trip on
//   wide_whitespace_runs ALONE — no other signal.
// Manually confirmed ordinary-prose examples in that lone-signal bucket
// (rendered + read): 19650003019 p6 ("SECTION I" heading), p7 (a plain
// paragraph: "The principle of the infrared heat transfer gage has been
// discussed in detail by Camac...", confirmed by fresh Tesseract to be
// unremarkable justified prose), p10 (mid-derivation prose).
//
// SCOPE: this is about the SIGNAL, not the whole score — a page where
// wide_whitespace_runs co-fires with >=1 other signal is NOT covered by
// this rule (those pages, measured separately, are more often real
// figures/tables). BROADENED by our own held-out check: this is NOT
// specific to old-OCR scans as first guessed — run against 20180004558 (a
// 2018 BORN-DIGITAL NTRS record, pdfinfo Creator "Word", no OCR anywhere in
// its pipeline), this rule fires on all 4 of its pages too. The true cause
// is more general than "old OCR reconstructs justified spacing unevenly":
// wide_whitespace_runs fires near-universally on JUSTIFIED prose of any
// vintage or production pipeline, because justification itself inserts
// occasional wide inter-word gaps to fill a line. Not yet checked against
// RAGGED-RIGHT (unjustified) text, where the signal should be much rarer —
// that comparison is left to the held-out targets below.
//
// `text` is one page's (or one document's) plain text.
export function detect(text, ctx = {}) {
  const minLines = ctx.minLines ?? 3;
  if (!text || typeof text !== "string") return { fired: false, evidence: {} };
  const lines = text.split("\n");
  const contentLines = lines.filter((l) => l.trim());
  if (contentLines.length < minLines) return { fired: false, evidence: { reason: "too few content lines" } };

  const tablePipes = contentLines.filter((l) => /[|¦│]/.test(l)).length;
  const BOX_DRAWING = /[─-╿▐-▟]/;
  const boxDraw = contentLines.filter((l) => BOX_DRAWING.test(l)).length;
  const shortLines = contentLines.filter((l) => l.trim().length > 0 && l.trim().length <= 12).length;
  const avgWords = contentLines.reduce((a, l) => a + l.trim().split(/\s+/).filter(Boolean).length, 0) / contentLines.length;
  const longRuns = contentLines.filter((l) => / {4,}/.test(l)).length;
  const widths = contentLines.map((l) => l.trim().length);
  const avgWidth = widths.reduce((a, b) => a + b, 0) / Math.max(1, widths.length);

  const signals = [];
  if (tablePipes / contentLines.length >= 0.5) signals.push("table_rows");
  if (boxDraw / contentLines.length >= 0.2) signals.push("box_drawing");
  if (shortLines / contentLines.length >= 0.4) signals.push("very_short_lines");
  if (avgWords <= 2.5) signals.push("sub_sentence_lines");
  if (longRuns / contentLines.length >= 0.3) signals.push("wide_whitespace_runs");
  if (avgWidth > 0 && avgWidth <= 20 && contentLines.length >= 8) signals.push("narrow_column");

  const lone = signals.length === 1 && signals[0] === "wide_whitespace_runs";
  return {
    fired: lone,
    evidence: {
      signals,
      score: signals.length,
      avgWords: Number(avgWords.toFixed(2)),
      contentLines: contentLines.length,
      wideWhitespaceLineFrac: Number((longRuns / contentLines.length).toFixed(2)),
      interpretation: lone
        ? "this page would be flagged for a CV look on wide_whitespace_runs alone; measured base rate on this source family is ~52% of all pages, many of them ordinary prose"
        : "not the lone-signal case (either not triggered, or triggered with corroborating signals)",
    },
  };
}

// RULE: isolated-letter-split
// FAMILY: extraction-artifact (with a cv-distilled payoff: the fix is a
//         mechanical re-OCR, not a vision-model call)
//
// STATEMENT: the ~1990s Acrobat Capture 3.0 OCR text layer embedded in these
// NTRS PDFs (Creator: "Acrobat Capture 3.0" on all 6 sampled originals'
// pdfinfo) frequently mis-segments a real word into several single-letter
// "words" joined by ordinary spaces — e.g. "infrared" -> "i n f r a r e d",
// "Rose" -> "R o s e", "REPORT" -> "R E P O R T" — UNPREDICTABLY, on both
// ALL-CAPS display headings and ordinary mixed-case body prose on the SAME
// page. A byte signature (>=2 single-alphabetic-character tokens on one
// line that are NOT a real one-letter word, a roman numeral, or an
// abbreviation-with-period) flags a line whose word-tokenization cannot be
// trusted.
//
// VERIFIED (not merely inherited from the untrusted .cv.md sidecar): a
// FRESH `tesseract --psm 3` run on the PDF page rendered at 150dpi
// (19650003019 pages 2, 4, 7) reads every one of these words correctly with
// no internal splitting — "infrared", "Rose", "REPORT" all come back whole.
// So the defect lives ONLY in the old embedded OCR text layer that
// pdftotext reads (confirmed identical to live_priors' own .txt — see
// ntrs-extraction-fidelity), not in the scanned image. The actionable
// consequence: when this signature fires, a plain mechanical re-OCR of the
// rendered page fixes it — no vision-model call is needed (contrast
// rotated-axis-label-run, where a vision/CV step IS needed because the
// defect is orientation, not engine age).
//
// FALSIFIED-AND-NARROWED BY OUR OWN HELD-OUT CHECK (not left for another
// agent to find): run against 20180004558 (a 2018, BORN-DIGITAL NTRS record
// — pdfinfo Creator "Word", Producer "Mac OS X 10.11.6 Quartz PDFContext",
// no OCR anywhere in its pipeline), this detector still fires (15/280
// lines) — but for a DIFFERENT, legitimate reason: inline math variable
// names in equations ("M -1 N -1", "I1 (m, n) I2 (x + m, y + n)"). The
// BYTE SIGNATURE (>=2 bare single letters on a line) is therefore NOT
// unique to OCR word-mis-segmentation — it also matches ordinary single-
// letter math notation on a clean, born-digital page. The rule's
// DETECTION still correctly says "don't naively word-tokenize this line";
// its PRESCRIBED FIX (re-OCR the rendered page) does NOT apply in the
// math-notation case — there is nothing wrong to re-OCR. Distinguish the
// two by base rate and source, not by the signature alone: our 1960s
// Acrobat-Capture scans hit on 40-100% of a document's pages (measured:
// 19650003019 48/48, 19660017568 31/32, 19880012630 8/20, 19880020389
// 24/37); this one clean born-digital math paper hits on 15/280 lines
// (~5%), concentrated in equation blocks, not spread through prose.
//
// A single-letter token ending in "." is excluded on purpose: that is the
// real, standing convention for an initial ("P.", "J.") or an abbreviation,
// not a split fragment — verified against 19650003019 p2's byline "P. H.
// Rose and J. O. Stankevics", where "P." "H." "J." "O." must NOT count but
// the genuinely split "R o s e" must.
//
// House rule: the excluded words and roman numerals are closed TABLES
// (Sets), never a regex alternation.
const REAL_ONE_LETTER_WORDS = new Set(["a", "A", "I"]);
const ROMAN_NUMERALS = new Set(["I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX", "X", "XI", "XII"]);

function isSuspiciousToken(tok) {
  if (tok.endsWith(".")) return false; // an initial/abbreviation, not a split fragment
  const bare = tok.replace(/[,;:]+$/, "");
  return bare.length === 1 && /[A-Za-z]/.test(bare) && !REAL_ONE_LETTER_WORDS.has(bare) && !ROMAN_NUMERALS.has(bare);
}

export function detect(text, ctx = {}) {
  const minSuspiciousPerLine = ctx.minSuspiciousPerLine ?? 2;
  if (!text || typeof text !== "string") return { fired: false, evidence: {} };
  const lines = text.split("\n");
  const hits = [];
  for (let i = 0; i < lines.length; i++) {
    const toks = lines[i].trim().split(/\s+/).filter(Boolean);
    const count = toks.filter(isSuspiciousToken).length;
    if (count >= minSuspiciousPerLine) {
      hits.push({ line: i + 1, count, text: lines[i].trim().slice(0, 100) });
    }
  }
  return {
    fired: hits.length > 0,
    evidence: {
      linesFlagged: hits.length,
      totalLines: lines.length,
      examples: hits.slice(0, 8),
    },
  };
}

// RULE: merged-runon-tokens
// FAMILY: extraction-artifact (the mirror-image failure of isolated-letter-split:
//         the same old OCR text layer sometimes DELETES real inter-word
//         spaces instead of inventing extra ones)
//
// STATEMENT: an all-lowercase alphabetic token of length >= 20 in a
// pdftotext -layout extraction of one of these Acrobat-Capture-OCR'd PDFs is
// (in the sampled territory) always several real words run together, never
// one genuine English technical word — e.g. "theseexpressionshavebeenimproved",
// "usingourpreviouslyobtainedconfigurationfactors" (both from 19660017568).
//
// MEASURED NULL (across all 6 sampled originals' full pdftotext -layout
// text, 49,671 all-lowercase alphabetic tokens): length percentiles are
// p50=1, p90=5, p99=11, p99.9=16 — so length>=20 is deep in the extreme
// tail (31 tokens, 0.06% of all tokens). The ONE legitimate long word found
// anywhere near that tail, "nondimensionalized" (18 characters), occurs
// TWICE, independently, in two different documents (19650011211 and
// 19880020389) — it sits BELOW the length=20 cutoff. Every one of the 31
// tokens at length>=20 was inspected by hand; all 31 are multi-word merges.
// The threshold (20) is therefore a hand-set choice, justified by: (a) it
// sits above the one known real exception (18) with margin, (b) it is far
// out past p99.9 (16) of the corpus's own token-length distribution, (c) a
// full manual check of every token it currently selects found zero false
// positives — not a guess.
//
// SCOPE: measured concentration was NOT even across documents — 30 of the
// 31 length>=20 tokens came from a single document (19660017568). This
// failure mode should be treated as batch/document-specific (perhaps a
// worse scan or a different OCR pass), not a corpus-wide constant rate like
// isolated-letter-split's ~52% page base rate. A detector firing on one
// document says little about whether it will fire on another from the same
// collection.
const MIN_LEN = 20;

export function detect(text, ctx = {}) {
  const minLen = ctx.minLen ?? MIN_LEN;
  if (!text || typeof text !== "string") return { fired: false, evidence: {} };
  const toks = text.split(/\s+/).filter(Boolean);
  const hits = [];
  for (const t of toks) {
    if (/^[a-z]+$/.test(t) && t.length >= minLen) hits.push(t);
  }
  return {
    fired: hits.length > 0,
    evidence: {
      count: hits.length,
      totalAlphaTokens: toks.filter((t) => /^[a-z]+$/.test(t)).length,
      examples: hits.slice(0, 10),
      threshold: minLen,
    },
  };
}

// RULE: rotated-axis-label-run
// FAMILY: cv-distilled
//
// STATEMENT: on a FIGURE-shaped page (weirdFormattingScore-style profile:
// low average words per line, many very-short lines — i.e. the page is
// mostly a plot, not prose) a LONG run (>=6 in a row) of single-character or
// two-character tokens on one line predicts a ROTATED axis label that the
// old OCR text layer read letter-by-letter along its vertical run and
// dumped onto one horizontal output line, e.g. the y-axis label of
// 19660017568 page 10 ("Effective Reflectance Ratio", printed sideways in
// the original) surfaces in pdftotext -layout as
// "E f f e c t i v eR e f l e c t a n c eR a t i o" — mostly single letters
// with spaces, but with the ORIGINAL word boundaries partly collapsed
// (no space) because vertical stacking carries no horizontal word-gap to
// preserve.
//
// This is DISTINGUISHED from isolated-letter-split (the general old-OCR
// word-mis-segmentation defect, which fires on ordinary prose pages too) by
// TWO joint conditions specific to this rule: (1) the run of suspicious
// tokens is long (>=6 consecutive), not just >=2 scattered on the line, and
// (2) it occurs on a page whose overall shape already looks like a figure
// (avgWords/line <= 10), not a prose page. Verified: rendering 19660017568
// page 10 at 150dpi shows a genuine engineering plot (curve family, x/y
// axes, a vertically-set axis label) — confirmed visually, not assumed.
//
// CV-DISTILLED PAYOFF: unlike isolated-letter-split (fixed by a plain
// re-OCR of the upright page), THIS defect is NOT fixed by a plain re-OCR —
// the label is genuinely rotated 90 degrees in the image, so an
// upright-only OCR pass (tesseract's default orientation) will misread it
// too. A byte-signature match here should route to an ACTUAL visual/CV
// step (rotate-and-reOCR, or OpenCV line/axis detection), not a bare
// re-run of the same mechanical OCR. This is the one rule in this bench
// where "the look is not needed next time" does NOT hold — the signature's
// job is to say WHERE a real look is worth spending, not to replace it.
function isShortToken(tok) {
  const bare = tok.replace(/[.,;:()]+$/, "").replace(/^[.,;:()]+/, "");
  return bare.length > 0 && bare.length <= 2 && /^[A-Za-z]+$/.test(bare);
}

export function detect(text, ctx = {}) {
  const minRun = ctx.minRun ?? 6;
  const maxAvgWords = ctx.maxAvgWords ?? 10;
  if (!text || typeof text !== "string") return { fired: false, evidence: {} };
  const lines = text.split("\n");
  const content = lines.filter((l) => l.trim());
  if (content.length < 3) return { fired: false, evidence: { reason: "too few content lines" } };
  const avgWords = content.reduce((a, l) => a + l.trim().split(/\s+/).filter(Boolean).length, 0) / content.length;

  const runs = [];
  for (let i = 0; i < lines.length; i++) {
    const toks = lines[i].trim().split(/\s+/).filter(Boolean);
    let run = 0, best = 0;
    for (const t of toks) {
      if (isShortToken(t)) { run++; best = Math.max(best, run); } else { run = 0; }
    }
    if (best >= minRun) runs.push({ line: i + 1, run: best, text: lines[i].trim().slice(0, 100) });
  }

  const pageLooksLikeFigure = avgWords <= maxAvgWords;
  const fired = pageLooksLikeFigure && runs.length > 0;
  return {
    fired,
    evidence: {
      avgWordsPerLine: Number(avgWords.toFixed(2)),
      pageLooksLikeFigure,
      runsFound: runs.length,
      examples: runs.slice(0, 5),
    },
  };
}

// RULE: gap-aligned-toc-table
// FAMILY: source-convention (with a cv-distilled corollary: don't look, the
//         flat text is already better than a naive OCR read)
//
// STATEMENT: the front-matter table-of-contents / index pages in this
// sample (typewritten 1960s NASA/AVCO contractor reports) align "SECTION"
// and "Page" columns with a WIDE WHITESPACE GAP, not with dot leaders.
// Checked directly against the rendered page image (19650003019 page 4):
// zero "." dot-leader glyphs exist between "Introduction" and its page
// number "1" — the gap is genuinely empty. This NARROWS the general
// expectation (stated in this bench's own brief, and true of typeset
// Wikisource TOCs) that a table of contents carries dot leaders: in this
// typewriter-originated corpus, it does not, and a detector that only
// looks for dot leaders (literal "." runs) will MISS every TOC in this
// sample (measured: 0 true dot-leader hits across all 6 originals' full
// text — the one incidental "...." match found, 19880020389 page 34, is a
// dashed line-style legend swatch inside a figure, not a TOC, confirmed by
// rendering that page).
//
// CV-DISTILLED COROLLARY, independently verified twice (not inherited from
// the untrusted .cv.md): a plain full-page `tesseract --psm 3` OCR of this
// same TOC page (19650003019 p4) — both the prior .cv.md's own transcript
// AND a byte-identical fresh run made for this bench — completely LOSES the
// row pairing: every page number ends up in one disconnected trailing list
// ("Page / iii / 13 / 21 / 23 / 43") separated from its section title,
// because naive OCR reading order doesn't know the two columns are one row.
// `pdftotext -layout`, because it tracks physical x-position, keeps
// "IV.     Calibration of the Infrared Gage System          13" on ONE
// line. For this page SHAPE, the flat text is already the better read —
// firing this detector should suppress a CV look, not request one.
// EXTRACTION-CHOICE CAVEAT, confirmed by our own held-out check: this rule
// detects gap-alignment as pdftotext -layout exposes it. Run against NTRS's
// OWN server-side fulltext extraction of the SAME page (a different
// pipeline for the identical document, https://ntrs.nasa.gov/api/citations/
// 19650003019/downloads/19650003019.txt) the detector correctly does NOT
// fire (gapAlignedRows=0) — that pipeline is not layout-aware and dumps
// every TOC token onto its own line ("SECTION" / "Page" / "Abstract" /
// "I." / "iii" / "Introduction" / "1" / ...), destroying the row pairing
// entirely even though the SOURCE's own convention (wide-gap alignment, no
// dot leaders) is unchanged. This rule's silence therefore means "this
// extraction didn't preserve layout," not "the source lacks the
// convention" — check which pdftotext mode (or which pipeline) produced
// the text before concluding a TOC page LACKS this structure.
const TOC_HEADER_WORDS = new Set(["SECTION", "CONTENTS", "TABLE"]);
const ROMAN_PAGENUM = new Set(["i", "ii", "iii", "iv", "v", "vi", "vii", "viii", "ix", "x"]);

function isTocRow(line) {
  const m = line.match(/^(.*\S)( {6,})(\S+)\s*$/);
  if (!m) return false;
  const label = m[1].trim();
  const trailing = m[3].trim();
  const isNum = /^\d{1,4}$/.test(trailing);
  const isRoman = ROMAN_PAGENUM.has(trailing.toLowerCase());
  if (!isNum && !isRoman) return false;
  if (label.length < 2) return false;
  return true;
}

export function detect(text, ctx = {}) {
  const minRows = ctx.minRows ?? 4;
  if (!text || typeof text !== "string") return { fired: false, evidence: {} };
  const lines = text.split("\n");
  const rows = [];
  for (let i = 0; i < lines.length; i++) {
    if (isTocRow(lines[i])) rows.push({ line: i + 1, text: lines[i].trim().slice(0, 90) });
  }
  const hasHeaderWord = lines.some((l) => {
    const w = l.trim().replace(/[^A-Z]/g, "");
    return TOC_HEADER_WORDS.has(w) || /TABLE\s*O?\s*F\s*CONTENTS/i.test(l);
  });
  const dotLeaderCount = lines.filter((l) => /\.{4,}/.test(l)).length;
  const fired = rows.length >= minRows;
  return {
    fired,
    evidence: {
      gapAlignedRows: rows.length,
      hasContentsHeader: hasHeaderWord,
      dotLeaderLinesFound: dotLeaderCount,
      examples: rows.slice(0, 8),
      note: "dotLeaderLinesFound>0 without gapAlignedRows firing is NOT this rule's target — see the file header re: the one figure-legend false hit",
    },
  };
}

// RULE: report-documentation-page-boilerplate
// FAMILY: source-convention (a fixed US-government form) with an
//         extraction-artifact/false-negative note about weirdFormattingScore
//
// STATEMENT: 1980s-era NASA Technical Memoranda in this corpus end with a
// standardized "Report Documentation Page" (NASA Form 1626, the NASA analog
// of DD Form 1473 / Standard Form 298) — a fixed grid of ~20 numbered
// fields (Report No., Government Accession No., Title and Subtitle,
// Author(s), Performing Organization, Sponsoring Agency, Abstract, Key
// Words, Security Classification, No. of pages, Price...). VERIFIED
// identical in structure across TWO independent documents from different
// months of the same year (19880012630, NASA TM-100083, March 1988; and
// 19880020389, both ending with this exact page as their LAST page), each
// reproduced field-by-field, in reading order, by plain `pdftotext -layout`
// — confirmed by rendering both pages and comparing to the extracted text
// directly (not via the untrusted .cv.md). The field labels are closed,
// government-mandated boilerplate text, not the author's prose — safe to
// match as literal strings (a TABLE), never a regex alternation.
//
// FALSE-NEGATIVE NOTE: weirdFormattingScore scores this page only 1
// (wide_whitespace_runs) on both sampled instances, despite the page being
// the single most rigidly tabular page in either document — because its
// grid lines are drawn, not typed as "|" characters, so `table_rows` (which
// only counts literal pipe/¦/│ glyphs) never fires. A pipe-character test
// cannot see a form whose columns are ruled lines in the scanned image, not
// ASCII art in the text.
//
// SCOPE: only observed on TECHNICAL_MEMORANDUM-type NTRS records from the
// 1980s in this sample; the 1960s-era CONTRACTOR_REPORT records
// (19650003019, 19650011211, 19660007927, 19660017568) carry no such page
// at all — this form postdates them. Do not expect it on older NTRS scans.
const FIELD_LABELS = [
  "Report Documentation Page",
  "Government Accession No.",
  "Recipient's Catalog No.",
  "Recipient’s Catalog No.",
  "Performing Organization",
  "Sponsoring Agency",
  "Security Classif",
  "Supplementary Notes",
  "Supplementan/ Notes", // observed OCR misread of "Supplementary Notes" — kept as its own literal, not folded into a regex
];

export function detect(text, ctx = {}) {
  const minFieldHits = ctx.minFieldHits ?? 3;
  if (!text || typeof text !== "string") return { fired: false, evidence: {} };
  const titleHit = text.includes("Report Documentation Page");
  const fieldHits = FIELD_LABELS.filter((f) => f !== "Report Documentation Page" && text.includes(f));
  const pipeCount = (text.match(/[|¦│]/g) || []).length;
  const contentLines = text.split("\n").filter((l) => l.trim());
  const fired = titleHit || fieldHits.length >= minFieldHits;
  return {
    fired,
    evidence: {
      titleHit,
      fieldHits,
      fieldHitCount: fieldHits.length,
      pipeCharsOnPage: pipeCount,
      contentLines: contentLines.length,
      note: pipeCount === 0 ? "zero pipe characters on a page that is visually a ruled grid — table_rows would not fire here" : undefined,
    },
  };
}

// RULE: sequential-page-footer
// FAMILY: source-convention (the edition's own pagination — kin to seed S3's
//         "editor's lineation" and S9's "scan furniture", but for a report's
//         own body-page numbers, not verse lines or injected scan UI)
//
// STATEMENT: the body pages of 19650003019 (an AVCO-Everett 1964 contractor
// report) each end with a standalone footer line of the shape "-N-" (a
// hyphen, the page number, a hyphen — pdftotext -layout sometimes inserts a
// stray inner space from OCR, e.g. "-6 -"), and N increments by exactly 1
// from page to page (measured directly: true PDF pages 7-13 carry footers
// -2-, -3-, -4-, -5-, -6-, -7-, -8-, a run of 7 consecutive integers with no
// gap or repeat). This is the report's OWN pagination, separate from the
// PDF's physical page count (the front matter — cover, title, abstract, TOC
// — carries roman-numeral or no footer; "-2-" begins the numbered body).
//
// MEASURED NULL (house rule: prefer a measured statistic to a hand-set
// threshold): under a null where trailing footer numbers on consecutive
// pages are unrelated integers drawn from a plausible page-count range
// (say 1-60), the chance that k DIFFERENT consecutive pages' footers
// happen to form a run increasing by exactly 1 by pure coincidence is
// roughly (1/60)^(k-1) for k consecutive confirmations — for the k=7 run
// measured here that is on the order of 60^-6, i.e. effectively zero by
// chance. A real, intentional pagination convention is the only credible
// explanation.
//
// SCOPE: confirmed in this ONE document's body-text era/typeface
// (proportional AVCO phototype, 1964). Not yet checked against the 1988
// Technical Memoranda in this same sample, which may use a different
// footer convention (they use a printed running page number instead — see
// held-out targets). Treat "-N-" specifically as this document's/imprint's
// convention, and the GENERAL claim only as "a standalone footer line whose
// number increments by 1 down consecutive pages is this edition's own
// pagination" — the exact glyphs bracketing the number are not assumed to
// generalize.
function extractFooterNumber(pageText) {
  const lines = pageText.split("\n").map((l) => l.trim()).filter(Boolean);
  if (!lines.length) return null;
  const last = lines[lines.length - 1];
  const m = last.match(/^-\s*(\d{1,4})\s*-$/);
  return m ? { raw: last, n: Number(m[1]) } : null;
}

export function detect(text, ctx = {}) {
  const minRun = ctx.minRun ?? 3;
  if (!text || typeof text !== "string") return { fired: false, evidence: {} };
  // text may be a whole document (form-feed-separated pages) or ctx.pages already split
  const pages = Array.isArray(ctx.pages) ? ctx.pages : text.split("\x0c");
  const footers = pages.map((p, i) => ({ page: i + 1, footer: extractFooterNumber(p) }));
  const withFooter = footers.filter((f) => f.footer);

  // find the longest run of consecutive PDF pages whose footer numbers also increment by 1
  let bestRun = [];
  let curRun = [];
  for (let i = 0; i < withFooter.length; i++) {
    if (curRun.length === 0) { curRun = [withFooter[i]]; continue; }
    const prev = curRun[curRun.length - 1];
    const samePageGap = withFooter[i].page - prev.page; // pages between footer-bearing pages
    const numGap = withFooter[i].footer.n - prev.footer.n;
    if (samePageGap === 1 && numGap === 1) {
      curRun.push(withFooter[i]);
    } else {
      if (curRun.length > bestRun.length) bestRun = curRun;
      curRun = [withFooter[i]];
    }
  }
  if (curRun.length > bestRun.length) bestRun = curRun;

  const fired = bestRun.length >= minRun;
  return {
    fired,
    evidence: {
      totalPages: pages.length,
      pagesWithFooterMatch: withFooter.length,
      longestSequentialRun: bestRun.length,
      runStart: bestRun[0] ? { page: bestRun[0].page, footer: bestRun[0].footer.raw } : null,
      runEnd: bestRun.length ? { page: bestRun[bestRun.length - 1].page, footer: bestRun[bestRun.length - 1].footer.raw } : null,
      nullNote: bestRun.length >= 3 ? `chance run of length ${bestRun.length} under an i.i.d.-integer null is astronomically small; treated as intentional pagination` : undefined,
    },
  };
}

// RULE: equation-number-trailing-parens
// FAMILY: source-convention (kin to seed S3's "editor's lineation": a
//         trailing number is the edition's own reference apparatus, not
//         page content to read as prose) — here for numbered EQUATIONS
//         rather than verse lines.
//
// STATEMENT: these technical reports number displayed equations with a
// parenthesized integer (optionally with a trailing lowercase letter, e.g.
// "(14a)") set off by a large gap at the end of the equation's line — e.g.
// 19650003019 p29: "X = (1- z ) e   ...   (14)" and "...= tp-q   (15)";
// 19660017568 p18: "...(1.0 - 0.0)  (14)" and "...  (15)"; p22: "...(27)"
// and a boxed "K25 rad. = 1.231 x ... (28)". VERIFIED ACROSS TWO INDEPENDENT
// DOCUMENTS from different organizations (an AVCO-Everett 1964 report and a
// NASA-authored 1966 CR) — the convention is not one lab's house style.
//
// The formula CONTENT before the parenthesis is, on every example checked,
// badly garbled by pdftotext (stray exponent/subscript characters read as
// body text, symbols dropped or misread) — equations are NOT recoverable
// from the flat text and genuinely need a rendered look. But the trailing
// "(N)" equation NUMBER itself survives cleanly and can be trusted as a
// citation anchor even before that look happens — the two halves of the
// line carry very different reliability.
//
// Excludes Figure/Table caption numbering (e.g. "Figure (17)") by name — a
// closed table of caption-introducing words, not a regex alternation — so
// this rule is not confused with a caption number.
const CAPTION_WORDS = ["figure", "fig.", "fig", "table", "plate"];

export function detect(text, ctx = {}) {
  if (!text || typeof text !== "string") return { fired: false, evidence: {} };
  const lines = text.split("\n");
  const hits = [];
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const m = line.match(/^(.*?)( {3,})\(\s*(\d{1,3}[a-z]?)\s*\)\s*$/);
    if (!m) continue;
    const before = m[1].trim().toLowerCase();
    const isCaption = CAPTION_WORDS.some((w) => before.includes(w));
    if (isCaption) continue;
    hits.push({ line: i + 1, number: m[3], formulaFragment: m[1].trim().slice(-60) });
  }
  return {
    fired: hits.length > 0,
    evidence: {
      count: hits.length,
      examples: hits.slice(0, 6),
      reliability: "the (N) anchor is trustworthy; the formula text before it is pdftotext-garbled and needs a rendered look to actually read",
    },
  };
}

// RULE: cv-sidecar-coverage-gap
// FAMILY: extraction-artifact — about the *.cv.md SIDECAR specifically, not
//         the .txt. This is the user's rule #1 ("don't trust prior
//         extractions") applied one level up the pipeline: the CV sidecars
//         are themselves a prior extraction and must not be trusted either.
//
// STATEMENT: every *.cv.md sidecar sampled in live_priors/.../ntrs-white-papers
// covers AT MOST 6 pages (the frontmatter field is literally named
// "cv_look_pages: 6"), and every one inspected lists pages in ascending
// document order starting near the front (e.g. 19650003019: pages 2-7;
// 19880012630: pages 1,7,10,11,12,13 — front-loaded). MEASURED on
// 19650003019 (49 pages): re-scoring EVERY page with weirdFormattingScore
// finds pages later in the document (14, 15, 19, 22, 28, 34, 37, 39, 41 —
// figure/plot pages, confirmed by rendering p14) that score EQUAL TO OR
// HIGHER than the weakest of the 6 covered pages (score=1), yet were never
// looked at. The pipeline that produced these sidecars appears to walk
// pages in order and STOP once it has looked at `cv_look_pages` of them —
// so a long document's front matter can exhaust the whole budget before the
// pipeline ever reaches its figures, tables, or plots, which is exactly the
// content this bench's territory (NTRS-CV) cares about most.
//
// CONSEQUENCE: a *.cv.md's silence about a page is NOT evidence that the
// page reads cleanly as text — it may only mean the page-order budget ran
// out first. Any consumer of these sidecars should treat "not covered"
// as "unknown", never as "fine".
//
// `text` = the full fresh pdftotext -layout of the ORIGINAL document
// (form-feed-separated pages). `ctx.coveredPages` = the 1-indexed page
// numbers the *.cv.md sidecar actually covers (parsed from its own
// "### Page N" headers — never trust a frontmatter count field alone).
const BOX_DRAWING = /[─-╿▐-▟]/;
function weirdFormattingScore(pageText) {
  if (!pageText || typeof pageText !== "string") return { score: 0, signals: [] };
  const signals = [];
  const contentLines = pageText.split("\n").filter((l) => l.trim());
  if (contentLines.length < 3) return { score: 0, signals: [] };
  const tablePipes = contentLines.filter((l) => /[|¦│]/.test(l)).length;
  if (tablePipes / contentLines.length >= 0.5) signals.push("table_rows");
  const boxDraw = contentLines.filter((l) => BOX_DRAWING.test(l)).length;
  if (boxDraw / contentLines.length >= 0.2) signals.push("box_drawing");
  const shortLines = contentLines.filter((l) => l.trim().length > 0 && l.trim().length <= 12).length;
  if (shortLines / contentLines.length >= 0.4) signals.push("very_short_lines");
  const avgWords = contentLines.reduce((a, l) => a + l.trim().split(/\s+/).filter(Boolean).length, 0) / contentLines.length;
  if (avgWords <= 2.5) signals.push("sub_sentence_lines");
  const longRuns = contentLines.filter((l) => / {4,}/.test(l)).length;
  if (longRuns / contentLines.length >= 0.3) signals.push("wide_whitespace_runs");
  const widths = contentLines.map((l) => l.trim().length);
  const avgWidth = widths.reduce((a, b) => a + b, 0) / Math.max(1, widths.length);
  if (avgWidth > 0 && avgWidth <= 20 && contentLines.length >= 8) signals.push("narrow_column");
  return { score: signals.length, signals };
}

export function detect(text, ctx = {}) {
  const coveredPages = new Set(ctx.coveredPages ?? []);
  if (!text || typeof text !== "string" || coveredPages.size === 0) {
    return { fired: false, evidence: { skipped: true, reason: "ctx.coveredPages required" } };
  }
  const pages = text.split("\x0c");
  const scored = pages.map((p, i) => ({ page: i + 1, ...weirdFormattingScore(p) })).filter((p) => p.score >= 0 && p.signals);
  const covered = scored.filter((p) => coveredPages.has(p.page));
  const uncovered = scored.filter((p) => !coveredPages.has(p.page) && p.score > 0);
  if (!covered.length) return { fired: false, evidence: { reason: "no covered pages had any content/score" } };
  const minCoveredScore = Math.min(...covered.map((p) => p.score));
  const missedEqualOrHigher = uncovered.filter((p) => p.score >= minCoveredScore);

  return {
    fired: missedEqualOrHigher.length > 0,
    evidence: {
      coveredPageCount: coveredPages.size,
      minCoveredScore,
      totalPages: pages.length,
      uncoveredPagesWithAnySignal: uncovered.length,
      missedEqualOrHigherCount: missedEqualOrHigher.length,
      missedExamples: missedEqualOrHigher.slice(0, 10).map((p) => ({ page: p.page, score: p.score, signals: p.signals })),
    },
  };
}

// RULE: cv-box-text-density-separates-form-from-graphic
// FAMILY: cv-distilled
//
// STATEMENT: once a mechanical OpenCV box pass (eoreader7's
// native/eval/lavar/visual-detect.py) has run on a rendered page, the
// FRACTION of its detected boxes that carry non-empty OCR text mechanically
// separates a text-bearing FORM/flowchart page from a data-graphic page —
// no vision model needed to tell them apart, only the box list already on
// hand.
//
// MEASURED on this bench's own visual-detect.py runs (not assumed):
//   - Report Documentation Page (19880012630 p20, a ruled government form):
//     19/19 boxes carried real field text ("1. Report No.", "Bifurcations
//     in Unsteady Aerodynamics...", etc.) — text fraction 1.00.
//   - a multi-curve line chart with gridlines (19660017568 p10, "Effective
//     Reflectance Ratio"): 12 boxes, ALL empty — the detector is finding
//     the chart's own gridline-bounded cells, not text regions. Text
//     fraction 0.00.
//   - a single line-art diagram (19660017568 p26, "Figure (17) TypicalFin."):
//     1 box, empty (the whole figure's bounding contour). Text fraction
//     0.00.
// Every non-form page checked in this sample had a text fraction of 0;
// every form page checked had 1. Two data points on the "graphic" side is
// a small sample — treat the exact split as directional, not as a
// precision-measured boundary, until more graphic pages are checked.
//
// `text` here is the JSON STRING that visual-detect.py prints for one
// rendered page (this detector's input is that tool's output, not the
// page's OCR/pdftotext text — a disclosed, deliberate use of the `detect`
// interface's freedom to take any string). No network or model call
// happens inside this function; the CV pass already ran out-of-band to
// produce the JSON being read here.
export function detect(text, ctx = {}) {
  const minBoxes = ctx.minBoxes ?? 3;
  let data;
  try { data = JSON.parse(text); } catch { return { fired: false, evidence: { error: "not valid visual-detect.py JSON" } }; }
  const boxes = data.boxes ?? [];
  if (boxes.length < minBoxes) return { fired: false, evidence: { reason: "too few boxes to judge", boxCount: boxes.length } };
  const withText = boxes.filter((b) => b.text && b.text.trim().length > 0).length;
  const frac = withText / boxes.length;
  const predictsForm = frac >= 0.5;
  return {
    fired: predictsForm,
    evidence: {
      boxCount: boxes.length,
      textBearingBoxes: withText,
      textFraction: Number(frac.toFixed(2)),
      prediction: predictsForm ? "form/flowchart (text-bearing boxes)" : "chart or line-art graphic (empty boxes = gridlines or a single outline contour)",
    },
  };
}

// RULE: pg-crlf-universal [source-convention]
// Project Gutenberg serves ALL of its files (.txt AND -images.html) with
// CRLF ("\r\n") line endings, never bare LF. This is a byte-level fact
// about the SOURCE, not about any one work's content, and it matters
// because naive line-length math (line.length, regex $ anchors, trim())
// that doesn't strip \r first silently over-counts every line by one
// character and can shift wrap-width percentile calculations (see
// wrapped-prose-vs-verse.mjs) by exactly 1.
//
// Measured on originals (this swarm run): 100% CRLF across pg145.txt,
// pg100.txt, pg1322.txt, pg37134.txt, pg1342.txt, pg84.txt, and the
// -images.html of pg145 and pg100 (7 files, 0 to 269,269 newlines each,
// zero bare-LF lines in any of them).
//
// Null model: if a line's terminator were an independent fair coin flip
// (CRLF vs LF, p=0.5 each), observing k-of-k CRLF has probability 2^-k.
// For a 196,398-line file that is indistinguishable from zero; this is
// not a hand-set threshold, it is the coin-flip null itself.
//
// Contract: detect(text) where text is the candidate file's raw content
// (read WITHOUT any newline normalization -- fs.readFileSync(path,'utf8')
// is fine since utf8 decoding does not touch \r\n; do not use a readline
// interface that has already stripped \r).
export function detect(text, ctx = {}) {
  if (!text || text.length === 0) {
    return { fired: false, evidence: { note: "empty text" } };
  }
  const crlf = (text.match(/\r\n/g) || []).length;
  const bareLf = (text.match(/[^\r]\n/g) || []).length + (text.startsWith("\n") ? 1 : 0);
  const totalNl = (text.match(/\n/g) || []).length;
  const fired = crlf > 0 && bareLf === 0;
  // null probability of seeing this many CRLF by a fair per-line coin flip,
  // reported without underflowing to a bare 0.
  const k = Math.min(crlf, 1074); // 2^-1075 underflows a double
  const pNull = crlf > 1074 ? `< 1e-300 (k=${crlf})` : Math.pow(0.5, k);
  return {
    fired,
    evidence: {
      totalNewlines: totalNl,
      crlfCount: crlf,
      bareLfCount: bareLf,
      crlfFraction: totalNl ? crlf / totalNl : null,
      nullModel: "per-line terminator ~ fair coin(CRLF, LF), p=0.5 each",
      pUnderNull: pNull,
    },
  };
}

// RULE: pg-banner-intact [source-convention]
// An UNMODIFIED Project Gutenberg .txt (as PG itself serves it, before any
// extraction pipeline touches it) opens with a fixed-shape metadata header
// ("Title:", "Author:", "Release date: ... [eBook #NNNN]", "Language:", ...)
// and a "*** START OF THE PROJECT GUTENBERG EBOOK <TITLE> ***" banner, and
// closes with a mirrored "*** END OF THE PROJECT GUTENBERG EBOOK <TITLE> ***"
// banner followed by the standard license essay. The banner text between
// START and END is the work's actual body.
//
// Scope: this is the CURRENT (2021-era rewrite) PG banner format, confirmed
// on 5 originals fetched in this run (pg145, pg100, pg1322, pg37134, and
// pg1342/pg84 as contrast). It does NOT cover the older "*END*THE SMALL
// PRINT" boilerplate PG used before ~2021; a file carrying that older
// banner will not fire this detector (untested here -- flag as a gap).
//
// Measured (this run): all 6 fetched .txt originals have exactly one START
// and one END marker; the extracted [eBook #N] matches the URL's id in
// every case except none observed here are wrong -- id/title mismatches
// are the separate catalog-id-mismatch.mjs detector's job, run on this
// detector's extracted fields.
//
// Contract: detect(text) where text is a candidate ORIGINAL (pre-strip).
// Field names below are a fixed small closed set of PG's own labels; kept
// as an array (house rule: a closed list is a table, not a regex
// alternation baked inline).
const FIELD_LABELS = ["Title", "Author", "Release date", "Language", "Credits", "Contributor"];

export function detect(text, ctx = {}) {
  const startRe = /\*\*\* START OF THE PROJECT GUTENBERG EBOOK (.+?) \*\*\*/;
  const endRe = /\*\*\* END OF THE PROJECT GUTENBERG EBOOK (.+?) \*\*\*/;
  const startM = startRe.exec(text);
  const endM = endRe.exec(text);
  const fired = Boolean(startM && endM);

  const fields = {};
  for (const label of FIELD_LABELS) {
    const re = new RegExp("^" + label + ":\\s*(.+)$", "m");
    const m = re.exec(text);
    if (m) fields[label] = m[1].trim().replace(/\r$/, "");
  }
  const idMatch = /\[eBook #(\d+)\]/.exec(text);

  let bodyStartIdx = null, bodyEndIdx = null, bodyLength = null;
  if (fired) {
    bodyStartIdx = startM.index + startM[0].length;
    bodyEndIdx = endM.index;
    bodyLength = Math.max(0, bodyEndIdx - bodyStartIdx);
  }

  return {
    fired,
    evidence: {
      startBannerTitle: startM ? startM[1] : null,
      endBannerTitle: endM ? endM[1] : null,
      bannerTitlesMatch: startM && endM ? startM[1] === endM[1] : null,
      fields,
      ebookId: idMatch ? Number(idMatch[1]) : null,
      bodyByteLength: bodyLength,
      bodyStartCharIdx: bodyStartIdx,
      bodyEndCharIdx: bodyEndIdx,
      scopeNote: "current (post-2021) PG banner text only; older 'SMALL PRINT' banners untested",
    },
  };
}

// RULE: wrapped-prose-vs-verse [source-convention] -- re-grounds seed S2.
//
// A block of lines is HARD-WRAPPED PROSE (line breaks are a typesetting
// artifact of a fixed column width, not the author's line) when, for more
// than half its interior lines (every line but a block's last):
//   (a) len(line) + 1 + len(nextLine's first word) > W, i.e. the next word
//       could not have fit on this line at the work's own wrap width, AND
//   (b) the line does NOT end on closing punctuation (. ! ? ; : , -- or one
//       of those followed by a closing quote/bracket) -- a genuine forced
//       break usually lands mid-clause, not at a clause boundary.
// W is not a hand-set constant: it is THIS TEXT's own 95th-percentile
// interior line length, because measured wrap width varies by edition
// (see evidence below: 71/72/72/74-75 across four different PG works).
//
// Measured on originals (this run), block = paragraph (blank-line
// delimited), W = that work's own P95 interior line length:
//   Middlemarch      (pg145, prose)   W=71  conjunction=88.2% (20520/23268) -> FIRES (prose)
//   Pride & Prejudice(pg1342, prose)  W=72  conjunction=86.6% (7987/9228)   -> FIRES (prose)
//   Frankenstein     (pg84, prose)    W=74  conjunction=49.2% (2839/5766)  -> BORDERLINE, just under half
//   Leaves of Grass  (pg1322, verse)  W=74  conjunction=6.3%  (740/11692)  -> does NOT fire (verse, correctly)
// Frankenstein is a genuine near-miss for this rule's own positive class:
// its epistolary open (short salutation lines, dash-broken interjections)
// pushes many true wrap-breaks past the "ends without closing punctuation"
// test because they end in a dash or ellipsis this regex treats as
// closing. SCOPE: this conjunction test is reliable for descriptive/
// narrative prose (85-90% range observed); for dialogue- or letter-heavy
// prose it can sit near the 50% line, and the wouldNotFit fraction alone
// (also reported in evidence) should be read alongside the conjunction
// fraction rather than trusting the AND-gate in isolation.
//
// Also recorded as supporting evidence: PG's plain-text wrap NEVER
// hyphenates a split word (0 of 28,044 non-blank Middlemarch lines end in
// "-"), unlike a justified/typeset source -- a text with real end-of-line
// hyphenation is a different medium (print-justified, not PG-reflowed) and
// this detector's wouldNotFit arithmetic would need a hyphen-rejoin step
// first, which it deliberately does not attempt.
//
// Contract: detect(text, ctx) -- text is one candidate region (a chapter,
// a poem, or a whole work); ctx.W optionally overrides the auto-measured
// wrap width (skip auto-measurement when comparing two different texts on
// one shared W).
const CLOSING_RE = /["'’”)\]]?[.!?;:,—-]["'’”)\]]?$/;

function stripCr(l) {
  return l.replace(/\r$/, "");
}
function paragraphBlocks(lines) {
  const blocks = [];
  let cur = [];
  for (const l of lines) {
    if (l.trim() === "") {
      if (cur.length) blocks.push(cur);
      cur = [];
    } else cur.push(l);
  }
  if (cur.length) blocks.push(cur);
  return blocks;
}
function pctile(arr, p) {
  if (!arr.length) return 0;
  const s = [...arr].sort((a, b) => a - b);
  return s[Math.floor((p / 100) * (s.length - 1))];
}

export function detect(text, ctx = {}) {
  const lines = text.split("\n").map(stripCr);
  const blocks = paragraphBlocks(lines);
  const allInteriorLens = [];
  for (const b of blocks) for (let i = 0; i < b.length - 1; i++) allInteriorLens.push(b[i].length);
  const W = ctx.W || pctile(allInteriorLens, 95);

  let interiorTotal = 0, both = 0, wouldNotFitCount = 0, endsOpenCount = 0, hyphenBreaks = 0;
  for (const b of blocks) {
    for (let i = 0; i < b.length - 1; i++) {
      interiorTotal++;
      const line = b[i];
      const next = b[i + 1];
      const nextFirstWord = next.trim().split(/\s+/)[0] || "";
      const wouldNotFit = line.length + 1 + nextFirstWord.length > W;
      const endsOpen = !CLOSING_RE.test(line.trim());
      if (wouldNotFit) wouldNotFitCount++;
      if (endsOpen) endsOpenCount++;
      if (wouldNotFit && endsOpen) both++;
      if (/-$/.test(line)) hyphenBreaks++;
    }
  }
  const conjunctionFrac = interiorTotal ? both / interiorTotal : 0;
  const fired = conjunctionFrac > 0.5;

  return {
    fired,
    evidence: {
      W,
      interiorTotal,
      wouldNotFitFraction: interiorTotal ? wouldNotFitCount / interiorTotal : null,
      endsOpenFraction: interiorTotal ? endsOpenCount / interiorTotal : null,
      conjunctionFraction: conjunctionFrac,
      hyphenatedLineBreaks: hyphenBreaks,
      classification: fired ? "wrapped-prose" : "not-wrapped-prose (verse or too-short sample)",
    },
  };
}

// RULE: relative-indentation [source-convention] -- re-grounds seed S10.
//
// Indentation is the EDITION's before it is the author's, and its absolute
// value carries no fixed meaning across works: read it relative to the
// work's OWN modal (most common) leading-space count, then treat any band
// ABOVE that modal value as a structural marker whose meaning is local to
// this work.
//
// Measured on originals (this run), non-blank lines, leading-space count:
//   Leaves of Grass (pg1322, full poem body): modal=2 (74.9%, 10619/14171);
//     secondary bands at 6 (2674) and 7 (436) = modal+4 / modal+5, which
//     are hanging run-over continuations of a verse line too long for one
//     line -- NOT a different author intent, a compositor's wrap-within-
//     verse convention. A third band at 0 (418, 2.9%) is poem/section
//     TITLE lines ("BOOK I. INSCRIPTIONS"), which sit BELOW the modal, not
//     above it -- titles are unindented headings, not indented verse.
//   Shakespeare's Sonnets (pg100, lines 87-2861, all 154 sonnets read
//     positionally 1-14 within each sonnet): modal=0 for lines 1-12 (the
//     three quatrains, 100% for 154/154 sonnets on lines 1-10, 153/154 on
//     11-12), and the closing couplet (lines 13-14) sits at modal+2 (152-
//     153/154). The ONE exception is Sonnet 126, which is textually only
//     12 lines (no couplet) -- a known edition fact, not a detector miss.
// CONCLUSION (narrows S10): the absolute indent number that marks "above
// modal" is NOT stable across works (+2 in the Sonnets marks a couplet;
// +4/+5 in Whitman marks a wrapped verse run-over) -- only the RELATION
// "some lines sit above this work's own modal indent, and that band is a
// structural signal" transfers. Do not hard-code "+2 spaces = verse" or
// "+4 = run-over" as a corpus-wide constant.
//
// Contract: detect(text, ctx) -- text is one work's verse/structured region
// (strip prose front/back matter first, e.g. via pg-banner-intact.mjs).
// ctx.positionalPeriod (integer, optional): if the text is composed of
// fixed-length stanzas (e.g. 14-line sonnets) separated by a lone-number
// line, pass the stanza length to get the line-position-within-stanza
// breakdown in addition to the flat histogram. Firing requires at least
// two distinct indent levels attested >=3 times each -- a single uniform
// indent (or one-off noise) is not "relative structure."
//
// HONEST CAVEAT (measured, not assumed): this "fired" gate is a weak
// discriminator on its own. Run against Middlemarch's PROSE body (pg145,
// 28,044 non-blank lines) it ALSO fires -- modal=0 at 99.5%, but a real
// secondary band at indent=4 (91 lines) and indent=1 (52 lines), from
// occasional inset quotations/lists inside otherwise flush-left prose.
// Any sufficiently long real book will incidentally contain a few inset
// lines, so fired=true does not by itself mean "this is verse" or "this
// work uses meaningful relative indentation" -- the useful output is the
// returned histogram/positional breakdown for a caller to interpret
// against what KIND of block this is, not the boolean alone. A genuine
// not-fire case is more reliably produced by an insufficient SAMPLE (a
// short excerpt with too few lines to reach the >=3 floor at any second
// level) than by a text that truly has no secondary indent at all.
function stripCr(l) {
  return l.replace(/\r$/, "");
}

export function detect(text, ctx = {}) {
  const lines = text.split("\n").map(stripCr);
  const hist = {};
  let nonBlank = 0;
  for (const l of lines) {
    if (l.trim() === "") continue;
    nonBlank++;
    const n = (l.match(/^( *)/) || ["", ""])[1].length;
    hist[n] = (hist[n] || 0) + 1;
  }
  const sorted = Object.entries(hist).map(([k, v]) => [Number(k), v]).sort((a, b) => b[1] - a[1]);
  const modal = sorted.length ? sorted[0][0] : 0;
  const modalCount = sorted.length ? sorted[0][1] : 0;
  const levelsAtLeast3 = sorted.filter(([, v]) => v >= 3);
  const fired = levelsAtLeast3.length >= 2;

  let positional = null;
  if (ctx.positionalPeriod) {
    const period = ctx.positionalPeriod;
    const posIndent = Array.from({ length: period }, () => []);
    let pos = -1;
    let active = false;
    for (const l of lines) {
      const t = l.trim();
      if (/^\d+$/.test(t)) {
        pos = 0;
        active = true;
        continue;
      }
      if (t === "") continue;
      if (active && pos >= 0 && pos < period) {
        posIndent[pos].push((l.match(/^( *)/) || ["", ""])[1].length);
        pos++;
      }
    }
    positional = posIndent.map((arr, i) => {
      const h = {};
      for (const v of arr) h[v] = (h[v] || 0) + 1;
      return { position: i + 1, n: arr.length, distribution: h };
    });
  }

  return {
    fired,
    evidence: {
      nonBlankLines: nonBlank,
      modalIndent: modal,
      modalFraction: nonBlank ? modalCount / nonBlank : null,
      histogram: Object.fromEntries(sorted),
      levelsWithAtLeast3: levelsAtLeast3,
      positional,
    },
  };
}

// RULE: drama-speaker-label [source-convention] -- re-grounds seed S11.
//
// A short (<=3 words), ALL-CAPS, period-terminated line that recurs many
// times across a text is a drama speaker cue, not a heading or a shout.
// Measured on the ORIGINAL pg100.txt (Complete Works of Shakespeare, no
// prior extraction involved): 1007 distinct candidate strings, 31,816
// total occurrences; top: FALSTAFF. x472, KING. x455, DUKE. x369,
// HAMLET. x358, KING HENRY. x352, BRUTUS. x283 ... This matches the seed's
// cited HAMLET. x358 exactly, now grounded on source bytes rather than a
// prior extraction.
//
// Threshold, stated honestly: "<=3 words" and "recurs >=20 times" are
// hand-set, not measured nulls, because there is no natural content-null
// for "how many words are in a play character's name." Justification: English
// character/role names are essentially never 4+ words, and below ~20
// recurrences a short ALL-CAPS period-terminated line (e.g. a one-off
// interjection like "SILENCE.") could plausibly be coincidental; above it,
// exact-string recurrence at that rate is not explainable except as a
// structural cue. The full recurrence count is always reported so a
// caller can apply a stricter or looser bar without rerunning.
//
// Contract: detect(text). Works on any prose/drama text; on non-drama
// prose (Middlemarch, Leaves of Grass) it should find zero or only
// low-count candidates -- see held-out targets.
export function detect(text, ctx = {}) {
  const minRecurrence = ctx.minRecurrence ?? 20;
  const maxWords = ctx.maxWords ?? 3;
  const lines = text.split("\n").map((l) => l.replace(/\r$/, ""));
  const counts = new Map();
  for (const l of lines) {
    const t = l.trim();
    if (!t || t.length > 40 || !t.endsWith(".")) continue;
    const letters = t.replace(/[^A-Za-z]/g, "");
    if (!letters || letters !== letters.toUpperCase() || /[a-z]/.test(letters)) continue;
    const words = t.replace(/\.$/, "").split(/\s+/);
    if (words.length > maxWords) continue;
    counts.set(t, (counts.get(t) || 0) + 1);
  }
  const sorted = [...counts.entries()].sort((a, b) => b[1] - a[1]);
  const qualifying = sorted.filter(([, n]) => n >= minRecurrence);
  const fired = qualifying.length > 0;
  return {
    fired,
    evidence: {
      distinctCandidates: sorted.length,
      totalCandidateOccurrences: sorted.reduce((a, [, n]) => a + n, 0),
      thresholdMinRecurrence: minRecurrence,
      thresholdMaxWords: maxWords,
      thresholdJustification: "no natural null for name length/recurrence; hand-set from observed English drama-label shape",
      top: sorted.slice(0, 10),
      qualifyingCount: qualifying.length,
    },
  };
}

// RULE: drama-stage-direction [source-convention] -- re-grounds seed S12.
//
// A bracketed, underscore-italicized span "[_...._]" that recurs is a stage
// direction. Measured on ORIGINAL pg100.txt: "[_Exeunt._]" x536 and
// "[_Exit._]" x508 -- matching the seed's cited counts exactly, now on
// source bytes. Two distinct SHAPES were measured and both are reported
// separately because they are not interchangeable:
//   - whole-line directions (the bracket is the entire line, trimmed):
//     2915 of 3463 bracket-bearing lines (84.2%) -- e.g. "[_Dies._]",
//     capitalized, period inside the closing "._]".
//   - inline directions (the bracket shares a line with dialogue): 548
//     (15.8%) -- e.g. "[_kneeling_]", often lowercase, no trailing period,
//     e.g. "Pardon, my lord [_kneeling_], for me and for my tidings."
// A detector that only matches whole lines will silently miss 1 in 6
// stage directions in this text; this detector reports both.
//
// Contract: detect(text).
export function detect(text, ctx = {}) {
  const minRecurrence = ctx.minRecurrence ?? 3;
  const lines = text.split("\n").map((l) => l.replace(/\r$/, ""));
  const anyBracketRe = /\[_[^_][^\]]*_\]/;
  const wholeLineRe = /^\s*\[_[^_][^\]]*_\]\s*$/;
  const counts = new Map();
  let anyCount = 0, wholeCount = 0;
  for (const l of lines) {
    if (!anyBracketRe.test(l)) continue;
    anyCount++;
    const isWhole = wholeLineRe.test(l.trim());
    if (isWhole) {
      wholeCount++;
      const t = l.trim();
      counts.set(t, (counts.get(t) || 0) + 1);
    }
  }
  const sorted = [...counts.entries()].sort((a, b) => b[1] - a[1]);
  const qualifying = sorted.filter(([, n]) => n >= minRecurrence);
  const fired = qualifying.length > 0;
  return {
    fired,
    evidence: {
      linesWithAnyBracketDirection: anyCount,
      wholeLineDirections: wholeCount,
      inlineOrMixedDirections: anyCount - wholeCount,
      inlineFraction: anyCount ? (anyCount - wholeCount) / anyCount : null,
      top: sorted.slice(0, 10),
      thresholdMinRecurrence: minRecurrence,
    },
  };
}

// RULE: quote-style-and-apostrophe-ambiguity [script-convention]
//
// (1) Quote-character style is a PER-FILE choice in this corpus, not a
// corpus-wide constant: most David-Widger-credited PG texts use curly
// Unicode quotes (U+2018/2019/201C/201D) almost exclusively, but the
// Distributed-Proofreaders-credited pg37134 (Elements of Style, 2011) uses
// straight ASCII quotes/apostrophes as its house style. Measured on
// originals:
//   pg145  (Middlemarch):        curly-close 3702, ascii-apos 0
//   pg100  (Shakespeare):        curly-close 26344, ascii-apos 1
//   pg1322 (Leaves of Grass):    curly-close 2382, ascii-apos 0
//   pg1342 (Pride & Prejudice):  curly-close 767,  ascii-apos 0
//   pg84   (Frankenstein):       curly-close 150,  ascii-apos 0
//   pg37134(Elements of Style):  curly-close 6,    ascii-apos 53, ascii-dquote 144
// A pipeline that assumes "PG = curly quotes" and hard-codes U+2019 will
// silently miss every apostrophe in a straight-quote file like pg37134.
//
// (2) WITHIN a curly-quote file, U+2019 is overloaded: it is used both as
// an apostrophe (contraction/possessive: "don't", "Dorothea's") and as a
// closing single-quotation mark. Measured on originals (classifying each
// U+2019 by its immediate neighbors: letter-before+letter-after =
// contraction-shaped; letter/punct-before + whitespace/quote/EOL-after =
// closing-quote-shaped):
//   pg145:  92.0% contraction-shaped, 6.5% closing-quote-shaped
//   pg100:  77.6% contraction-shaped, 11.2% closing-quote-shaped
//   pg1322: 95.5% contraction-shaped, 3.2% closing-quote-shaped
// A rule that treats every U+2019 as "just an apostrophe, discard it" will
// discard 3-11% real closing-quote boundaries (breaking nested-quotation
// parsing); a rule that treats every U+2019 as "end of quoted span" will
// break thousands of contractions.
//
// Contract: detect(text).
export function detect(text, ctx = {}) {
  const curlyClose = (text.match(/’/g) || []).length;
  const curlyOpen = (text.match(/‘/g) || []).length;
  const curlyDquote = (text.match(/[“”]/g) || []).length;
  const asciiApos = (text.match(/'/g) || []).length;
  const asciiDquote = (text.match(/"/g) || []).length;

  const curlyTotal = curlyClose + curlyOpen + curlyDquote;
  const asciiTotal = asciiApos + asciiDquote;
  let dominant = "none";
  if (curlyTotal > asciiTotal * 3) dominant = "curly";
  else if (asciiTotal > curlyTotal * 3) dominant = "ascii";
  else if (curlyTotal || asciiTotal) dominant = "mixed";

  let apostropheAmbiguity = null;
  if (curlyClose >= 10) {
    let contraction = 0, closingQuote = 0;
    const re = /’/g;
    let m;
    while ((m = re.exec(text))) {
      const i = m.index;
      const before = text[i - 1] || "";
      const after = text[i + 1] || "";
      if (/[A-Za-z]/.test(before) && /[A-Za-z]/.test(after)) contraction++;
      else if (/[A-Za-z.,!?]/.test(before) && /[\s\r\n"”]|^$/.test(after || "")) closingQuote++;
    }
    apostropheAmbiguity = {
      total: curlyClose,
      contractionShaped: contraction,
      contractionFraction: contraction / curlyClose,
      closingQuoteShaped: closingQuote,
      closingQuoteFraction: closingQuote / curlyClose,
    };
  }

  const fired = dominant === "curly" && apostropheAmbiguity && apostropheAmbiguity.closingQuoteShaped >= 10 && apostropheAmbiguity.contractionShaped >= 10;

  return {
    fired,
    evidence: {
      curlyClose, curlyOpen, curlyDquote, asciiApos, asciiDquote,
      dominantQuoteStyle: dominant,
      apostropheAmbiguity,
    },
  };
}

// RULE: title-abbreviation-period [script-convention]
//
// A period after an English title/rank abbreviation (Mr., Mrs., Dr., St.,
// Capt., ...) is not a sentence boundary, and -- this is the part worth
// measuring, not assuming -- the word FOLLOWING it gives almost no signal
// to tell the two apart: in English, both a genuine sentence-final period
// and a title-abbreviation period are followed by a capitalized word
// essentially all the time (a new sentence starts with a capital; a title
// is followed by a capitalized proper name). Measured on originals:
//   Middlemarch (pg145):          2432 title-abbreviation periods, 99.84%
//                                  followed by a capital letter.
//   Pride and Prejudice (pg1342): 1074 title-abbreviation periods, 98.04%
//                                  followed by a capital letter.
//   Leaves of Grass (pg1322):     6 (all "St.", geographic e.g. "St.
//                                  Domingo" -- Whitman's lyric voice
//                                  rarely addresses a "Mr." or "Mrs.").
//   Elements of Style (pg37134):  8 (6 "Mr.", 1 "Mrs.", 1 "St." -- a
//                                  style manual, not social narrative).
// HONEST RECALIBRATION: presence is near-universal in English prose of
// any real length -- even a lyric poem and a grammar manual clear a
// naive "at least a few" bar. The count is NOT zero/nonzero so much as
// three orders of magnitude by genre (6-8 vs 1000-2400): social-address
// narrative prose is what drives the count up, not English as a script
// per se. Do not expect a clean not-fire on English text; expect a
// clean LOW count instead, and read the number, not just the boolean.
// A "period + space + capital = sentence end" segmenter (the naive rule)
// therefore cannot distinguish these two cases by local case alone --
// it needs the closed list of titles as a lookup table, not a smarter
// regex. That is what this detector is: TITLES below is a Set (house
// rule: a closed list of words is a table, never a regex alternation)
// and firing means "text contains enough of these to make naive
// period-splitting unsafe here", with the actual list of abbreviations it
// found so a caller can subtract them from a sentence-boundary count.
//
// Contract: detect(text).
const TITLES = new Set([
  "Mr.", "Mrs.", "Ms.", "Dr.", "St.", "Messrs.", "Mme.", "Mons.",
  "Capt.", "Col.", "Gen.", "Lt.", "Maj.", "Rev.", "Prof.", "Esq.",
  "Jr.", "Sr.", "Hon.", "Sgt.",
]);

export function detect(text, ctx = {}) {
  const minCount = ctx.minCount ?? 5;
  const perTitle = new Map();
  let total = 0, capFollows = 0;
  for (const title of TITLES) {
    const esc = title.replace(".", "\\.");
    const re = new RegExp("(^|[^A-Za-z])" + esc + "( )([A-Za-z])", "g");
    let m, n = 0, cap = 0;
    while ((m = re.exec(text))) {
      n++;
      if (/[A-Z]/.test(m[3])) cap++;
    }
    if (n > 0) perTitle.set(title, n);
    total += n;
    capFollows += cap;
  }
  const fired = total >= minCount;
  return {
    fired,
    evidence: {
      totalAbbreviationPeriods: total,
      capitalFollowsFraction: total ? capFollows / total : null,
      note: "capital-follows fraction near 1.0 for BOTH abbreviation and true sentence-final periods in English -- local case is not discriminating, the closed list is required",
      perTitleCounts: Object.fromEntries(perTitle),
      thresholdMinCount: minCount,
    },
  };
}

// RULE: banner-stripped-interior-verbatim [extraction-artifact]
//
// The live_priors gutenberg ingestion's ONLY transformation on these four
// works was: strip PG's metadata header + START banner + END banner +
// license footer, trim leading/trailing blank lines, and drop the final
// trailing newline. The interior body -- every wrap, every _italic_
// underscore, every CRLF, every indentation -- was carried over byte for
// byte. Measured (diff of {original body between banners, blank-trimmed}
// vs {live_priors copy}), all four re-fetched originals in this run:
//   pg145   (Middlemarch):        33,285 original body lines vs 33,277
//     copy lines; diff = only the 4 leading + 5 trailing blank lines. 0
//     interior differences.
//   pg1322  (Leaves of Grass, the CONTENT actually filed as "pg2397"):
//     17,863 vs 17,859 lines; diff = only edge blank lines. 0 interior
//     differences.
//   pg37134 (Elements of Style): 2,381 vs 2,369 lines (2369 = 2381 minus
//     4 leading + a trailing run, after subtracting the copy's own 8-line
//     YAML frontmatter block); 0 interior differences once frontmatter is
//     excluded.
//   pg100   (Complete Works of Shakespeare, read from live_priors git
//     history via `git show HEAD:...pg100...txt`, since it is deleted in
//     the working tree): 196,022 vs 196,014 lines; diff = only edge blank
//     lines (plus the copy's missing final newline). 0 interior
//     differences across the ENTIRE 196k-line, 5.6MB body.
// This is a POSITIVE finding about extraction fidelity for this specific
// corpus/pipeline -- it argues these four .txt bodies can be trusted at
// the byte level once the banner is accounted for. It does NOT generalize
// to other territories (the seed file's S4-S9 show heavy corruption on
// Wikisource/GRETIL/scanned sources) or even to every Gutenberg file in
// this same live_priors tree -- see catalog-id-mismatch.mjs for the one
// real defect found in this territory (a wrong ID in a filename, not a
// content corruption).
//
// Contract: detect(candidateText, ctx) -- candidateText is the extraction
// under test. ctx.original (string, the freshly fetched PG original),
// if supplied, is used for an exact comparison; without it the detector
// can only report the weaker "looks banner-stripped" heuristic (no PG
// banner strings present, no license-paragraph fingerprint present).
const LICENSE_FINGERPRINT = "Section 5. General Information About Project Gutenberg";
function trimBlankEdges(lines) {
  let a = 0, b = lines.length;
  while (a < b && lines[a].trim() === "") a++;
  while (b > a && lines[b - 1].trim() === "") b--;
  return lines.slice(a, b);
}
function stripYamlFrontmatter(lines) {
  if (lines[0] && lines[0].trim() === "---") {
    for (let i = 1; i < lines.length; i++) {
      if (lines[i].trim() === "---") return lines.slice(i + 1);
    }
  }
  return lines;
}

export function detect(candidateText, ctx = {}) {
  const hasStartBanner = /\*\*\* START OF THE PROJECT GUTENBERG EBOOK/.test(candidateText);
  const hasEndBanner = /\*\*\* END OF THE PROJECT GUTENBERG EBOOK/.test(candidateText);
  const hasLicenseText = candidateText.includes(LICENSE_FINGERPRINT);
  const looksBannerStripped = !hasStartBanner && !hasEndBanner && !hasLicenseText;

  let exactInteriorMatch = null, originalBodyLines = null, candidateBodyLines = null, crlfPreserved = null;
  if (ctx.original) {
    const startM = /\*\*\* START OF THE PROJECT GUTENBERG EBOOK.*?\*\*\*/.exec(ctx.original);
    const endM = /\*\*\* END OF THE PROJECT GUTENBERG EBOOK.*?\*\*\*/.exec(ctx.original);
    if (startM && endM) {
      const originalBody = ctx.original.slice(startM.index + startM[0].length, endM.index);
      const origLines = trimBlankEdges(originalBody.split("\n").map((l) => l.replace(/\r$/, "")));
      let candLines = trimBlankEdges(candidateText.split("\n").map((l) => l.replace(/\r$/, "")));
      candLines = stripYamlFrontmatter(candLines);
      candLines = trimBlankEdges(candLines);
      originalBodyLines = origLines.length;
      candidateBodyLines = candLines.length;
      exactInteriorMatch = origLines.length === candLines.length && origLines.every((l, i) => l === candLines[i]);
      crlfPreserved = /\r\n/.test(candidateText);
    }
  }

  const fired = ctx.original ? Boolean(exactInteriorMatch) : looksBannerStripped;
  return {
    fired,
    evidence: {
      hasStartBanner, hasEndBanner, hasLicenseText, looksBannerStripped,
      exactInteriorMatch, originalBodyLines, candidateBodyLines, crlfPreserved,
      mode: ctx.original ? "exact-comparison" : "heuristic-only (no ctx.original supplied)",
    },
  };
}

// RULE: catalog-id-mismatch [extraction-artifact]
//
// THE CONCRETE DEFECT THIS DETECTOR CATCHES (found in this run): live_priors
// files 01-literature-books/gutenberg/pg2397_Leaves_of_Grass_by_Whitman.txt
// and its .eot.json sidecar are filed under Gutenberg id 2397, but PG's
// eBook #2397 is actually Helen Keller's "The Story of My Life" --
// confirmed by fetching https://www.gutenberg.org/cache/epub/2397/pg2397.txt
// (original header: "Title: The Story of My Life", "Author: Helen
// Keller"). The CONTENT of the live_priors file is genuinely Whitman's
// Leaves of Grass -- it matches PG id 1322 byte-for-byte (see
// banner-stripped-interior-verbatim.mjs) -- so this is a labeling error
// (wrong id baked into a filename during a fetch, years before this run),
// not a text-corruption error. A pipeline that trusts the filename's id to
// look up "the real source" for provenance/citation purposes would cite
// the wrong Project Gutenberg page.
//
// This detector is meant to run on a FRESHLY FETCHED ORIGINAL (before any
// banner-stripping) against the id/title the caller intended to fetch, so
// it catches this failure mode at ingestion time rather than downstream.
//
// Contract: detect(originalText, ctx) where originalText still carries its
// PG header (has "[eBook #N]" and "Title:"), and ctx.claimedId (number)
// and/or ctx.claimedTitle (string, loose match) is what the caller
// intended. fired=true means MISMATCH (a problem); fired=false with
// evidence.verified=true means the id and title both check out.
function normalizeTitle(s) {
  return s.toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
}

export function detect(originalText, ctx = {}) {
  const idMatch = /\[eBook #(\d+)\]/.exec(originalText);
  const titleMatch = /^Title:\s*(.+)$/m.exec(originalText);
  const actualId = idMatch ? Number(idMatch[1]) : null;
  const actualTitle = titleMatch ? titleMatch[1].trim().replace(/\r$/, "") : null;

  if (actualId === null) {
    return { fired: false, evidence: { note: "no [eBook #N] found -- this looks like an already-stripped body, not a fresh original; run this check before stripping" } };
  }

  let idMismatch = null, titleMismatch = null;
  if (ctx.claimedId !== undefined) idMismatch = Number(ctx.claimedId) !== actualId;
  if (ctx.claimedTitle) {
    const a = normalizeTitle(actualTitle || "");
    const b = normalizeTitle(ctx.claimedTitle);
    titleMismatch = !(a.includes(b) || b.includes(a));
  }
  const fired = Boolean(idMismatch || titleMismatch);
  return {
    fired,
    evidence: {
      actualId, actualTitle,
      claimedId: ctx.claimedId ?? null,
      claimedTitle: ctx.claimedTitle ?? null,
      idMismatch, titleMismatch,
      verified: idMismatch === false && (titleMismatch === false || titleMismatch === null),
    },
  };
}

// RULE: illustration-count-predicts-cv [cv-distilled]
//
// The plain-text "[Illustration" placeholder count predicts, without
// opening any image, WHETHER a page/HTML-aware render would show interior
// images at all, and roughly how many -- but NOT always the exact file
// count, which this run's own measurement falsifies at the exact-match
// level (kept here deliberately, rather than patched away, because that
// falsification is itself the finding).
//
// Measured on originals (this run), .txt placeholder count vs <img> count
// in the corresponding -images.html:
//   pg84   (Frankenstein):  0 tags, 0 <img> -- exact match, no plates.
//   pg2397 (Story of My Life): 0 tags, 0 <img> -- exact match.
//   pg145, pg100, pg1322 (Middlemarch, Shakespeare, Leaves of Grass):
//     0 "[Illustration" tags, exactly 1 <img> each (images/cover.jpg) --
//     matches once the cover is excluded by filename. These three
//     Tschichold-archon works carry NO interior illustrations in this PG
//     digitization; a CV call over their interior pages would find
//     nothing a text scan didn't already rule out.
//   pg37134 (Elements of Style): 0 tags, 1 <img> -- but that image is
//     "images/logo.png" (a Distributed-Proofreaders production credit,
//     not a cover) -- this detector's filename-based cover exclusion
//     (/cover\.(jpg|jpeg|png)/i) does NOT recognize it, so it reports a
//     mismatch (fired=false) where the right call is "still nothing
//     interior". NARROWS the rule: "exclude anything matching a cover
//     filename" does not generalize to every non-content front-matter
//     image; a production-logo convention needs its own signature.
//   pg1342 (Pride and Prejudice): 162 "[Illustration" tags in .txt, but
//     164 <img> tags (163 once the real cover.jpg is excluded) -- a
//     genuine undercount, not a bug in the regex. The HTML renders at
//     least 60 illustrations as a STACKED PAIR of image files each
//     ("images/i_501_a.jpg" + "images/i_501_b.png", etc. -- 120 files for
//     60 illustrations, a duotone/overlay technique), and the remaining
//     gap is consistent with a few purely decorative headpieces that
//     carry no "[Illustration]" text tag at all. FALSIFIES exact-count
//     prediction; the safe claim is presence/absence and order-of-
//     magnitude, not an exact file count.
// Net: this lets the archon reliably skip a CV call when the placeholder
// count is 0 AND treat "0 real content images" as still true even when a
// lone production/cover image exists -- but it must NOT budget an exact
// image count from the tag count alone once illustrations are present.
//
// Contract: detect(text, ctx) -- text is the plain .txt; ctx.imagesHtml
// (optional) is the -images.html content, used to confirm the prediction
// against an actual count instead of only asserting the zero-case.
export function detect(text, ctx = {}) {
  const illustrationMatches = text.match(/\[Illustration\b/g) || [];
  const textCount = illustrationMatches.length;

  let htmlImgCount = null, htmlNonCoverImgCount = null, matches = null;
  if (typeof ctx.imagesHtml === "string") {
    const imgTags = ctx.imagesHtml.match(/<img\b[^>]*>/g) || [];
    htmlImgCount = imgTags.length;
    htmlNonCoverImgCount = imgTags.filter((t) => !/cover\.(jpg|jpeg|png)/i.test(t)).length;
    matches = textCount === htmlNonCoverImgCount;
  }

  const zeroCasePrediction = textCount === 0;
  const fired = ctx.imagesHtml ? Boolean(matches) : zeroCasePrediction;

  return {
    fired,
    evidence: {
      illustrationTagCountInText: textCount,
      htmlImgCount, htmlNonCoverImgCount,
      predictionConfirmedAgainstHtml: matches,
      recommendation: zeroCasePrediction
        ? "0 placeholders -- skip a CV/page-image call over the interior; at most a cover image exists"
        : `${textCount} placeholders -- expect exactly this many image interruptions in a page render`,
    },
  };
}

// RULE gutenberg-id-drift (family: extraction-artifact)
// A corpus file's filename-embedded Gutenberg ebook id (or a manifest's claimed
// title/author/language for that id) must never be trusted. Every Project
// Gutenberg plaintext self-declares its own identity in a fixed, parseable
// place: either the modern "Title:" / "Author:" / "Language:" header block,
// or (for every edition, old or new) the very first line
// "The Project Gutenberg eBook of <TITLE>" / "The Project Gutenberg Etext of <TITLE>",
// or the "*** START OF THE PROJECT GUTENBERG EBOOK <TITLE> ***" marker line.
// This detector extracts that self-declared identity and compares it against
// what the caller expected (e.g. from a corpus manifest or filename), never
// trusting the filename/id itself.
//
// Pure JS, no network. detect(text, ctx) where ctx may carry:
//   ctx.expectedTitle, ctx.expectedAuthor, ctx.expectedLanguage (any subset)

function normalize(s) {
  return (s || '')
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[̀-ͯ]/g, '') // strip accents so "Aeneidos"~"aeneidos", "Böse"~"bose" compare robustly
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

function extractDeclaredIdentity(text) {
  const head = text.slice(0, 4000); // header always lives in the first few KB
  const out = { title: null, author: null, language: null, openingLine: null, startMarkerTitle: null };

  const mTitle = head.match(/^Title:\s*(.+)$/m);
  if (mTitle) out.title = mTitle[1].trim();
  const mAuthor = head.match(/^Author:\s*(.+)$/m);
  if (mAuthor) out.author = mAuthor[1].trim();
  const mLang = head.match(/^Language:\s*(.+)$/m);
  if (mLang) out.language = mLang[1].trim();

  const mOpen = head.match(/^The Project Gutenberg (?:eBook|EBook|Etext|eText) of (.+?)\s*$/m);
  if (mOpen) out.openingLine = mOpen[1].trim();

  const mStart = text.match(/\*\*\* START OF (?:THE|THIS) PROJECT GUTENBERG (?:EBOOK|ETEXT)\s+(.+?)\s*\*\*\*/i);
  if (mStart) out.startMarkerTitle = mStart[1].trim();

  // Fallback title if no "Title:" field (older etexts): opening line or start-marker line.
  if (!out.title) out.title = out.openingLine || out.startMarkerTitle || null;

  return out;
}

function substringMatch(expected, declaredCandidates) {
  if (!expected) return { checked: false, matched: null };
  const nExp = normalize(expected);
  if (!nExp) return { checked: false, matched: null };
  for (const cand of declaredCandidates) {
    if (!cand) continue;
    const nCand = normalize(cand);
    if (!nCand) continue;
    if (nCand.includes(nExp) || nExp.includes(nCand)) return { checked: true, matched: true, against: cand };
  }
  return { checked: true, matched: false, against: declaredCandidates.filter(Boolean) };
}

export function detect(text, ctx = {}) {
  const declared = extractDeclaredIdentity(text);
  const mismatches = [];
  const checks = {};

  if (ctx.expectedTitle) {
    const r = substringMatch(ctx.expectedTitle, [declared.title, declared.openingLine, declared.startMarkerTitle]);
    checks.title = r;
    if (r.checked && !r.matched) mismatches.push({ field: 'title', expected: ctx.expectedTitle, declared: declared.title });
  }
  if (ctx.expectedAuthor) {
    const r = substringMatch(ctx.expectedAuthor, [declared.author]);
    checks.author = r;
    if (r.checked && !r.matched) mismatches.push({ field: 'author', expected: ctx.expectedAuthor, declared: declared.author });
  }
  if (ctx.expectedLanguage) {
    const r = substringMatch(ctx.expectedLanguage, [declared.language]);
    checks.language = r;
    if (r.checked && !r.matched) mismatches.push({ field: 'language', expected: ctx.expectedLanguage, declared: declared.language });
  }

  return {
    fired: mismatches.length > 0,
    evidence: {
      declared,
      checks,
      mismatches,
    },
  };
}

// RULE sidecar-source-drift (family: extraction-artifact)
// A derived sidecar (live_priors' *.eot.json or *.structure.json) records a
// byte count and, for .eot.json, a sha256 of the source .txt it was computed
// from. If the CURRENT source file's hash/length no longer matches what the
// sidecar recorded, the sidecar describes bytes that are no longer on disk:
// any line/unit count, offset or "reading" it carries is stale and must be
// re-derived, never trusted at face value. This generalizes rule #1 (learn
// from originals, not prior extractions) to a pipeline's OWN metadata about
// itself.
//
// Pure JS (node:crypto is a built-in, not a network/model call).
// detect(text, ctx) where ctx.sidecar is the parsed JSON of either schema:
//   eot.json:       { source: { sha256, bytes } , ... }
//   structure.json: { bytes, ... }   (no hash available in this schema)

import { createHash } from 'node:crypto';

export function detect(text, ctx = {}) {
  const sidecar = ctx.sidecar;
  const actualBytes = Buffer.byteLength(text, 'utf8');
  const actualSha256 = createHash('sha256').update(text, 'utf8').digest('hex');

  if (!sidecar || typeof sidecar !== 'object') {
    return { fired: false, evidence: { skipped: true, reason: 'no ctx.sidecar provided', actualBytes, actualSha256 } };
  }

  const nested = sidecar.source && typeof sidecar.source === 'object' ? sidecar.source : null;
  const recordedSha256 = nested ? nested.sha256 : (typeof sidecar.sha256 === 'string' ? sidecar.sha256 : null);
  const recordedBytes = nested ? nested.bytes : (typeof sidecar.bytes === 'number' ? sidecar.bytes : null);

  const hashChecked = recordedSha256 != null;
  const hashMatch = hashChecked ? recordedSha256 === actualSha256 : null;
  const bytesChecked = recordedBytes != null;
  const bytesMatch = bytesChecked ? recordedBytes === actualBytes : null;

  const drifted = (hashChecked && !hashMatch) || (!hashChecked && bytesChecked && !bytesMatch);

  const evidence = {
    schema: sidecar.schema || (nested ? 'EOTReading-like' : 'SourceStructure-like'),
    actualBytes,
    recordedBytes,
    bytesMatch,
    actualSha256: hashChecked ? actualSha256 : undefined,
    recordedSha256: recordedSha256 || undefined,
    hashMatch,
    deltaBytes: bytesChecked ? actualBytes - recordedBytes : null,
    ratio: bytesChecked && recordedBytes ? +(actualBytes / recordedBytes).toFixed(4) : null,
  };

  return { fired: drifted, evidence };
}

// RULE pg-body-exact-between-markers (family: extraction-artifact)
// For this bench's Gutenberg-plaintext pipeline (the corpus directories
// 01-literature-books/gutenberg, 11-multi-language/{parallel-classics,
// italian-originals,gutenberg-non-en}), the "clean" text stored in live_priors
// is byte-identical to the ORIGINAL'S body: everything strictly between
// "*** START OF THE PROJECT GUTENBERG EBOOK ... ***" and
// "*** END OF THE PROJECT GUTENBERG EBOOK ... ***", once CRLF is normalised.
// No flattened line breaks, no inserted leading spaces, no doubled content
// was found there (checked on 9 works / ~85k lines in this territory).
// This is a POSITIVE, narrowly-scoped finding: it says nothing about
// Wikisource- or scan-sourced material (seeds S4/S5/S7/S9 already show THOSE
// pipelines do corrupt content) and nothing about front/back matter, which
// this pipeline deliberately discards rather than mis-transcribes.
//
// detect(original, ctx) where ctx.extracted is the candidate "cleaned" text
// to verify (e.g. the live_priors copy). Pure string ops, no network.
// fired=true means a REAL mismatch was found inside the marker-delimited
// body (i.e. this specific extraction broke the "body-exact" property).

function crlfNormalize(s) {
  return s.replace(/\r\n/g, '\n');
}

function bodySpan(lines) {
  let start = 0, end = lines.length;
  let hasStart = false, hasEnd = false;
  for (let i = 0; i < lines.length; i++) {
    if (/^\*\*\* START OF (?:THE|THIS) PROJECT GUTENBERG (?:EBOOK|ETEXT)/.test(lines[i])) { start = i + 1; hasStart = true; break; }
  }
  for (let i = lines.length - 1; i >= 0; i--) {
    if (/^\*\*\* END OF (?:THE|THIS) PROJECT GUTENBERG (?:EBOOK|ETEXT)/.test(lines[i])) { end = i; hasEnd = true; break; }
  }
  return { start, end, hasStart, hasEnd };
}

export function detect(original, ctx = {}) {
  const origLines = crlfNormalize(original).split('\n');
  const span = bodySpan(origLines);
  const bodyLines = origLines.slice(span.start, span.end);

  if (typeof ctx.extracted !== 'string') {
    return {
      fired: false,
      evidence: {
        skipped: true,
        reason: 'no ctx.extracted provided; reporting marker presence only',
        hasStartMarker: span.hasStart,
        hasEndMarker: span.hasEnd,
        bodyLineCount: bodyLines.length,
      },
    };
  }

  // Trim exactly one leading/trailing blank line of slack (extractors commonly
  // drop or keep a single trailing newline); anything beyond that is a real diff.
  const extractedLines = crlfNormalize(ctx.extracted).split('\n');
  const a = bodyLines.slice();
  const b = extractedLines.slice();
  while (a.length && a[a.length - 1] === '') a.pop();
  while (b.length && b[b.length - 1] === '') b.pop();
  while (a.length && a[0] === '') a.shift();
  while (b.length && b[0] === '') b.shift();

  let firstDiffAt = -1;
  const n = Math.min(a.length, b.length);
  for (let i = 0; i < n; i++) {
    if (a[i] !== b[i]) { firstDiffAt = i; break; }
  }
  const lengthMismatch = a.length !== b.length;
  const mismatch = firstDiffAt !== -1 || lengthMismatch;

  return {
    fired: mismatch,
    evidence: {
      hasStartMarker: span.hasStart,
      hasEndMarker: span.hasEnd,
      originalBodyLines: a.length,
      extractedLines: b.length,
      firstDiffAt,
      lengthMismatch,
      sample: firstDiffAt !== -1 ? { original: a[firstDiffAt], extracted: b[firstDiffAt] } : null,
    },
  };
}

// RULE transcriber-note-declares-markup (family: source-convention)
// Re-grounds seed S17. Some Gutenberg etexts carry an explicit note (German
// "Anmerkungen zur Transkription" / English "Transcriber's note" / etc.)
// that DECLARES what a bracketing ASCII character means in THIS file only
// (asterisks = letter-spaced/gesperrt print emphasis, tilde = a different
// typeface, underscore = italics, caret = superscript, ...). A reader must
// find and parse this declaration per file and apply it only to that file;
// it must never be assumed as a corpus-wide default, because different
// files in the SAME shelf declare DIFFERENT conventions (pg60360 declares
// * and ~; pg42671 -- unrelated content, but the note form is the same --
// declares _ and ^).
//
// House rule: the anchor phrases are a closed TABLE (a Set), not a regex
// alternation growing without bound. The naive `/gesperrt/i` search is a
// trap: "eingesperrt" (imprisoned), "abgesperrt" (barred off), "aufgesperrt"
// (unlocked) all contain the substring "gesperrt" as ordinary German words
// unrelated to typography (measured: pg7203/pg7204/pg7205/pg2229 each match
// bare /gesperrt/i exactly once, all four as such false positives, zero true
// declarations). This detector requires the ANCHOR HEADING first, then looks
// for a (symbol, meaning) pair only inside the paragraph(s) right after it.

const ANCHOR_HEADINGS = new Set([
  "transcriber's note",
  'transcriber’s note',
  'anmerkungen zur transkription',
  'anmerkung zur transkription',
  'anmerkung des bearbeiters',
  'nota del trascrittore',
  'nota do transcritor',
  'nota del transcriptor',
]);

const MEANING_TERMS = [
  { re: /gesperrt/i, meaning: 'gesperrt (letter-spaced emphasis)' },
  { re: /kursiv|italics?/i, meaning: 'italics' },
  { re: /andere(?:n|r)?\s+schriftart|other typeface|different (?:font|typeface)/i, meaning: 'other typeface' },
  { re: /hochgestellt|superscri/i, meaning: 'superscript' },
  { re: /fett|bold/i, meaning: 'bold' },
  { re: /kapitälchen|small caps/i, meaning: 'small caps' },
];

// A "symbol" is a short run of one repeated non-alphanumeric bracketing
// character (its own opening/closing mark), e.g. *, ~, _, ^, =, #.
const SYMBOL_RE = /([*~_^=#])(?:\1)?/;

function findAnchorIndex(text) {
  const lower = text.toLowerCase();
  let best = -1;
  for (const heading of ANCHOR_HEADINGS) {
    const i = lower.indexOf(heading);
    if (i !== -1 && (best === -1 || i < best)) best = i;
  }
  return best;
}

export function detect(text, ctx = {}) {
  const windowSize = ctx.windowSize || 1200;
  const anchorAt = findAnchorIndex(text);
  if (anchorAt === -1) {
    return { fired: false, evidence: { anchorFound: false } };
  }

  const window = text.slice(anchorAt, anchorAt + windowSize);
  // Split into short clauses/lines to keep each (symbol, meaning) pairing local,
  // so a symbol mentioned near one meaning isn't wrongly paired with another
  // meaning several sentences away.
  const clauses = window.split(/(?<=[.\n])/);

  const declarations = [];
  for (const clause of clauses) {
    const symMatch = clause.match(SYMBOL_RE);
    if (!symMatch) continue;
    for (const { re, meaning } of MEANING_TERMS) {
      if (re.test(clause)) {
        declarations.push({ symbol: symMatch[1], meaning, quote: clause.trim().slice(0, 140) });
        break;
      }
    }
  }

  // De-duplicate by symbol+meaning.
  const seen = new Set();
  const unique = declarations.filter((d) => {
    const k = d.symbol + '|' + d.meaning;
    if (seen.has(k)) return false;
    seen.add(k);
    return true;
  });

  return {
    fired: unique.length > 0,
    evidence: {
      anchorFound: true,
      anchorHeadingContext: text.slice(anchorAt, anchorAt + 60).replace(/\n/g, ' '),
      declarations: unique,
    },
  };
}

// RULE verse-sentence-case-lineation (family: source-convention)
// Re-grounds seed S2's Italian claim and GENERALIZES it to Latin verse,
// measured on the ORIGINAL bytes (not a prior extraction). In these
// Romance/classical verse editions, a line's first letter is capitalised
// if and only if it also begins a new sentence; an enjambment/continuation
// line stays lowercase. This is NOT a property of "verse" in general: German
// verse-drama (Goethe's Faust) capitalises almost every line regardless of
// syntax, so letter-case at a line start must never be read as verse-vs-prose
// or sentence-boundary evidence without first checking which regime a given
// text is in -- which is exactly what this detector measures.
//
// Method: split into non-blank lines; classify each line by whether the
// PRECEDING non-blank line ends in terminal punctuation (. ! ? ; :, allowing
// a trailing closing quote/paren/bracket). Compare P(upper-start | prev is
// non-terminal) against P(upper-start | prev is terminal). A verse-sentence-
// case text shows a large gap; a capitalize-every-line text shows almost none.
//
// Threshold note (house rule: state it and why): fired requires BOTH (a) a
// two-proportion z-test significant at z>8 (p<1e-15; the two measured
// "real" cases in this bench clear z>40) and (b) the gap itself >0.30 (30
// points). The gap cut sits far from both measured clusters: no-effect
// (Faust, German verse-drama) gap=0.026; real-effect (Dante, Aeneid)
// gap=0.65-0.68. 0.30 is the midpoint of that 0.026-vs-0.65 split, not a
// value tuned to any one text.

const TERMINAL = /[.!?;:]["'»”’)\]]*$/;

function firstLetterCase(s) {
  const m = s.match(/[A-Za-zÀ-ÖØ-öø-ÿ]/);
  if (!m) return null;
  const ch = m[0];
  return ch === ch.toUpperCase() && ch !== ch.toLowerCase() ? 'upper' : 'lower';
}

function bodySpan(lines) {
  let start = 0, end = lines.length;
  for (let i = 0; i < lines.length; i++) if (/^\*\*\* START OF (?:THE|THIS) PROJECT GUTENBERG/.test(lines[i])) { start = i + 1; break; }
  for (let i = lines.length - 1; i >= 0; i--) if (/^\*\*\* END OF (?:THE|THIS) PROJECT GUTENBERG/.test(lines[i])) { end = i; break; }
  return [start, end];
}

export function detect(text, ctx = {}) {
  const lines = text.replace(/\r\n/g, '\n').split('\n');
  const [s, e] = bodySpan(lines);
  const body = lines.slice(s, e);

  const term = { upper: 0, lower: 0 };
  const nonTerm = { upper: 0, lower: 0 };
  let prev = null;
  for (const raw of body) {
    const line = raw.trim();
    if (line === '') continue;
    const cls = firstLetterCase(line);
    if (prev !== null && cls) {
      const bucket = TERMINAL.test(prev) ? term : nonTerm;
      bucket[cls]++;
    }
    prev = line;
  }

  const nT = term.upper + term.lower;
  const nN = nonTerm.upper + nonTerm.lower;
  if (nT < 30 || nN < 30) {
    return { fired: false, evidence: { skipped: true, reason: 'insufficient verse-line sample', nTerminal: nT, nNonTerminal: nN } };
  }

  const pT = term.upper / nT;
  const pN = nonTerm.upper / nN;
  const pPool = (term.upper + nonTerm.upper) / (nT + nN);
  const se = Math.sqrt(pPool * (1 - pPool) * (1 / nT + 1 / nN));
  const z = se > 0 ? (pT - pN) / se : 0;
  const gap = pT - pN;

  const Z_GATE = 8;
  const GAP_GATE = 0.30;
  const fired = z > Z_GATE && gap > GAP_GATE;

  return {
    fired,
    evidence: {
      pUpperAfterTerminal: +pT.toFixed(4),
      nTerminal: nT,
      pUpperAfterNonTerminal: +pN.toFixed(4),
      nNonTerminal: nN,
      gap: +gap.toFixed(4),
      zScore: +z.toFixed(2),
      gateUsed: { zGate: Z_GATE, gapGate: GAP_GATE },
    },
  };
}

// RULE german-noun-capital-not-sentence-boundary (family: script-convention)
// Re-grounds the other half of seed S2 ("German prose continues on
// capitalised nouns"). In German, every common noun is capitalised wherever
// it falls in the sentence, so a hard-wrapped continuation line starting
// with a capital letter is routine and carries close to NO information about
// a sentence/clause boundary -- unlike in Spanish or Italian, where a
// capital only appears at a real name or a true sentence start.
//
// Method: find hard-wrap continuation points (previous non-blank line is
// long enough to plausibly be wrapped, >=45 chars, and does not end in
// terminal punctuation), and measure P(next line starts with a capital).
// Compare against a MEASURED null rate (not hand-picked): the same statistic
// computed on Cervantes' Don Quijote (Spanish prose, pg2000, n=24687) in
// this bench = 0.0407. A one-proportion z-test against that null decides
// `fired`; z>5 (p<3e-7) is used as the significance bar, which the German
// texts measured here clear by roughly 40-50x (see evidence.zScore) --
// i.e. the bar is nowhere near tuned to these particular numbers.

const TERMINAL = /[.!?;:]["'»”’)\]]*$/;

function firstLetterCase(s) {
  const m = s.match(/[A-Za-zÀ-ÖØ-öø-ÿ]/);
  if (!m) return null;
  const ch = m[0];
  return ch === ch.toUpperCase() && ch !== ch.toLowerCase() ? 'upper' : 'lower';
}

function bodySpan(lines) {
  let start = 0, end = lines.length;
  for (let i = 0; i < lines.length; i++) if (/^\*\*\* START OF (?:THE|THIS) PROJECT GUTENBERG/.test(lines[i])) { start = i + 1; break; }
  for (let i = lines.length - 1; i >= 0; i--) if (/^\*\*\* END OF (?:THE|THIS) PROJECT GUTENBERG/.test(lines[i])) { end = i; break; }
  return [start, end];
}

// Measured on pg2000 (Don Quijote, Spanish prose) in this bench -- a
// no-noun-capitalisation Romance-prose baseline, not an invented constant.
const ROMANCE_NULL_RATE = 0.0407;

export function detect(text, ctx = {}) {
  const nullRate = typeof ctx.nullRate === 'number' ? ctx.nullRate : ROMANCE_NULL_RATE;
  const lines = text.replace(/\r\n/g, '\n').split('\n');
  const [s, e] = bodySpan(lines);
  const body = lines.slice(s, e);

  let capital = 0, lower = 0;
  for (let i = 1; i < body.length; i++) {
    const prev = body[i - 1].trim();
    const cur = body[i].trim();
    if (prev.length < 45 || cur === '') continue;
    if (TERMINAL.test(prev)) continue;
    const cls = firstLetterCase(cur);
    if (cls === 'upper') capital++;
    else if (cls === 'lower') lower++;
  }
  const n = capital + lower;
  if (n < 100) {
    return { fired: false, evidence: { skipped: true, reason: 'insufficient hard-wrap sample', n } };
  }
  const pHat = capital / n;
  const se = Math.sqrt(nullRate * (1 - nullRate) / n);
  const z = se > 0 ? (pHat - nullRate) / se : 0;

  const Z_GATE = 5;
  const fired = z > Z_GATE && pHat > nullRate;

  return {
    fired,
    evidence: {
      pCapitalAtWrapContinuation: +pHat.toFixed(4),
      n,
      nullRate,
      nullSource: 'pg2000 Don Quijote (Spanish prose), same statistic, n=24687',
      zScore: +z.toFixed(2),
      zGate: Z_GATE,
    },
  };
}

// RULE spanish-guillemet-paragraph-continuation (family: source-convention)
// In this Quijote edition (pg2000), a speech turn is opened with a
// paragraph-initial em-dash (Spanish "raya": "— Lo primero..."). When a
// SINGLE speech or quoted passage runs across a paragraph break, the
// CONTINUATION paragraph is not given a fresh dash; instead it opens with a
// bare guillemet (» in this edition) with no matching opener on that
// paragraph -- e.g. "— Lo primero en que reparáis..." runs on for a
// paragraph, then the next paragraph opens "»En lo de citar..." and the
// one after "»En lo que toca...", with no « anywhere between them.
// A short, self-contained quotation instead gets an ordinary balanced pair
// on one paragraph ("«Apenas había el rubicundo...Montiel».").
// This explains the measured 57 « vs 290 » asymmetry in the whole
// work: most » are continuation markers, not closing quotes, so naively
// treating «/» as a simple open/close pair will mis-segment the
// continued-speech paragraphs as unterminated quotations.
//
// Method: split into blank-line-delimited paragraphs; flag paragraphs (other
// than the first in the document) whose trimmed text starts with ».
// fired=true when such paragraphs exist AND the work-wide » count
// exceeds the « count (the imbalance this convention predicts).

function bodySpan(lines) {
  let start = 0, end = lines.length;
  for (let i = 0; i < lines.length; i++) if (/^\*\*\* START OF (?:THE|THIS) PROJECT GUTENBERG/.test(lines[i])) { start = i + 1; break; }
  for (let i = lines.length - 1; i >= 0; i--) if (/^\*\*\* END OF (?:THE|THIS) PROJECT GUTENBERG/.test(lines[i])) { end = i; break; }
  return [start, end];
}

export function detect(text, ctx = {}) {
  const norm = text.replace(/\r\n/g, '\n');
  const lines = norm.split('\n');
  const [s, e] = bodySpan(lines);
  const body = lines.slice(s, e).join('\n');

  const paragraphs = body.split(/\n\s*\n/).map((p) => p.trim()).filter(Boolean);
  const continuationParas = [];
  for (let i = 1; i < paragraphs.length; i++) {
    if (paragraphs[i].startsWith('»')) {
      continuationParas.push(paragraphs[i].slice(0, 60));
    }
  }

  const openCount = (body.match(/«/g) || []).length;
  const closeCount = (body.match(/»/g) || []).length;

  const fired = continuationParas.length > 0 && closeCount > openCount;

  return {
    fired,
    evidence: {
      guillemetOpenCount: openCount,
      guillemetCloseCount: closeCount,
      continuationParagraphCount: continuationParas.length,
      continuationExamples: continuationParas.slice(0, 3),
    },
  };
}

// RULE quote-style-is-per-file (family: source-convention)
// The quotation-mark character set used in a German text is a property of
// the INDIVIDUAL transcription, not of the declared language "German": a
// reader must sniff each file's own bytes rather than assume a fixed style
// for a language. Measured on the Nietzsche shelf in this bench (same
// author, same rough digitisation era): pg60360 and pg7205 use proper German
// low-high quotes ( „ ... “ ), 1649 and 726 pairs respectively,
// zero ASCII straight quotes; pg7202/pg7203/pg7206/pg7207 use ONLY the ASCII
// straight quote ("), 770/676/454/428 times respectively, with a small
// constant 11 occurrences of a bare “ in each (a recurring
// front-matter/epigraph artifact, not body dialogue) and zero „. Two
// conventions, one language, one shelf.
//
// This detector classifies a SINGLE file's own convention; fired=true means
// the file is internally consistent with exactly one of the two known
// styles (so a caller can safely pick a quote-parsing rule for it). A
// genuinely mixed file (both styles used substantially) is reported instead
// of forced into either bucket.

export function detect(text, ctx = {}) {
  const minCount = ctx.minCount || 20;
  const nativeOpen = (text.match(/„/g) || []).length; // „
  const nativeClose = (text.match(/“/g) || []).length; // “ (reused as closer in German)
  const asciiQuote = (text.match(/"/g) || []).length;

  const hasNative = nativeOpen >= minCount;
  const hasAsciiOnly = !hasNative && asciiQuote >= minCount;
  const mixed = nativeOpen >= minCount && asciiQuote >= minCount;

  let style = null;
  if (mixed) style = 'mixed';
  else if (hasNative) style = 'native-low-high';
  else if (hasAsciiOnly) style = 'ascii-straight';

  return {
    fired: style === 'native-low-high' || style === 'ascii-straight',
    evidence: {
      style,
      nativeOpenCount: nativeOpen,
      nativeCloseCount: nativeClose,
      asciiQuoteCount: asciiQuote,
      mixed,
    },
  };
}

// RULE no-editorial-lineation-in-verse (family: source-convention)
// Re-grounds seed S3 by SCOPE. S3 was measured on Wikisource verse (Martial,
// Homer, Pindar): a trailing number on a verse line is the edition's line
// count when EVERY trailing number in the work is a multiple of 5 (a content
// null: p=1/5 per number, k-of-k under that null gives 0.2^k). This detector
// IMPLEMENTS that exact test (so it still fires on a Wikisource-style verse
// text), but measured directly on Gutenberg-plaintext verse ORIGINALS in
// this territory (Aeneid pg227, Dante pg1000, Faust pg2229: 25,899 combined
// non-blank body lines) it finds ZERO trailing-number lines at all -- the
// convention simply does not appear in this pipeline's source material.
// S3 is therefore scope-narrowed to Wikisource-style scholarly apparatus,
// not a general "verse" property, purely from a negative count -- no
// judgement call needed.

function bodySpan(lines) {
  let start = 0, end = lines.length;
  for (let i = 0; i < lines.length; i++) if (/^\*\*\* START OF (?:THE|THIS) PROJECT GUTENBERG/.test(lines[i])) { start = i + 1; break; }
  for (let i = lines.length - 1; i >= 0; i--) if (/^\*\*\* END OF (?:THE|THIS) PROJECT GUTENBERG/.test(lines[i])) { end = i; break; }
  return [start, end];
}

const TRAILING_NUMBER = /(?:^\s*(\d{1,4})\s*$)|(?:\S\s+(\d{1,4})\s*$)/;

export function detect(text, ctx = {}) {
  const lines = text.replace(/\r\n/g, '\n').split('\n');
  const [s, e] = bodySpan(lines);
  const body = lines.slice(s, e);

  const hits = [];
  for (const raw of body) {
    if (raw.trim() === '') continue;
    const m = raw.match(TRAILING_NUMBER);
    if (m) {
      const n = parseInt(m[1] || m[2], 10);
      hits.push(n);
    }
  }

  const k = hits.length;
  const multiplesOf5 = hits.filter((n) => n % 5 === 0).length;
  const pUnderNull = k > 0 ? Math.pow(0.2, multiplesOf5) : null;

  // Fires as S3 ORIGINALLY intended: real editorial lineation found (enough
  // hits, and they are overwhelmingly multiples of 5, astronomically
  // unlikely by chance).
  const fired = k >= 10 && multiplesOf5 / k > 0.9 && pUnderNull < 1e-6;

  return {
    fired,
    evidence: {
      nonBlankBodyLines: body.filter((l) => l.trim() !== '').length,
      trailingNumberLineCount: k,
      multiplesOf5,
      pUnderMultipleOf5Null: pUnderNull,
      note: k === 0 ? 'no trailing-number lines at all in this text' : undefined,
    },
  };
}

// RULE leading-indent-is-per-edition (family: source-convention)
// Re-grounds and NARROWS seed S10. S10 claimed a fixed split ("Wikisource
// lines carry one leading space, Gutenberg verse two"). Measured directly on
// three Gutenberg verse ORIGINALS in this territory, the indent is NOT a
// constant of "being Gutenberg": Aeneid (pg227) is 2-space-indented in
// 9930/9932 non-blank lines (99.98%); Dante (pg1000) is 0-space in
// 14439/14542 (99.29%); Faust (pg2229) is 0-space in 5928/5956 (99.53%).
// Two of three Gutenberg verse works use NO indent at all. The part of S10
// that survives is the METHOD ("read indent relative to the work's modal
// indent"), not the specific constant; this detector measures a work's own
// modal indent instead of assuming one.

function bodySpan(lines) {
  let start = 0, end = lines.length;
  for (let i = 0; i < lines.length; i++) if (/^\*\*\* START OF (?:THE|THIS) PROJECT GUTENBERG/.test(lines[i])) { start = i + 1; break; }
  for (let i = lines.length - 1; i >= 0; i--) if (/^\*\*\* END OF (?:THE|THIS) PROJECT GUTENBERG/.test(lines[i])) { end = i; break; }
  return [start, end];
}

export function detect(text, ctx = {}) {
  const minShare = typeof ctx.minShare === 'number' ? ctx.minShare : 0.9;
  const lines = text.replace(/\r\n/g, '\n').split('\n');
  const [s, e] = bodySpan(lines);
  const body = lines.slice(s, e);

  const hist = new Map();
  let total = 0;
  for (const raw of body) {
    if (raw.trim() === '') continue;
    total++;
    const n = (raw.match(/^ */)[0] || '').length;
    hist.set(n, (hist.get(n) || 0) + 1);
  }

  let modal = null, modalCount = 0;
  for (const [n, c] of hist.entries()) {
    if (c > modalCount) { modal = n; modalCount = c; }
  }
  const share = total > 0 ? modalCount / total : 0;

  return {
    fired: total > 0 && share >= minShare,
    evidence: {
      totalNonBlankLines: total,
      modalIndent: modal,
      modalIndentShare: +share.toFixed(4),
      histogram: Object.fromEntries(hist),
    },
  };
}

// Rule: ws-zh-tag-boundary-space-join
// Family: extraction-artifact
// Re-grounds seed S10 for zh.wikisource.org (Chinese Wikisource): the "leading
// space" S10 attributes to editorial indentation is, for this territory, NOT
// indentation at all. Neither the wikitext nor the rendered HTML of any
// fetched original has leading/trailing whitespace on a paragraph or around
// an inline template span (checked: shiji-juan001, bencao-caozhiyi, etc).
// Yet the live_priors plain-text copy inserts one ASCII space at (what looks
// like) every HTML tag boundary: around every {{專|X}}/{{書|X}} proper-noun /
// book-title span, around <a> links (including the licence-box wikilink),
// at the start AND end of every rendered block (so paragraphs/headings carry
// a leading AND a trailing space, not just leading), and a fully empty block
// becomes a line containing exactly one space character.
//
// Null model: Literary/Classical Chinese orthography never places a bare
// ASCII space between two Han ideographs (or CJK punctuation) in running
// prose -- there is no word-spacing convention. So the *expected* count of
// "space flanked by CJK on both sides" under the source's own convention is
// exactly 0. Any non-zero count is evidence the space was inserted by a
// conversion step, not authored. We therefore do not use a hand-picked
// fraction cutoff for the interior-space evidence -- presence (count > 0) is
// itself the falsifying signal. For the line-edge evidence we do report a
// fraction (see evidence.lineEdgeFraction) since some legitimate texts could
// front a line with a Latin/number token; that is contextual evidence, not
// the firing condition.

const CJK_IDEOGRAPH = /[㐀-䶿一-鿿豈-﫿]/;
const CJK_PUNCT = new Set([
  '，', '。', '、', '；', '：', '「', '」', '『', '』', '《', '》',
  '〈', '〉', '【', '】', '（', '）', '！', '？', '—', '…', '・',
  '　', '﹏', '﹁', '﹂',
]);

function isCJKContext(ch) {
  if (ch === undefined) return false;
  return CJK_IDEOGRAPH.test(ch) || CJK_PUNCT.has(ch);
}

export function detect(text, ctx = {}) {
  const chars = Array.from(text);
  let totalSpaces = 0;
  let interiorHits = 0;
  const exampleInterior = [];

  for (let i = 0; i < chars.length; i++) {
    if (chars[i] !== ' ') continue;
    totalSpaces++;
    const prev = chars[i - 1];
    const next = chars[i + 1];
    if (isCJKContext(prev) && isCJKContext(next)) {
      interiorHits++;
      if (exampleInterior.length < 6) {
        const start = Math.max(0, i - 6);
        const end = Math.min(chars.length, i + 7);
        exampleInterior.push(chars.slice(start, end).join(''));
      }
    }
  }

  const lines = text.split('\n');
  let nonBlankLines = 0;
  let startHits = 0;
  let endHits = 0;
  let loneSpaceLines = 0;
  const exampleLines = [];
  for (const line of lines) {
    if (line === ' ') {
      loneSpaceLines++;
      continue;
    }
    if (line.length === 0) continue;
    nonBlankLines++;
    const lchars = Array.from(line);
    const startsWithSpaceCJK = lchars[0] === ' ' && isCJKContext(lchars[1]);
    const endsWithSpaceCJK =
      lchars[lchars.length - 1] === ' ' && isCJKContext(lchars[lchars.length - 2]);
    if (startsWithSpaceCJK) startHits++;
    if (endsWithSpaceCJK) endHits++;
    if ((startsWithSpaceCJK || endsWithSpaceCJK) && exampleLines.length < 4) {
      exampleLines.push(line.slice(0, 40));
    }
  }

  const fired = interiorHits > 0;

  return {
    fired,
    evidence: {
      totalSpaces,
      interiorCJKFlankedSpaces: interiorHits,
      interiorFractionOfAllSpaces: totalSpaces ? Number((interiorHits / totalSpaces).toFixed(4)) : 0,
      exampleInteriorContexts: exampleInterior,
      nonBlankLines,
      lineStartSpaceCJKHits: startHits,
      lineEndSpaceCJKHits: endHits,
      lineEdgeFraction: nonBlankLines
        ? Number(((startHits + endHits) / (2 * nonBlankLines)).toFixed(3))
        : 0,
      loneSpaceBlankLines: loneSpaceLines,
      exampleFlaggedLines: exampleLines,
      nullModel:
        'Chinese running prose has no word-spacing convention; a bare ASCII space with a CJK ideograph/punctuation on both sides has expected count 0 under the source edition\'s own typesetting. Any count > 0 rejects "this text is an unmodified transcription of the source bytes".',
    },
  };
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const fs = await import('node:fs');
  const path = process.argv[2];
  const text = fs.readFileSync(path, 'utf8');
  console.log(JSON.stringify(detect(text, {}), null, 2));
}

// Rule: ws-zh-simplified-chrome-in-traditional
// Family: extraction-artifact
// Re-grounds seed S4 (" [ 编辑 ] " edit-link leakage) and generalizes it.
// zh.wikisource.org serves Literary Chinese works transcribed in Traditional
// characters, but the wiki's OWN interface chrome (section edit links,
// Page:-namespace proofreading-quality banners, etc.) is emitted in
// Simplified Chinese regardless of the content script ("编辑" not "編輯",
// "此页尚未校对" not "此頁尚未校對"). A plain-text extraction that does not
// separate UI chrome from content therefore mixes a handful of Simplified
// characters into an otherwise wall-to-wall Traditional document.
//
// Rather than hand-listing every possible UI phrase (which would not
// generalize to chrome we have not seen), this detector uses a small CLOSED
// TABLE of unambiguous Traditional/Simplified character-form pairs (real
// lexicographic fact, not a tuned parameter) and asks a global question:
// is this document overwhelmingly Traditional (>50% of table-covered
// characters), yet contains at least one line with a Simplified-only form?
// If both hold, those lines are almost certainly platform chrome, not
// authorial text -- the 50% split is a generous, non-arbitrary majority
// bound (real leakage in our samples is far below 1% of table characters).
const TRAD_SIMP_PAIRS = [
  ['編', '编'], ['輯', '辑'], ['這', '这'], ['頁', '页'], ['對', '对'],
  ['導', '导'], ['歷', '历'], ['漢', '汉'], ['學', '学'], ['國', '国'],
  ['語', '语'], ['點', '点'], ['個', '个'], ['來', '来'], ['時', '时'],
  ['問', '问'], ['題', '题'], ['說', '说'], ['讀', '读'], ['圖', '图'],
  ['錄', '录'], ['長', '长'], ['馬', '马'], ['車', '车'], ['歸', '归'],
  ['聲', '声'], ['顯', '显'],
];
const TRAD_ONLY = new Set(TRAD_SIMP_PAIRS.map((p) => p[0]));
const SIMP_ONLY = new Set(TRAD_SIMP_PAIRS.map((p) => p[1]).filter((c) => !TRAD_ONLY.has(c)));

// A wikitext -{...}- LanguageConverter block can legitimately spell out a
// zh-hans: (Simplified) variant right next to a zh-hant: (Traditional) one
// (e.g. "-{zh-hans:X;zh-hant:Y}-"); that is the source deliberately
// authoring both scripts, not chrome leakage, so we mask such spans out
// (replacing with '#' of the same length, preserving line numbers/offsets)
// before scanning. This was found empirically: without the mask, 史記/卷001
// wikitext shows one false positive inside exactly such a block.
function maskLanguageConverterSpans(text) {
  return text.replace(/-\{[^]*?\}-/g, (m) => '#'.repeat(m.length));
}

export function detect(text, ctx = {}) {
  const masked = maskLanguageConverterSpans(text);
  let tradCount = 0;
  let simpCount = 0;
  for (const ch of masked) {
    if (TRAD_ONLY.has(ch)) tradCount++;
    else if (SIMP_ONLY.has(ch)) simpCount++;
  }
  const denom = tradCount + simpCount;
  const globalSimplifiedFraction = denom ? simpCount / denom : 0;

  const maskedLines = masked.split('\n');
  const originalLines = text.split('\n');
  const flaggedLines = [];
  maskedLines.forEach((line, idx) => {
    for (const ch of line) {
      if (SIMP_ONLY.has(ch)) {
        flaggedLines.push({ lineNo: idx, text: (originalLines[idx] || line).trim().slice(0, 60) });
        break;
      }
    }
  });

  const documentIsMajorityTraditional = globalSimplifiedFraction < 0.5;
  const fired = flaggedLines.length > 0 && documentIsMajorityTraditional;

  return {
    fired,
    evidence: {
      tradTableCharCount: tradCount,
      simpTableCharCount: simpCount,
      globalSimplifiedFraction: Number(globalSimplifiedFraction.toFixed(4)),
      documentIsMajorityTraditional,
      flaggedLineCount: flaggedLines.length,
      exampleFlaggedLines: flaggedLines.slice(0, 8),
      thresholdNote:
        '50% is a deliberately generous majority bound, not a tuned cutoff: genuine platform-chrome leakage in the samples measured is a tiny fraction of a percent of table characters, so any value far below 50% already falsifies "this is a Simplified-script document".',
    },
  };
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const fs = await import('node:fs');
  const path = process.argv[2];
  const text = fs.readFileSync(path, 'utf8');
  console.log(JSON.stringify(detect(text, {}), null, 2));
}

// Rule: ws-zh-hidden-licensetpl-leak
// Family: extraction-artifact
// Part of re-grounding seed S5 ("Public domain Public domain false false").
// On zh.wikisource.org, {{PD-old}} (and relatives) render a `<div
// class="licensetpl">` block whose OWN page stylesheet declares
// `.licensetpl{display:none}` (confirmed in bencao-caozhiyi.html and
// mengzi-ziyi-shuzheng.html's inlined <style>). It is machine-readable
// metadata for bots/reusers, invisible to a sighted reader in a real
// browser. The plain-text extraction does not honour CSS visibility (it is
// not driven by a real rendering engine), so the four child spans
// (licensetpl_short / _long / _link_req / _attr_req) are joined with the
// same single-space-per-tag-boundary behaviour as ws-zh-tag-boundary-space-
// join and come out as a short, very distinctive run: a phrase, repeated
// once, then two boolean words repeated. This is a structural pattern
// (which spans exist), not a closed vocabulary of license names, so it is
// matched positionally/generically rather than via a hand list of license
// strings -- it will also catch a CC-BY-SA-style license box, not just
// "Public domain".
const BOOL_WORDS = new Set(['true', 'false']);
// Structural: <phrase> <same phrase> <bool> <bool>, single ASCII space
// between each element (the join behaviour under test).
const PATTERN = /([A-Za-z][A-Za-z0-9.,'()\- ]{1,40}?) \1 (true|false) (true|false)\b/g;

export function detect(text, ctx = {}) {
  const matches = [];
  let m;
  const re = new RegExp(PATTERN);
  while ((m = re.exec(text)) !== null) {
    if (!BOOL_WORDS.has(m[2]) || !BOOL_WORDS.has(m[3])) continue; // belt & suspenders
    matches.push({
      phrase: m[1],
      bool1: m[2],
      bool2: m[3],
      index: m.index,
      context: text.slice(Math.max(0, m.index - 20), m.index + m[0].length + 5),
    });
  }

  return {
    fired: matches.length > 0,
    evidence: {
      matchCount: matches.length,
      examples: matches.slice(0, 5),
      structuralPattern: 'phrase SPACE phrase SPACE bool SPACE bool (bool in {true,false})',
      cssConfirmation:
        'bencao-caozhiyi.html and mengzi-ziyi-shuzheng.html both carry ".mw-parser-output .licensetpl{display:none}" in their own inlined <style>, i.e. this content is source-marked invisible, not merely unstyled.',
    },
  };
}

