// Rule: ws-zh-pd-notice-boilerplate
// Family: extraction-artifact (furniture that IS genuinely visible on the
// live page, unlike ws-zh-hidden-licensetpl-leak, but is per-page Wikisource
// site furniture, not authorial content of the work).
// Part of re-grounding seed S5. The human-readable half of the PD-old
// template ("此[X]作品在全世界都属于 公有领域 ，因为作者逝世已经超过100年，
// 且作品于1931年1月1日之前出版。") is real, on-page, visible text -- but it
// is appended once per FETCHED SUBPAGE, verbatim (only a dynasty word and a
// year/date vary), so a work fetched as N subpages carries N near-identical
// copies of a legal notice with zero information about the work's content.
// Null model: authorial prose does not repeat a multi-clause sentence
// verbatim across a work; we require >=2 occurrences to fire (repetition
// itself is the signal, not a magnitude threshold).
const RE = /此[一-鿿]{0,6}作品在全世界都属于\s*公有领域\s*，因为[^。]{0,80}。/g;

export function detect(text, ctx = {}) {
  const matches = Array.from(text.matchAll(RE)).map((m) => m[0]);
  const distinct = Array.from(new Set(matches));
  const totalBytes = matches.reduce((n, s) => n + Buffer.byteLength(s, 'utf8'), 0);

  return {
    fired: matches.length >= 2,
    evidence: {
      occurrenceCount: matches.length,
      distinctVariants: distinct.slice(0, 5),
      distinctVariantCount: distinct.length,
      totalBytesConsumed: totalBytes,
      fractionOfFileBytes: text.length
        ? Number((totalBytes / Buffer.byteLength(text, 'utf8')).toFixed(4))
        : 0,
      firingRule: 'count >= 2 (verbatim repetition of a full sentence is not a plausible authorial act; the exact count, not a tuned fraction, is the evidence)',
    },
  };
}

