// Rule: ws-zh-fetcher-part-separator
// Family: extraction-artifact
// Part of re-grounding seed S5's list of injected non-source text (the task
// brief names "fetcher part separators" explicitly). When the earlier
// pipeline concatenated multiple fetched subpages (one Wikisource page per
// juan/subpage) into one corpus .txt file, it inserted a run of U+2500 BOX
// DRAWINGS LIGHT HORIZONTAL characters between parts. This string form never
// occurs in any wikitext or rendered HTML we fetched from zh.wikisource.org
// (box-drawing characters are not part of Literary Chinese punctuation or of
// MediaWiki's own output) -- it is 100% attributable to the local
// concatenation step, not the source. Because it also marks true subpage
// boundaries, it doubles as a (reconstructable) structural signal.
const RE = /─{10,}/g;

export function detect(text, ctx = {}) {
  const matches = Array.from(text.matchAll(RE));
  const lengths = matches.map((m) => m[0].length);
  const distinctLengths = Array.from(new Set(lengths));

  let onOwnLine = 0;
  for (const m of matches) {
    const before = text.slice(Math.max(0, m.index - 3), m.index);
    const after = text.slice(m.index + m[0].length, m.index + m[0].length + 3);
    if (/\n\s*$/.test(before) && /^\s*\n/.test(after)) onOwnLine++;
  }

  return {
    fired: matches.length > 0,
    evidence: {
      separatorRunCount: matches.length,
      distinctRunLengths: distinctLengths,
      runsSittingAloneOnTheirOwnLine: onOwnLine,
      note: 'U+2500 does not appear anywhere in the fetched originals\' wikitext or rendered HTML (checked across all territory originals); its only source is this corpus\'s own subpage-concatenation step.',
    },
  };
}

