// Rule: ws-zh-annotation-mark-templates
// Family: source-convention
// zh.wikisource.org annotated editions of Classical Chinese texts mark
// proper nouns and book/work titles the way a modern print edition would --
// with an underline convention -- because the script itself carries no
// capitalization to distinguish a name from surrounding prose. This is
// implemented as a CLOSED table of two wikitext templates (never a regex
// alternation of many spellings: only these two things exist), each with a
// distinct CSS decoration confirmed in rendered HTML:
//   {{專|X}} / {{ProperNoun|X}}   -> text-decoration-style: SOLID underline
//                                    (person/place/dynasty names, 專名號)
//   {{書|X}} / {{WavyBookMark|X}} -> text-decoration-style: WAVY underline
//                                    (cited work titles, 書名號)
// Measured on shiji-juan001: every {{專|...}} call corresponds to a "solid"
// span and every {{書|...}} call to a "wavy" span in the matching rendered
// HTML. Neither template produces a hyperlink (no <a href>) -- this is
// decoration only, distinct from an ordinary wikilink.
// Scope: this signal lives in the wikitext or the rendered HTML. Once
// flattened to plain text the decoration itself is lost; only the
// accidental single-space boundary from ws-zh-tag-boundary-space-join
// survives as a faint trace of where a span used to be.
const MARK_TABLE = [
  { names: ['專', 'ProperNoun'], decoration: 'solid', meaning: 'proper-noun underline (專名號): person/place/dynasty' },
  { names: ['書', 'WavyBookMark'], decoration: 'wavy', meaning: 'book-title wavy underline (書名號): cited work title' },
];

function countSubstr(haystack, needle) {
  if (!needle) return 0;
  let count = 0;
  let idx = 0;
  while ((idx = haystack.indexOf(needle, idx)) !== -1) {
    count++;
    idx += needle.length;
  }
  return count;
}

export function detect(text, ctx = {}) {
  const perTemplate = MARK_TABLE.map((entry) => {
    const wikitextCount = entry.names.reduce(
      (sum, name) => sum + countSubstr(text, `{{${name}|`),
      0
    );
    return { names: entry.names, decoration: entry.decoration, meaning: entry.meaning, wikitextCount };
  });

  const htmlSolid = countSubstr(text, '-moz-text-decoration-style: solid');
  const htmlWavy = countSubstr(text, '-moz-text-decoration-style: wavy');
  const htmlHasUnderlineDecoration = countSubstr(text, 'text-decoration: underline');
  const htmlHasHrefNearUnderline = /text-decoration: underline[^>]*>\s*<a /.test(text);

  const wikitextFired = perTemplate.some((e) => e.wikitextCount > 0);
  const htmlFired = htmlSolid > 0 || htmlWavy > 0;

  return {
    fired: wikitextFired || htmlFired,
    evidence: {
      perTemplateWikitextCounts: perTemplate,
      htmlSolidUnderlineSpans: htmlSolid,
      htmlWavyUnderlineSpans: htmlWavy,
      htmlUnderlineDecorationTotal: htmlHasUnderlineDecoration,
      decorationIsNotAHyperlink: !htmlHasHrefNearUnderline,
    },
  };
}

