// Rule: ws-zh-interlinear-commentary-templates
// Family: source-convention
// Re-grounds part of seed S14 ("interlinear notes") with the actual
// mechanism. Classical Chinese commentary is traditionally set as small
// interlinear text -- either one run of small text, or two half-height
// columns side by side (the woodblock "double-row" 雙行 convention).
// zh.wikisource.org implements this with a closed table of two templates,
// distinguished cleanly in rendered HTML by which CSS classes are present
// (measured on 荀子/不苟篇 and 九章算術 Page:.../10):
//   {{*|note}}            1 field -> <small style="color:var(--color-
//                                     destructive--visited,...)"> wrapping,
//                                     brackets are a bare inline
//                                     style="color:transparent;font-size:0px"
//                                     span with NO class attribute.
//   {{雙行註文|A|B}}       2 fields -> <small class="sfrac nowrap"> stacking
//                                     A over B, brackets are
//                                     <span class="wst-dl-bracket"> (styled
//                                     transparent/font-size:0 via an external
//                                     <style> rule, not inline).
// Both variants wrap the note in 〈 〉 (U+3008/U+3009) brackets that are
// PART OF THE SOURCE'S OWN CSS (not an extraction artifact): the source
// itself renders them invisible (color:transparent;font-size:0px) to a
// sighted reader, who instead perceives the small-type/stacked layout. A
// naive text extraction (this corpus's) does not apply CSS, so it makes
// visible (as literal 〈 〉 characters) a delimiter the source intended to be
// invisible ink. Coverage is uneven: some subpages of the SAME work under
// the SAME commentator carry no notes at all (measured: 荀子/正名篇 has 0
// occurrences of {{*|...}} though 荀子/不苟篇 has 109) -- presence must be
// checked per subpage, never assumed for a whole work.
const SINGLE_HTML_SIG = '<span style="color:transparent;font-size:0px">';
const DOUBLE_HTML_SIG = '<span class="wst-dl-bracket">';

function countSubstr(haystack, needle) {
  let count = 0;
  let idx = 0;
  while ((idx = haystack.indexOf(needle, idx)) !== -1) {
    count++;
    idx += needle.length;
  }
  return count;
}

export function detect(text, ctx = {}) {
  const wikitextSingle = countSubstr(text, '{{*|');
  const wikitextDouble = countSubstr(text, '{{雙行註文|');
  const htmlSingle = countSubstr(text, SINGLE_HTML_SIG);
  const htmlDouble = countSubstr(text, DOUBLE_HTML_SIG);
  const bracketOpen = countSubstr(text, '〈');
  const bracketClose = countSubstr(text, '〉');

  return {
    fired: wikitextSingle > 0 || wikitextDouble > 0 || htmlSingle > 0 || htmlDouble > 0,
    evidence: {
      wikitext: { singleColumnStar: wikitextSingle, doubleColumnShuangHangZhuwen: wikitextDouble },
      html: { singleColumnSignature: htmlSingle, doubleColumnSignature: htmlDouble },
      bracketCharCounts: { open: bracketOpen, close: bracketClose, balanced: bracketOpen === bracketClose },
      note: 'Brackets are invisible in the true rendering (color:transparent;font-size:0px in the source\'s own CSS); their visibility in plain text is a side-effect of not applying CSS, not an injected artifact.',
    },
  };
}

