// Rule: ws-zh-three-commentary-cbox
// Family: source-convention
// Re-grounds the "Three Commentaries in Shiji" part of seed S14. The
// 史記三家註 (Three-Commentary) edition subtree (e.g. 史記三家註/卷001,
// distinct from the plain 史記/卷001 pages the earlier extraction actually
// used) marks each of the three historical commentators with a CLOSED,
// 3-element table of names -- 集解 (Pei Yin), 索隱 (Sima Zhen), 正義 (Zhang
// Shoujie) -- via {{CBox|NAME|COLOR}}, a colored name-badge, immediately
// followed by the note text wrapped in a matching {{green|...}} /
// {{deepPink|...}} / colour-hex span. Measured on 史記三家註/卷001: 481
// {{CBox|...}} calls, and in the matching rendered HTML every extracted
// label we sampled is one of the three names, rendered as a solid-colour
// pill (background-color + white bold text + border-radius) preceded by the
// same invisible 〈 bracket used by the simpler interlinear templates. This
// is Wikisource's own (CSS-era) solution for a historically double-column,
// three-voice commentary apparatus -- not something the woodblock original
// could have done with colour, but a faithful re-encoding of "which of three
// named voices is speaking" that a plain-text reader can still recover from
// the surviving CBox label text even though the colour itself is lost.
// This edition subtree was NOT part of the live_priors extraction (which
// used the plain 史記/卷NNN pages) -- this rule is forward-looking, grounded
// directly on the original, for when the archon does meet a three-commentary
// page.
// The table below started as the three commentators and was WIDENED by one
// entry after measurement: 史記三家註/卷001 has exactly 481 {{CBox|...}}
// calls, and one of them is labelled "索隱述贊" (172 集解 + 103 索隱 + 205 正義
// + 1 索隱述贊 = 481) -- the eulogy-specific sub-label of Sima Zhen's 索隱
// voice (see ws-zh-suoyin-zan-another-hand). The set is still small and
// closed (4, not an open vocabulary); we report any label actually outside
// it as a falsifying mismatch rather than silently absorbing it.
const COMMENTATOR_NAMES = ['集解', '索隱', '正義', '索隱述贊'];
const CBOX_RE = /\{\{CBox\|([^|}]+)\|([^}]+)\}\}/g;

export function detect(text, ctx = {}) {
  const calls = Array.from(text.matchAll(CBOX_RE)).map((m) => ({
    label: m[1],
    color: m[2],
  }));
  const mismatches = calls.filter((c) => !COMMENTATOR_NAMES.includes(c.label));
  const colorCounts = {};
  for (const c of calls) colorCounts[c.color] = (colorCounts[c.color] || 0) + 1;

  return {
    fired: calls.length > 0 && mismatches.length === 0,
    evidence: {
      cboxCallCount: calls.length,
      distinctLabelsSeen: Array.from(new Set(calls.map((c) => c.label))),
      closedTableUsed: COMMENTATOR_NAMES,
      labelsOutsideClosedTable: mismatches.slice(0, 5),
      colorUsageCounts: colorCounts,
    },
  };
}

