// Rule: ws-zh-bencao-field-label-table
// Family: source-convention (script-convention flavour: 【】 as a generic
// Chinese structural-label delimiter, specialised here to a closed
// vocabulary).
// Directly answers the task's callout of "【】 field labels". Measured on
// 本草綱目/草之一 wikitext: entries are structured with a lenticular-bracket
// label drawn from a CLOSED, 11-item set --
//   釋名 集解 修治 氣味 主治 發明 附方 校正 正誤 附錄 附注
// (counts on this one subpage: 主治×44, 氣味×33, 集解×30, 釋名×29, 附方×28,
// 發明×27, 修治×16, 校正×7, 正誤×3, 附錄×1, 附注×1). Per the house rule that
// a closed list of labels is a TABLE, not a regex alternation, the closed
// set below is an explicit array checked by membership, not baked into the
// extraction regex. The bracket SHAPE 【…】 is reused elsewhere in this
// territory for an unrelated purpose (Shiji's single eulogy marker
// 【索隱述贊】, see ws-zh-suoyin-zan-another-hand) -- so 【…】 itself is a
// general script-convention for "this is a structural label, not running
// prose", and the specific vocabulary inside is corpus/work-specific. This
// detector reports both: the generic bracket-span count, and how many of
// those spans land in Bencao's specific closed table.
const BENCAO_FIELD_LABELS = [
  '釋名', '集解', '修治', '氣味', '主治', '發明', '附方', '校正', '正誤', '附錄', '附注',
];
const BENCAO_SET = new Set(BENCAO_FIELD_LABELS);
const BRACKET_RE = /【([^】]{1,6})】/g;

export function detect(text, ctx = {}) {
  const spans = Array.from(text.matchAll(BRACKET_RE)).map((m) => m[1]);
  const counts = {};
  for (const s of spans) counts[s] = (counts[s] || 0) + 1;
  const inTable = spans.filter((s) => BENCAO_SET.has(s));
  const outOfTable = spans.filter((s) => !BENCAO_SET.has(s));
  const outOfTableCounts = {};
  for (const s of outOfTable) outOfTableCounts[s] = (outOfTableCounts[s] || 0) + 1;

  return {
    fired: inTable.length > 0,
    evidence: {
      totalBracketSpans: spans.length,
      closedTable: BENCAO_FIELD_LABELS,
      matchedClosedTableCount: inTable.length,
      matchedFraction: spans.length ? Number((inTable.length / spans.length).toFixed(3)) : 0,
      perLabelCounts: counts,
      outOfTableLabelsSeen: outOfTableCounts,
    },
  };
}

