// Rule: ws-zh-vertical-writing-mode-signal
// Family: cv-distilled
// What a CV look at a page scan would show you: that this edition was
// printed in vertical, right-to-left columns (true of essentially all
// pre-modern Chinese woodblock/movable-type books, including the 四部叢刊
// facsimile behind 九章算術). Measured: fetching Page:Sibu Congkan0390-劉徽-
// 九章算術-3-1.djvu/10 directly returns wikitext containing
// "{{Vtext2Start}}" and rendered HTML containing an explicit
// "writing-mode:vertical-rl" inline style on the page's content container --
// i.e. Wikisource's own renderer already encodes "this page is vertical" as
// a byte-level fact, and a look at the scan image would tell you nothing
// that these bytes do not already say.
// Important scope caveat, itself measured: {{Vtext2Start}} sits inside
// <noinclude>...</noinclude> in the Page: wikitext, so it is DROPPED when
// the page is transcluded into the assembled "work" page (confirmed:
// jiuzhang-juan1.html, fetched via the work-page transclusion route, has 0
// occurrences of "writing-mode" even though it demonstrably contains the
// same underlying page content). The signal must be read from the Page:
// namespace text itself, not inferred from its absence in a transcluded
// chapter.
function countSubstr(haystack, needle) {
  let count = 0;
  let idx = 0;
  while ((idx = haystack.indexOf(needle, idx)) !== -1) {
    count++;
    idx += needle.length;
  }
  return count;
}

export function detect(text, ctx = {}) {
  const vtextTemplate = countSubstr(text, '{{Vtext'); // prefix family, not a single exact name
  const writingModeCss = (text.match(/writing-mode\s*:\s*vertical-rl/g) || []).length;

  return {
    fired: vtextTemplate > 0 || writingModeCss > 0,
    evidence: {
      vtextTemplateOccurrences: vtextTemplate,
      writingModeVerticalRlOccurrences: writingModeCss,
      predicts: 'source edition was set in vertical right-to-left columns; no CV/scan-image look needed to establish this once the Page: namespace bytes are read',
      scopeCaveat: 'This template sits in <noinclude> and does not survive transclusion into an assembled work page; absence here only means "not visible from the work page", not "not vertical". Check the underlying Page:*/N text directly.',
    },
  };
}

