// Rule: ws-zh-presentation-colon-vertical-heritage
// Family: script-convention
// Classical-commentary quotations in this territory (measured: 荀子/不苟篇
// wikitext, Yang Liang's notes) introduce direct speech with U+FE30
// "PRESENTATION FORM FOR VERTICAL TWO DOT LEADER" (︰) rather than the
// ordinary horizontal fullwidth colon U+FF1A (：). Unicode's own name for
// the character records its vertical-text heritage: it is the glyph a
// vertical-column edition uses where a horizontal edition would use "：".
// Its presence is a mechanical, byte-level trace that the transcriber
// preserved a vertical-original edition's exact punctuation glyph rather
// than normalising it -- readable without looking at any page image.
export function detect(text, ctx = {}) {
  const vertColon = (text.match(/︰/g) || []).length;
  const horizColon = (text.match(/：/g) || []).length;

  let followedByOpenQuote = 0;
  const chars = Array.from(text);
  for (let i = 0; i < chars.length; i++) {
    if (chars[i] === '︰' && chars[i + 1] === '「') followedByOpenQuote++;
  }

  return {
    fired: vertColon > 0,
    evidence: {
      verticalPresentationColonCount: vertColon,
      horizontalFullwidthColonCount: horizColon,
      verticalColonFollowedByOpenQuote300C: followedByOpenQuote,
      fractionFollowedByOpenQuote: vertColon ? Number((followedByOpenQuote / vertColon).toFixed(3)) : 0,
      unicodeName: 'U+FE30 PRESENTATION FORM FOR VERTICAL TWO DOT LEADER',
    },
  };
}

