// Rule: ws-zh-languageconverter-raw-leak-risk
// Family: extraction-artifact (preventive / regression check, not something
// that fired on the corpus we measured).
// MediaWiki's LanguageConverter markup -{...}- protects or flags a
// character/word for Traditional/Simplified (and regional) variant
// conversion. Measured: it is present in the wikitext of this territory
// (9 occurrences in 史記/卷001 wikitext, 1 in 本草綱目/草之一 wikitext) and
// is FULLY resolved -- 0 occurrences in every corresponding rendered HTML
// and 0 occurrences anywhere in the live_priors chinese-originals corpus
// (checked across all 7 files). That means the pipeline that actually
// produced live_priors used rendered/parsed content, not a raw wikitext
// dump, for this delimiter. This detector exists as a regression guard: if
// a future extraction stage ever ingests raw wikitext (action=raw,
// prop=wikitext) directly as "the text" instead of rendering it first, this
// is the byte signature that will catch the leak before it reaches a
// downstream reader.
export function detect(text, ctx = {}) {
  const openCount = (text.match(/-\{/g) || []).length;
  const closeCount = (text.match(/\}-/g) || []).length;

  return {
    fired: openCount > 0 || closeCount > 0,
    evidence: {
      openDelimiterCount: openCount,
      closeDelimiterCount: closeCount,
      controlNote: 'Expected to fire TRUE on raw wikitext and FALSE on properly rendered/plain text; measured 0/0 on every file in live_priors/11-multi-language/chinese-originals, confirming that corpus is not a raw-wikitext dump for this signal.',
    },
  };
}

