// Rule: ws-zh-page-scan-transclusion-stub
// Family: source-convention
// Not every zh.wikisource.org "work" page is a diplomatic plain-wikitext
// transcription. Some editions (measured: 九章算術 (四部叢刊本), a facsimile
// of a 涵芬樓 print) are scan-backed: the work-namespace page's OWN wikitext
// is a near-empty stub -- a running-head template plus a single
// <pages from="X" to="Y" index="....djvu" /> transclusion tag that pulls
// the real body text from per-scanned-page Page:....djvu/N subpages.
// Measured: 九章算術 (四部叢刊本)/序 is 269 bytes of wikitext, /卷第一 is 286
// bytes -- versus 19-114 KB for the diplomatic (non-scan-backed) pages
// fetched in the same territory (史記, 荀子, 說文解字, 本草綱目, 孟子字義疏證
// subpages). A reader that only looks at the work page's own wikitext length
// would wrongly conclude the chapter is nearly empty; the actual text (and
// its own page-level furniture: running heads, quality banners, vertical-
// writing-mode markers -- see ws-zh-vertical-writing-mode-signal) lives one
// level down, in Page: namespace.
const PAGES_TAG_RE = /<pages\s+from="(\d+)"\s+to="(\d+)"\s+index="([^"]+)"\s*\/>/;

export function detect(text, ctx = {}) {
  const m = text.match(PAGES_TAG_RE);
  const byteLength = Buffer.byteLength(text, 'utf8');

  return {
    fired: !!m,
    evidence: {
      pagesTagFound: !!m,
      fromPage: m ? Number(m[1]) : null,
      toPage: m ? Number(m[2]) : null,
      djvuIndex: m ? m[3] : null,
      pageSpan: m ? Number(m[2]) - Number(m[1]) + 1 : null,
      ownWikitextByteLength: byteLength,
      contrastNote: 'Diplomatic (non-scan-backed) subpages measured in this territory range ~2.4KB-114KB of wikitext; a scan-backed stub with a <pages> tag is typically a few hundred bytes regardless of how many real pages (10-53 in this example) it transcludes.',
    },
  };
}

