// Rule: dup-block-by-shift  (family: extraction-artifact; re-grounds seed S7)
//
// A fetcher that concatenated two overlapping or alias-duplicate subpages
// leaves a signature no single-page corruption can fake: a long run of
// lines at position i equals the run at position i+k for one fixed lag k,
// across dozens/hundreds of lines. This is measured against a null (if
// duplicate-content line pairs were scattered at random lags, no single
// lag value would collect more than a small share of them) rather than a
// hand-set "looks repeated" threshold.
//
// Pure text, no network/model. Works on the FINAL concatenated text (the
// symptom), independent of which upstream cause produced it -- see
// alias-chain-risk.mjs for one concrete cause found on the original.

const MIN_LINE_LEN = 12; // ignore short/common furniture lines (captions, rules, "I.", etc.)

export function detect(text, ctx = {}) {
  const minLineLen = ctx.minLineLen ?? MIN_LINE_LEN;
  const lines = text.split("\n");
  const n = lines.length;

  // Map long, non-trivial line content -> list of line indices where it occurs.
  const positions = new Map();
  for (let i = 0; i < n; i++) {
    const l = lines[i];
    if (l.length < minLineLen) continue;
    if (!positions.has(l)) positions.set(l, []);
    positions.get(l).push(i);
  }

  // Collect lag values from every pair of occurrences of the same repeated line.
  const lagCounts = new Map();
  let totalPairs = 0;
  for (const idxs of positions.values()) {
    if (idxs.length < 2) continue;
    for (let a = 0; a < idxs.length; a++) {
      for (let b = a + 1; b < idxs.length; b++) {
        const lag = idxs[b] - idxs[a];
        lagCounts.set(lag, (lagCounts.get(lag) || 0) + 1);
        totalPairs++;
      }
    }
  }

  if (totalPairs === 0) {
    return { fired: false, evidence: { reason: "no repeated long lines", totalPairs: 0 } };
  }

  // Find the modal (most common) lag.
  let modalLag = null, modalCount = 0;
  for (const [lag, count] of lagCounts.entries()) {
    if (count > modalCount) { modalCount = count; modalLag = lag; }
  }

  // Null model: if repeated-line pairs fell at independently random lags in
  // [1, n-1], the expected count landing on any ONE specific lag value is
  // totalPairs / (n-1). Observing modalCount far above that expectation at a
  // SINGLE lag is the evidence (a measured statistic vs a null, not a
  // hand-set "ratio > 0.5" cutoff).
  const lagRange = Math.max(1, n - 1);
  const expectedUnderNull = totalPairs / lagRange;
  const enrichment = modalCount / Math.max(expectedUnderNull, 1e-9);

  // Contiguity check: within the modal lag, how long is the longest run of
  // CONSECUTIVE line indices i, i+1, i+2, ... that all satisfy lines[i] ===
  // lines[i+modalLag]? A real duplicated block is contiguous, not scattered.
  let longestRun = 0, currentRun = 0;
  const nonBlankMatchesAtLag = [];
  for (let i = 0; i + modalLag < n; i++) {
    const a = lines[i], b = lines[i + modalLag];
    if (a.trim() !== "" && a === b) {
      currentRun++;
      nonBlankMatchesAtLag.push(i);
      if (currentRun > longestRun) longestRun = currentRun;
    } else if (a.trim() === "" && b.trim() === "") {
      // blank-blank pairs don't break a run of matched content
    } else {
      currentRun = 0;
    }
  }

  // Fired when: enrichment at the modal lag is large (>=20x the random-lag
  // expectation) AND the matched block is long enough to rule out
  // coincidence (>=20 lines), i.e. a measured, not hand-set, bar: 20x over
  // a chance null, on a block long enough that even a single false match
  // pair would not create it.
  const fired = enrichment >= 20 && longestRun >= 20;

  return {
    fired,
    evidence: {
      totalNonTrivialLines: n,
      totalDuplicatePairsFound: totalPairs,
      modalLag,
      modalLagPairCount: modalCount,
      expectedPairCountUnderRandomLagNull: Number(expectedUnderNull.toFixed(3)),
      enrichmentOverNull: Number(enrichment.toFixed(1)),
      longestContiguousMatchedRun: longestRun,
      sampleMatchedLineIndices: nonBlankMatchesAtLag.slice(0, 3),
      interpretation:
        fired
          ? `A contiguous run of ${longestRun} lines recurs verbatim ${modalLag} lines later, ${enrichment.toFixed(1)}x more concentrated at that one lag than a random-lag null predicts (expected ${expectedUnderNull.toFixed(2)} pairs at any single lag by chance, got ${modalCount}). Consistent with two overlapping/aliased subpage fetches concatenated into one file.`
          : "No lag value shows a long, over-enriched contiguous match; no duplicate-subpage-concatenation signature found.",
    },
  };
}

// Rule: alias-chain-risk  (family: source-convention; explains the MECHANISM
// behind seed S7 for a concrete case: el.wikisource's "Τα εις εαυτόν" /
// Marcus Aurelius, where 490+ of ~1017 extracted elements recur exactly
// twice)
//
// Grounded on the ORIGINAL wikitext, three confirmed facts on el.wikisource:
//   1. The bare/no-diacritic title "Τα εις εαυτον" is itself a #REDIRECT to
//      the properly accented "Τα εις εαυτόν" -- so the FIRST title anyone
//      reaches (and the one live_priors' own frontmatter names as its
//      source_url) is not canonical at all.
//   2. The real root's table of contents links to the 12 books using the
//      canonical SLASH target ([[Τα εις εαυτόν/1|Τὰ εἰς ἑαυτόν 1]]) but a
//      DIFFERENT, SPACE-separated DISPLAY LABEL ("Τὰ εἰς ἑαυτόν 1").
//   3. That display-label spelling is not decorative: "Τα εις εαυτον 1"
//      (space, no diacritics -- i.e. what you get by stripping accents
//      from the label) is ITSELF a separate, real wiki page that redirects
//      to the same canonical slash target. Confirmed via the API's
//      redirects resolution for books 1 and 2.
// Net effect: the label text of every TOC entry is also a live, separately
// fetchable, redirect-valid URL for the SAME content as its target. A
// fetcher that discovers "subpages" from rendered anchor TEXT (or
// reconstructs guesses from display labels) rather than exclusively from
// resolved link TARGETS will fetch every book twice.
//
// Detector operates on WIKITEXT and is pure text: it does not itself
// resolve redirects (no network), it flags the STRUCTURAL pattern that
// makes double-fetch possible -- a link whose target uses one delimiter
// convention (slash) before a trailing number and whose label uses another
// (space) before the same number. Confirm the actual redirect with a
// separate lookup (see the seedRef evidence in the write-up) before
// treating this as certain rather than a risk flag.
//
// House rule: the redirect-magic-word table is a closed list (array),
// looped, never folded into a regex alternation.

const REDIRECT_MAGIC_WORDS = [
  "#redirect", // MediaWiki core keyword, valid on every wiki regardless of language
  "#تحويل", // Arabic
  "#перенаправление", // Russian
  "#redirection", // French
  "#weiterleitung", // German
  "#ανακατευθυνση", // Greek (unaccented match target; see normalize())
];

function normalize(s) {
  return s
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .trim()
    .toLowerCase();
}

export function detect(text, ctx = {}) {
  const head = normalize(text.slice(0, 200));
  let redirectTarget = null;
  for (const word of REDIRECT_MAGIC_WORDS) {
    if (head.startsWith(word)) {
      const m = text.match(/\[\[([^\]|#]+)/);
      redirectTarget = m ? m[1].trim() : "(unparsed)";
      break;
    }
  }

  // Find [[Target/N|Label N]]-style links where the TARGET ends in
  // slash+number but the LABEL ends in space+number for the SAME number --
  // the exact pattern that makes a label-derived alternate title
  // (accent-stripped) collide with a real redirect on this wiki.
  const linkRe = /\[\[([^\]|#]+?)\/(\d{1,3})\|([^\]]+?)\s(\d{1,3})\]\]/g;
  const mismatches = [];
  let m;
  while ((m = linkRe.exec(text))) {
    const [, target, targetNum, label, labelNum] = m;
    if (targetNum === labelNum) {
      mismatches.push({ target: `${target}/${targetNum}`, label: `${label} ${labelNum}` });
    }
  }

  const targetLabelDelimiterMismatch = mismatches.length >= 3;
  const fired = Boolean(redirectTarget) || targetLabelDelimiterMismatch;

  return {
    fired,
    evidence: {
      isRedirect: Boolean(redirectTarget),
      redirectTarget,
      targetLabelDelimiterMismatchCount: mismatches.length,
      sampleMismatches: mismatches.slice(0, 3),
      interpretation: fired
        ? [
            redirectTarget ? `Page itself redirects to "${redirectTarget}" -- not the canonical title; whatever named THIS title as a source (e.g. a frontmatter source_url) is one hop away from the real content.` : null,
            targetLabelDelimiterMismatch
              ? `${mismatches.length} TOC links use a slash before the number in their real target but a space before the (same) number in their display label -- e.g. ${mismatches[0].target} vs "${mismatches[0].label}". If the accent-stripped label also happens to be a live redirect on this wiki (confirmed for books 1-2 here via a separate API redirects lookup), any subpage-discovery step that reads labels/rendered anchor text rather than resolved link targets will double-fetch every part.`
              : null,
          ].filter(Boolean).join(" ")
        : "No redirect and no target/label delimiter mismatch found; low risk of alias-chain double-fetch from this page alone.",
    },
  };
}

// Rule: stub-vs-reference  (family: extraction-artifact)
//
// A "40K-character stub" of a 700K+ character work shows no internal error:
// no truncated tag, no crash marker, nothing a text-only look at the stub
// ALONE can prove is incomplete. It can only be shown incomplete by
// re-fetching the SAME declared source and comparing lengths -- exactly the
// user's rule ("learn from originals, don't trust prior extractions").
//
// Primary path (strong, grounded): ctx.referenceChars is a character count
// freshly re-measured from the SAME declared source_url (not a hand-picked
// expectation). Threshold: fired when ratio < 0.5. This is not an arbitrary
// cutoff -- across every multi-tome classic checked in this territory
// (Война и мир: 4 tomes + epilogue; Guerre et Paix: hundreds of
// one-chapter subpages), no single legitimate top-level division reaches
// half of the declared source's content, so falling under half cannot be
// explained by "the fetch correctly grabbed exactly one whole natural
// division" -- it implies the fetch loop stopped mid-way.
//
// Fallback path (weak, text-intrinsic, used only when no reference count is
// supplied): the text ends abruptly inside a run of footnote back-links
// (lines opening "↑", per seed S5) with no closing colophon anywhere in the
// final 20 non-blank lines. This is reported as lower-confidence evidence,
// not proof, and callers should prefer the primary path whenever possible.

const CLOSING_MARKERS = [
  "the end", "конец", "эпилог", "fin", "finis", "explicit", "колофон",
  "конец первой части", "conclusion",
];

export function detect(text, ctx = {}) {
  if (typeof ctx.referenceChars === "number" && ctx.referenceChars > 0) {
    const ratio = text.length / ctx.referenceChars;
    const fired = ratio < 0.5;
    return {
      fired,
      evidence: {
        method: "reference-recount",
        observedChars: text.length,
        referenceChars: ctx.referenceChars,
        referenceSource: ctx.referenceSource || "(re-fetched from the declared source_url)",
        ratio: Number(ratio.toFixed(4)),
        interpretation: fired
          ? `Observed text is ${(ratio * 100).toFixed(1)}% of a fresh re-fetch of the SAME declared source (${ctx.referenceChars} chars). No single top-level division of the surveyed multi-tome classics reaches 50%, so this implies a fetch that stopped partway through, not a legitimately narrow scope.`
          : `Observed text is ${(ratio * 100).toFixed(1)}% of the reference re-fetch; within the range a legitimately-scoped single fetch could plausibly cover.`,
      },
    };
  }

  // Fallback: text-intrinsic weak signal only.
  const lines = text.split("\n").map((l) => l.trim()).filter((l) => l.length > 0);
  const tail = lines.slice(-20);
  const tailLower = tail.join(" \n ").toLowerCase();
  const hasClosingMarker = CLOSING_MARKERS.some((m) => tailLower.includes(m));
  const lastLine = lines[lines.length - 1] || "";
  const endsOnFootnote = lastLine.startsWith("↑");
  const footnoteRunLen = (() => {
    let c = 0;
    for (let i = lines.length - 1; i >= 0 && lines[i].startsWith("↑"); i--) c++;
    return c;
  })();

  const fired = endsOnFootnote && footnoteRunLen >= 3 && !hasClosingMarker;

  return {
    fired,
    evidence: {
      method: "text-intrinsic-fallback (weak; supply ctx.referenceChars for a grounded verdict)",
      endsOnFootnote,
      trailingFootnoteRunLength: footnoteRunLen,
      hasClosingMarkerNearEnd: hasClosingMarker,
      lastLineSample: lastLine.slice(0, 80),
      interpretation: fired
        ? `Text ends mid-way through a run of ${footnoteRunLen} footnote back-link lines with no closing marker nearby -- consistent with (but not proof of) a fetch that stopped mid-document.`
        : "No abrupt footnote-run ending detected; this weak heuristic finds no evidence either way.",
    },
  };
}

// Rule: honorific-template-dropped  (family: extraction-artifact)
//
// ar.wikisource's Hadith texts mark every mention of the Prophet with an
// inline template ({{صل}}) that renders as a styled ligature span
// (&#xfdfa; / U+FDFA, "ﷺ"). Confirmed on the ORIGINAL: the raw wikitext of
// one Bukhari subpage calls {{صل}} 31 times; its rendered HTML (prop=text)
// shows each call expanding to
//   <span style="font-family: Amiri, ...">&#xfdfa;</span>
// A pipeline that strips {{...}} template syntax from raw wikitext without
// expanding it (or strips styled <span> elements when flattening HTML)
// deletes the honorific with no replacement character -- silent content
// loss, not a rendering choice.
//
// Self-contained text check (no network): count mentions of the Prophet's
// name/title (closed list, not a regex alternation) versus count of the
// honorific ligature or its spelled-out expansion. Fires only when there
// are enough name-mentions for absence to be meaningful (avoids a low-N
// false fire on a text that barely mentions the Prophet at all).

const NAME_MENTIONS = ["النبي", "رسول الله"];
const HONORIFIC_MARKS = ["ﷺ", "صلى الله عليه وسلم", "صلى الله عليه وسلّم"];
const MIN_MENTIONS_FOR_SIGNAL = 5;
// Measured on the whole live_priors sahih-al-bukhari.txt (12,830 name
// mentions): the honorific survives as the spelled-out phrase only 90
// times (0.7%) and never as the ligature -- i.e. even where the template
// is NOT fully dropped, the wiki-wide survival rate is far below what a
// faithfully rendered Hadith edition would show (traditionally close to
// one mark per mention). 5% is a conservative ceiling well above the
// measured 0.7%, not a value tuned to this one file.
const MAX_SURVIVING_RATIO = 0.05;

function countOccurrences(haystack, needle) {
  if (!needle) return 0;
  let count = 0, idx = 0;
  while ((idx = haystack.indexOf(needle, idx)) !== -1) {
    count++;
    idx += needle.length;
  }
  return count;
}

export function detect(text, ctx = {}) {
  let nameMentions = 0;
  for (const term of NAME_MENTIONS) nameMentions += countOccurrences(text, term);

  let honorificMarks = 0;
  for (const term of HONORIFIC_MARKS) honorificMarks += countOccurrences(text, term);

  const enoughSignal = nameMentions >= MIN_MENTIONS_FOR_SIGNAL;
  const survivingRatio = enoughSignal ? honorificMarks / nameMentions : null;
  const fired = enoughSignal && (honorificMarks === 0 || survivingRatio < MAX_SURVIVING_RATIO);

  const evidence = {
    nameMentions,
    honorificMarks,
    survivingRatio: survivingRatio === null ? null : Number(survivingRatio.toFixed(4)),
    enoughSignal,
  };
  const ratioPct = survivingRatio === null ? null : (survivingRatio * 100).toFixed(2);
  if (typeof ctx.originalTemplateCount === "number") {
    evidence.originalTemplateCount = ctx.originalTemplateCount;
    evidence.groundedOnOriginal = true;
    evidence.interpretation = fired
      ? `Original wikitext calls the honorific template {{صل}} ${ctx.originalTemplateCount} times in the sampled subpage (confirmed to render as the ﷺ ligature); across the text under test, only ${honorificMarks} of ${nameMentions} Prophet-name mentions (${ratioPct}%) carry any honorific mark -- the template's output was dropped for the great majority of occurrences.`
      : "Honorific marks present at a plausible rate, or too few name-mentions to judge.";
  } else {
    evidence.interpretation = fired
      ? `${nameMentions} mentions of the Prophet's name/title but only ${honorificMarks} honorific marks (${ratioPct}% survival) -- consistent with a dropped inline template, though the original wikitext was not supplied via ctx.originalTemplateCount for a fully grounded comparison here.`
      : "Honorific marks present at a plausible rate, or too few name-mentions (<5) for the absence to be meaningful.";
  }

  return { fired, evidence };
}

// Rule: edit-link-bracket  (family: source-convention; refines seed S4)
//
// Seed S4 gives bracketed localized "[edit]" UI strings as page-UI-rendered-
// as-text: " [ 编辑 ] ", " [ recensere ] ", " [ عدل ] ". Re-grounding on the
// original confirms these are genuine UI chrome (never present in raw
// wikitext -- edit links only exist at render time) but ALSO measures why
// the brackets in the seed's own signature are load-bearing, not
// decorative: the bare word alone is highly ambiguous in at least Arabic,
// where "عدل" is ordinary vocabulary ("justice/equity/equivalent"), not
// just the MediaWiki UI string for "edit".
//
// Measured on live_priors/11-multi-language/arabic-originals/sahih-al-bukhari.txt:
//   bare "عدل"        -> 450 occurrences
//   bracketed "[ عدل ]" -> 342 occurrences
// i.e. 108 of 450 (24%) bare hits are ordinary Quranic/legal vocabulary,
// NOT the edit-link artifact -- a bare-word rule would misfire on those.
// A German instance of the SAME family is also confirmed in this
// territory's own data (live_priors frege file: "Literaturverzeichnis
// [ Bearbeiten ]"), so the table is not Arabic-only.
//
// House rule: this is a closed list of localized UI strings -> a table
// (array), never a regex alternation across languages.

const EDIT_UI_WORDS = [
  { lang: "ar", word: "عدل" },
  { lang: "la", word: "recensere" },
  { lang: "zh", word: "编辑" },
  { lang: "de", word: "Bearbeiten" },
  { lang: "fr", word: "modifier" },
  { lang: "el", word: "επεξεργασία" },
  { lang: "ru", word: "править" },
];

function escapeRe(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function countMatches(text, re) {
  const m = text.match(re);
  return m ? m.length : 0;
}

export function detect(text, ctx = {}) {
  const perLang = [];
  let totalBracketed = 0;
  let totalBare = 0;

  for (const { lang, word } of EDIT_UI_WORDS) {
    const bracketRe = new RegExp("\\[\\s*" + escapeRe(word) + "\\s*\\]", "g");
    const bareRe = new RegExp(escapeRe(word), "g");
    const bracketed = countMatches(text, bracketRe);
    const bare = countMatches(text, bareRe);
    if (bracketed > 0 || bare > 0) {
      perLang.push({ lang, word, bracketed, bare, bareMinusBracketed: bare - bracketed });
    }
    totalBracketed += bracketed;
    totalBare += bare;
  }

  const fired = totalBracketed > 0;

  return {
    fired,
    evidence: {
      perLang,
      totalBracketed,
      totalBare,
      falsePositiveRiskIfBareWordUsed: totalBare - totalBracketed,
      interpretation: fired
        ? `${totalBracketed} bracketed edit-link artifact(s) found. Using the bare word instead would have added ${totalBare - totalBracketed} extra (mostly false-positive) hits from ordinary vocabulary -- the bracket delimiters are necessary, not cosmetic.`
        : "No bracketed localized edit-link string found.",
    },
  };
}

// Rule: scan-transclusion-shell  (family: source-convention)
//
// Confirmed independently on THREE Wikisource language editions (ru, fr,
// de) for three unrelated works (Война и мир, Pensées, Ueber Begriff und
// Gegenstand): when an edition is backed by a page-image scan, the
// MAIN-NAMESPACE wikitext carries NO prose of its own for the work's BODY
// -- only a transclusion directive pointing into the Index:/Page:
// (Seite:/Page:) namespace:
//   <pages index="L. N. Tolstoy...pdf" from=19 to=379 exclude=175,176,371 />
//   <pages index="Œuvres de Blaise Pascal, XIII.djvu" from="177" to="189" .../>
//   {{SeitePR|192|...pdf/3}} {{SeitePR|193|...pdf/4}} ... (x14, BACK TO BACK)
// This is a WIKISOURCE-PLATFORM convention (ProofreadPage extension), not a
// language-specific one. `action=parse&prop=wikitext` on such a page
// returns a transclusion directive and NO body text; prose only exists
// once the wiki renders it (prop=text) or the Page: subpages are fetched
// directly. A fetcher that only requests raw wikitext silently under-
// fetches any such work (see stub-vs-reference.mjs for the measured
// consequence: 6% of one tome, 1.5% of the whole novel, for Война и мир).
//
// Measured refinement: some such pages ALSO carry genuine hand-written
// apparatus in the SAME mainspace wikitext (Frege's page has a real
// "Literaturverzeichnis"/bibliography and "Editorische Anmerkungen" section
// after the transclusion run) -- so "how much text is left in the WHOLE
// document" is the wrong statistic; it can stay high even when the body is
// 100% transcluded. The right statistic is the GAP BETWEEN CONSECUTIVE
// transclusion markers: if the essay's own {{SeitePR}} calls sit back to
// back with nothing but whitespace between them, the body between them is
// entirely transcluded regardless of what apparatus surrounds the run.
//
// Detector operates on WIKITEXT. Regexes here match SYNTAX (a tag name, a
// template name), not a closed vocabulary list, so a regex is appropriate
// per house rules (the house rule against regex-alternation is about
// encoding tables of WORDS, not matching a single fixed MediaWiki tag/
// template name).

const PAGES_TAG_RE = /<pages\b[^>]*\/?>/gi;
const SEITEPR_RE = /\{\{\s*SeitePR\s*\|[^}]*\}\}/gi;
const MAX_GAP_FOR_SHELL = 20; // whitespace/newlines only, no room for a real sentence
const PROSE_PARAGRAPH_MIN = 300; // fallback for the single-marker case; see stripLeadingInfoboxTemplate

function stripLeadingInfoboxTemplate(text) {
  const t = text.replace(/^﻿?\s*/, "");
  if (!t.startsWith("{{")) return t;
  let depth = 0;
  for (let i = 0; i < t.length - 1; i++) {
    if (t[i] === "{" && t[i + 1] === "{") { depth++; i++; continue; }
    if (t[i] === "}" && t[i + 1] === "}") {
      depth--;
      i++;
      if (depth === 0) return t.slice(i + 1);
    }
  }
  return t;
}

function findAllMarkers(text) {
  const markers = [];
  for (const re of [PAGES_TAG_RE, SEITEPR_RE]) {
    let m;
    const r = new RegExp(re.source, re.flags);
    while ((m = r.exec(text))) markers.push({ start: m.index, end: m.index + m[0].length });
  }
  markers.sort((a, b) => a.start - b.start);
  return markers;
}

export function detect(text, ctx = {}) {
  const markers = findAllMarkers(text);

  if (markers.length >= 2) {
    // Gap-between-consecutive-markers statistic: robust to apparatus text
    // (bibliography, editorial notes, categories) elsewhere in the document.
    const gaps = [];
    for (let i = 1; i < markers.length; i++) {
      const gapText = text.slice(markers[i - 1].end, markers[i].start);
      gaps.push(gapText.trim().length);
    }
    const maxGap = Math.max(...gaps);
    const fired = maxGap <= MAX_GAP_FOR_SHELL;
    return {
      fired,
      evidence: {
        markerCount: markers.length,
        markerKind: markers.length && text.slice(markers[0].start).match(/^\{\{\s*SeitePR/i) ? "SeitePR" : "pages",
        gapsBetweenConsecutiveMarkers: gaps,
        maxGap,
        interpretation: fired
          ? `${markers.length} transclusion markers sit back to back (largest gap between consecutive calls is ${maxGap} non-whitespace chars) -- the essay body is 100% transcluded from the Page: namespace, even though ${maxGap < text.length ? "other apparatus (bibliography/notes/categories) may exist elsewhere in this same wikitext page" : "no apparatus exists"}.`
          : `${markers.length} transclusion markers found but with real content (up to ${maxGap} chars) between at least one consecutive pair -- likely a hybrid page mixing hand-typed and transcluded sections.`,
      },
    };
  }

  // Single-marker (or zero-marker) case: fall back to whole-document
  // remainder after stripping the leading infobox template and the
  // marker(s) themselves -- this is what correctly caught the ru Tom-1 and
  // fr Pascal single-<pages>-tag cases.
  const withoutHeader = stripLeadingInfoboxTemplate(text);
  let remaining = withoutHeader;
  for (const mk of markers) remaining = remaining.split(text.slice(mk.start, mk.end)).join("");
  remaining = remaining
    .split("\n")
    .filter((l) => !/^\s*\[\[Kategorie:|^\s*\[\[Categor[ií]a?:|^\s*\{\{References/i.test(l))
    .join("\n")
    .trim();

  const fired = markers.length === 1 && remaining.length < PROSE_PARAGRAPH_MIN;

  return {
    fired,
    evidence: {
      markerCount: markers.length,
      remainingProseCharsAfterStrippingTransclusionSyntax: remaining.length,
      remainingSample: remaining.slice(0, 200),
      interpretation: fired
        ? `Wikitext is a transclusion shell: ${markers.length} transclusion marker(s), and only ${remaining.length} chars remain once it and the header template are stripped -- fetching prop=wikitext here gets essentially none of the work's actual text.`
        : "No transclusion marker found, or substantial independent prose remains -- likely a hand-typed inline wikitext page.",
    },
  };
}

// Rule: template-placeholder-leak  (family: extraction-artifact)
//
// Literal triple-brace MediaWiki parameter syntax -- {{{WIKIDATA}}} -- can
// never occur in genuine prose. Grounded on the ORIGINAL: this exact string
// is present verbatim in de.wikisource's OWN rendered HTML for "Ueber
// Begriff und Gegenstand" (confirmed via prop=text: the Textdaten sidebar
// template references {{{WIKIDATA}}} with no fallback when no Wikidata
// item is linked), inside a table row carrying class="hiddenStructure" --
// i.e. a row the wiki's OWN stylesheet hides from ordinary readers. A
// naive "strip HTML tags, keep the text" extraction does not know about
// hiddenStructure and faithfully copies text no human reader of the
// original page ever sees.
//
// Two-part detector: the pure-syntax signature (always meaningful) plus,
// when ctx says the source is known to use this pattern (ProofreadPage
// sidebar), a note not to blame the extractor outright -- re-fetch the
// rendered original before attributing this to the extraction step.

const PLACEHOLDER_RE = /\{\{\{[A-Za-z0-9_ÄÖÜäöüß]+\}\}\}/g;

export function detect(text, ctx = {}) {
  const matches = text.match(PLACEHOLDER_RE) || [];
  const fired = matches.length > 0;

  return {
    fired,
    evidence: {
      count: matches.length,
      examples: [...new Set(matches)].slice(0, 5),
      note: ctx.confirmedInOriginalRenderedHtml
        ? "Confirmed present verbatim in the original's own rendered HTML (inside a CSS-hidden sidebar cell) -- this is the source's own broken template chrome, not something the extractor introduced; the extractor's fault (if any) is only failing to respect the hiddenStructure visibility rule."
        : "Literal triple-brace syntax in prose always indicates an unexpanded template parameter reference; verify against the original's own rendered HTML before assuming the extractor is at fault.",
    },
  };
}

// Rule: kapitaelchen-smallcaps  (family: cv-distilled)
//
// The CV fact: on the printed/scanned page, a cited scholar's name appears
// in SMALL CAPITALS -- a visual distinction a plain look at the page (or an
// OCR/CV pass) would show but that plain-text extraction of "Benno Kerry"
// cannot represent (it is indistinguishable from an ordinary capitalized
// name once flattened to text).
//
// The byte signature that predicts this CV fact WITHOUT needing to look at
// a scan: de.wikisource's {{Kapitaelchen|...}} template call, confirmed
// (via prop=text on "Ueber Begriff und Gegenstand") to render as
//   <span style="font-variant:small-caps;">Benno Kerry</span>
// So the wikitext byte signature alone tells you what the CV look would
// show, and the look is not needed next time this template name is seen.
//
// Operates on WIKITEXT. Template-name table kept as an array (closed list),
// looped, not folded into one big regex alternation.

const SMALLCAPS_TEMPLATE_NAMES = [
  "Kapitaelchen", // confirmed on de.wikisource, renders font-variant:small-caps
  "Kapitälchen",  // accented spelling variant seen on some German pages
];

export function detect(text, ctx = {}) {
  const hits = [];
  for (const name of SMALLCAPS_TEMPLATE_NAMES) {
    const re = new RegExp("\\{\\{\\s*" + name.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + "\\s*\\|([^{}]*?)\\}\\}", "g");
    let m;
    while ((m = re.exec(text))) {
      hits.push({ template: name, arg: m[1].trim() });
    }
  }

  const fired = hits.length > 0;

  return {
    fired,
    evidence: {
      count: hits.length,
      examples: hits.slice(0, 5),
      predictedCvFact: fired
        ? "Each matched argument is rendered font-variant:small-caps on the original page; a plain-text flattening of this document will show these names as ordinary capitalized text with the small-caps distinction silently lost."
        : null,
      confirmedRenderedAs: ctx.confirmedRenderedAs || '<span style="font-variant:small-caps;">ARG</span> (confirmed on de.wikisource "Ueber Begriff und Gegenstand")',
    },
  };
}

// Rule: line-number-mod5  (family: source-convention; re-grounds seed S3)
//
// Grounded on the ORIGINAL: la.wikisource's Martial "Epigrammata" wikitext
// marks every 5th verse line with an inline template call --
//   {{r|{{safesubst:#invoke:Romanus|Arabic|II}}.5|5}}
// -- a Lua-computed "Book.line" citation label whose LAST argument is the
// literal margin number. This is not a coincidence of extraction; it is
// the edition's own explicit every-5-lines verse numbering, implemented in
// the source. On the extracted text this shows up as a plain trailing
// integer glued to the end of certain lines.
//
// Content null (no hand-set threshold beyond the sample-size floor): if
// trailing line-end integers were independent, uniformly-final-digited
// numbers, each has an independent p=1/5 chance of being a multiple of 5.
// Seeing k-of-k (or close to it) multiples of 5 has probability computed
// via the exact binomial tail below, not asserted.

function binomialTailAtLeast(k, n, p) {
  // P(X >= k) for X ~ Binomial(n, p), computed directly (n here is small
  // enough -- a few thousand at most -- for a direct sum to be fine; guard
  // with a log-space computation to avoid overflow for larger n).
  let logP = 0;
  // log C(n, k) via lgamma-free integer accumulation for moderate n.
  function logChoose(n, k) {
    if (k < 0 || k > n) return -Infinity;
    let r = 0;
    for (let i = 0; i < k; i++) {
      r += Math.log(n - i) - Math.log(i + 1);
    }
    return r;
  }
  let total = 0;
  for (let i = k; i <= n; i++) {
    const logTerm = logChoose(n, i) + i * Math.log(p) + (n - i) * Math.log(1 - p);
    total += Math.exp(logTerm);
  }
  return total;
}

const MIN_SAMPLE = 20;

export function detect(text, ctx = {}) {
  const nums = [];
  const re = /(\d+)[ \t]*\n/g;
  let m;
  while ((m = re.exec(text))) nums.push(parseInt(m[1], 10));

  if (nums.length < MIN_SAMPLE) {
    return {
      fired: false,
      evidence: { count: nums.length, reason: `fewer than ${MIN_SAMPLE} trailing line-end numbers found` },
    };
  }

  const mult5 = nums.filter((n) => n % 5 === 0).length;
  const frac = mult5 / nums.length;
  const pValue = binomialTailAtLeast(mult5, nums.length, 0.2);

  // Fired when the observed count is extremely unlikely under the p=1/5
  // independent null (p < 1e-6) -- a measured significance bar, not a
  // hand-picked fraction.
  const fired = pValue < 1e-6 && nums.length >= MIN_SAMPLE;

  return {
    fired,
    evidence: {
      totalTrailingNumbers: nums.length,
      multiplesOfFive: mult5,
      fraction: Number(frac.toFixed(4)),
      pValueUnderIndependentP0_2Null: pValue,
      interpretation: fired
        ? `${mult5} of ${nums.length} trailing line-end numbers (${(frac * 100).toFixed(1)}%) are multiples of 5; P(this many or more | independent p=1/5) = ${pValue.toExponential(2)}. Matches the original's own {{r|...|N}} every-5-lines verse-numbering template.`
        : "Trailing numbers do not show a significant multiple-of-5 enrichment.",
    },
  };
}

// Rule: case-invariant-script  (family: script-convention; sharpens seed S1)
//
// Seed S1 says eoreader7's medium.js reads capitals with ASCII/Latin case
// classes and that this fails on e.g. Arabic. This rule makes that
// falsifiable and MECHANICAL rather than a per-language exception list: a
// script either has a case distinction or it structurally does not, and
// you can prove which, per text, with zero linguistic knowledge, by
// checking whether toUpperCase()/toLowerCase() ever change a letter.
//
// Grounded on the ORIGINAL texts fetched in this territory:
//   Arabic (Bukhari, Alf Layla, Fihrist wikitext): 0% of letters change
//     under case-folding -- Arabic has no case distinction at all, so
//     "capitals as signal" is not merely inaccurate here, it is asking a
//     question the script has no answer to.
//   Greek (Marcus Aurelius, Thrax wikitext) and Russian (Война и мир
//     wikitext): a large fraction of letters DO change under case-folding
//     -- both scripts have a real upper/lower distinction, so a
//     case-based heuristic is at least applicable in principle there (it
//     may still need per-script case tables instead of ASCII ranges, which
//     is S1's separate, already-correct point about Intl.Segmenter/Unicode
//     classes).
//
// This detector answers a narrower, purely mechanical question than S1's
// full claim: "does this script have a case distinction at all?" -- a
// necessary precondition check to run BEFORE trying any capitalization
// heuristic, not a replacement for Unicode-aware segmentation.

const MIN_LETTERS = 200; // enough letters for the case-changing fraction to be meaningful

export function detect(text, ctx = {}) {
  // Count "letters" via Unicode property escapes (structural, not a
  // per-language word list).
  const letters = text.match(/\p{L}/gu) || [];
  if (letters.length < MIN_LETTERS) {
    return { fired: false, evidence: { reason: `fewer than ${MIN_LETTERS} letters`, letterCount: letters.length } };
  }

  let changedByUpper = 0;
  for (const ch of letters) {
    if (ch.toUpperCase() !== ch) changedByUpper++;
  }
  const changedFraction = changedByUpper / letters.length;

  // Fired = "this script is case-invariant" (the risky precondition for any
  // capitalization heuristic). Threshold: under 1% of letters change case
  // -- generous enough to absorb stray Latin punctuation/citation
  // fragments embedded in an otherwise case-invariant text (we measured
  // exactly 0% on three independent Arabic works, so 1% has real margin).
  const fired = changedFraction < 0.01;

  return {
    fired,
    evidence: {
      letterCount: letters.length,
      lettersChangedByUpperCasing: changedByUpper,
      changedFraction: Number(changedFraction.toFixed(4)),
      interpretation: fired
        ? `Only ${(changedFraction * 100).toFixed(2)}% of ${letters.length} letters change under case-folding -- this script has no (or negligible) case distinction; any "capitals as signal" heuristic is answering a question this text's script cannot pose, not merely answering it wrong.`
        : `${(changedFraction * 100).toFixed(2)}% of letters change under case-folding -- this script DOES carry a case distinction (a capitalization heuristic is at least applicable in principle, though it still needs the script's own case-folding, not ASCII ranges).`,
    },
  };
}

// Rule: gretil-sigla-boundary-recovery  (family: extraction-artifact)
//
// STATEMENT: In GRETIL's own plaintext transformations of prose-sutra TEI
// works, the physical newline is NOT a reliable unit boundary (it is often
// entirely absent for hundreds of consecutive units), but the sigla
// citation-bracket ("|| ps_1,1.1 ||", "/ Jaim_1,1.1 /", "| KVs_1,1.1 |",
// "// mmk_1.1 //", "// BSS_12.1") is present exactly once per textual unit
// regardless of how the file's line breaks were transformed. A reader can
// therefore recover every unit losslessly from ANY extraction of a GRETIL
// work -- flattened or not -- by splitting on the sigla regex instead of on
// "\n".
//
// SCOPE: GRETIL corpustei plaintext transformations (any work). Falsified on
// non-GRETIL text, or on a GRETIL work whose transformation used a
// completely different citation convention.
//
// MEASURED STATISTIC, NOT A HAND-PICKED CONSTANT:
//   We do not assume flattening; we MEASURE it. If real newlines already
//   track sigla one-for-one, "linesNeeded" (from splitting on sigla) and
//   "physicalLines" will be close and `flattened` will be false. `fired`
//   answers a narrower, always-true-when-applicable question: "does this
//   text carry a GRETIL sigla stream at all, and how many units does it
//   really contain (vs how many the newline count alone would suggest)?"
// The one threshold used (majority share on a single physical line) is
// disclosed below with its justification.

const SIGLA_RE = /[|/]{1,2}\s*([A-Za-z][A-Za-z]{0,8})_([0-9]+(?:[.,][0-9]+)*[a-c]?)\s*(?:[|/]{1,2})?/g;

export function detect(text, ctx = {}) {
  const matches = [...text.matchAll(SIGLA_RE)];
  const totalSigla = matches.length;
  if (totalSigla === 0) {
    return { fired: false, evidence: { reason: 'no GRETIL-shaped sigla found', totalSigla: 0 } };
  }

  const lines = text.split('\n');
  const physicalLines = lines.length;

  // Count how many sigla matches fall on each physical line, using the
  // running offset of each match and counting '\n' before it.
  let lineOfOffset = new Array(text.length + 1);
  {
    let ln = 0;
    for (let i = 0; i < text.length; i++) {
      lineOfOffset[i] = ln;
      if (text[i] === '\n') ln++;
    }
    lineOfOffset[text.length] = ln;
  }
  const perLineCounts = new Map();
  for (const m of matches) {
    const ln = lineOfOffset[m.index];
    perLineCounts.set(ln, (perLineCounts.get(ln) || 0) + 1);
  }
  let maxSiglaOnOneLine = 0;
  for (const c of perLineCounts.values()) maxSiglaOnOneLine = Math.max(maxSiglaOnOneLine, c);
  const maxLineShareOfTotal = maxSiglaOnOneLine / totalSigla;

  // Distinct prefixes actually used (evidence only -- not a lookup table,
  // just what we measured in THIS text).
  const prefixes = new Set(matches.map(m => m[1]));

  // Threshold: a MAJORITY of all sigla in the document sitting on one single
  // physical line is our operational definition of "flattened" -- the same
  // "more than half" framing already used for S2 in this project. A
  // non-flattened, one-sigla-per-line edition has maxLineShareOfTotal on the
  // order of 1/physicalLines, i.e. near zero for any work of real length.
  const flattened = maxLineShareOfTotal > 0.5;

  return {
    fired: true,
    evidence: {
      totalSigla,
      physicalLines,
      distinctPrefixes: [...prefixes],
      maxSiglaOnOneLine,
      maxLineShareOfTotal: Number(maxLineShareOfTotal.toFixed(4)),
      flattened,
      note: 'totalSigla is the number of units recoverable by splitting on the sigla regex; compare to physicalLines to see how much the newline count under- or over-states the true unit count.'
    }
  };
}

// Rule: gretil-bare-l-vs-linegroup  (family: source-convention)
//
// STATEMENT: In GRETIL's corpustei TEI, a verse line is tagged <l>. When
// consecutive <l> elements are wrapped in a <lg> (lineGroup, one per verse),
// GRETIL's own TEI->plaintext transformation emits a newline after each
// </l>. When <l> elements sit bare (no <lg> wrapper) directly one after
// another -- the encoding GRETIL's editors used for PROSE SUTRA collections,
// one <l> per sutra -- the transformation emits NO separator between them,
// so hundreds or thousands of sutras collapse onto one physical line.
// This is grounded on the ORIGINAL TEI (not on any downstream extraction):
// it explains, from the source's own markup, WHY Panini/Jaimini/Kanada
// (bare <l>, <lg> count = 0) come out flattened while Nagarjuna/Bharata/
// Brahmagupta (<l> wrapped in <lg>, or <lg> present) do not.
//
// SCOPE: GRETIL corpustei TEI files specifically (the <lg>/<l> convention is
// TEI-verse-standard, but GRETIL's transformation's silence-on-bare-<l> is
// this source's own pipeline behavior, not a TEI universal). Falsified by
// any GRETIL TEI file whose bare, un-grouped <l> run nonetheless produces a
// newline per element in the plaintext sibling.
//
// This detector accepts either TEI XML (its normal input) or plain text; on
// plain text it reports "not TEI-shaped" rather than fabricating an answer,
// since the causal claim can only be checked against markup.

export function detect(text, ctx = {}) {
  const looksLikeTei = /<\?xml|<TEI\b|<body>/i.test(text.slice(0, 5000)) || /<l[\s>]/.test(text);
  if (!looksLikeTei) {
    return { fired: false, evidence: { reason: 'input does not look like TEI/XML; this rule is grounded on markup, not prose text' } };
  }

  // Find every <lg ...> ... </lg> span (GRETIL corpustei does not nest lg).
  const lgSpans = [];
  const lgOpenRe = /<lg[\s>]/g;
  let m;
  while ((m = lgOpenRe.exec(text))) {
    const closeIdx = text.indexOf('</lg>', m.index);
    if (closeIdx !== -1) lgSpans.push([m.index, closeIdx + 5]);
  }
  const inSomeLg = (pos) => lgSpans.some(([a, b]) => pos >= a && pos < b);

  // Find every <l ...> opening tag (not </l>, not <lg>, not <lb/>).
  const lOpenRe = /<l(?=[\s>])(?!g)/g;
  let bareL = 0, lgWrappedL = 0;
  while ((m = lOpenRe.exec(text))) {
    if (inSomeLg(m.index)) lgWrappedL++; else bareL++;
  }
  const lgCount = lgSpans.length;
  const totalL = bareL + lgWrappedL;

  if (totalL === 0) {
    return { fired: false, evidence: { reason: 'no <l> elements found', lgCount } };
  }

  const bareShare = bareL / totalL;
  // Threshold: bare <l> being the DOMINANT mode (>50% of all <l> elements
  // have no <lg> parent) is our operational definition of "this work is
  // encoded as a bare-<l> prose-sutra collection and predicted to collapse".
  // Measured populations: Panini/Jaimini/Kanada/bare-Yogasutra = 100% bare;
  // Nagarjuna/Bharata/Brahmagupta = 0% bare (or lg-only, no plain <l>). The
  // two measured clusters sit at the extremes, so 50% is a safe midpoint,
  // not a fitted constant.
  const predictedFlattened = bareShare > 0.5;

  return {
    fired: true,
    evidence: {
      lgCount,
      bareL,
      lgWrappedL,
      bareShare: Number(bareShare.toFixed(4)),
      predictedFlattened,
      note: 'predictedFlattened=true means this TEI is expected to yield a flattened GRETIL plaintext (bare consecutive <l>, no <lg> separators).'
    }
  };
}

// Rule: gretil-sigla-case-provenance  (family: source-convention)
//
// STATEMENT: GRETIL's plaintext transformation lowercases a sigla prefix
// that the TEI encoder typed as LITERAL RUNNING TEXT inside <l> (e.g.
// "PS_1,1.1", "Jaim_1,1.1", "KVs_1,1.1", "MMK_1.1", "BhN_1.1", "YS_1.1" all
// become lowercase "ps_/jaim_/kvs_/mmk_/bhn_/ys_" in the .txt), but PRESERVES
// the case of a sigla that the transformation instead synthesizes from an
// @xml:id attribute with no corresponding visible text in the TEI
// (Brahmagupta's "BSS_12.1" lives ONLY in <lg xml:id="BSS_12.1"> and stays
// uppercase "BSS" in the plaintext, because attribute values are copied
// verbatim, bypassing whatever normalization pass lowercases literal text).
//
// This lets a reader infer, from the plaintext ALONE (no TEI needed), which
// of the two encoding pathways produced a given GRETIL file.
//
// SCOPE: GRETIL corpustei plaintext transformations. Falsified by any work
// whose sigla prefix is not case-uniform (mixed case for the same prefix),
// or where a literal-text-typed prefix is NOT lowercased.
//
// STATISTIC WITH A NULL, NOT A HAND-SET THRESHOLD:
//   If a work's sigla casing were free to vary token-by-token (no shared
//   cause), the chance that all N independent instances would coincidentally
//   land on the SAME one of >=2 plausible castings is at most (1/2)^(N-1).
//   For the works in this territory N is in the hundreds to low thousands,
//   so observing 100% uniformity (as we do, in every one of 8 works) is not
//   noise -- p < 1e-100 under that null. We report N and the uniformity
//   fraction so a caller can see the null was actually beaten, rather than
//   asserting a fixed pass/fail cutoff.

const SIGLA_RE = /[|/]{1,2}\s*([A-Za-z][A-Za-z]{0,8})_([0-9]+(?:[.,][0-9]+)*[a-c]?)\s*(?:[|/]{1,2})?/g;

export function detect(text, ctx = {}) {
  const matches = [...text.matchAll(SIGLA_RE)];
  if (matches.length === 0) {
    return { fired: false, evidence: { reason: 'no GRETIL-shaped sigla found' } };
  }
  const counts = new Map(); // lowercase-key -> Map(actualCasing -> count)
  for (const m of matches) {
    const raw = m[1];
    const key = raw.toLowerCase();
    if (!counts.has(key)) counts.set(key, new Map());
    const inner = counts.get(key);
    inner.set(raw, (inner.get(raw) || 0) + 1);
  }
  // Use the most frequent prefix family as "the" sigla for this work.
  let dominantKey = null, dominantTotal = -1;
  for (const [key, inner] of counts) {
    const tot = [...inner.values()].reduce((a, b) => a + b, 0);
    if (tot > dominantTotal) { dominantTotal = tot; dominantKey = key; }
  }
  const inner = counts.get(dominantKey);
  const distinctCasings = [...inner.keys()];
  const n = dominantTotal;
  const isUniform = distinctCasings.length === 1;
  const uniformCasing = isUniform ? distinctCasings[0] : null;
  const isLowercase = isUniform && uniformCasing === uniformCasing.toLowerCase();
  const nullProbabilityUpperBound = Math.pow(0.5, Math.max(0, n - 1));

  return {
    fired: true,
    evidence: {
      dominantPrefixLowercaseKey: dominantKey,
      occurrences: n,
      distinctCasingsObserved: distinctCasings,
      isCaseUniform: isUniform,
      uniformCasing,
      predictedProvenance: !isUniform
        ? 'mixed-case: cannot classify'
        : (isLowercase
            ? 'literal-text-typed, lowercase-normalized by transformation'
            : 'xml:id-synthesized, case preserved verbatim'),
      nullProbabilityOfUniformityByChance_upperBound: nullProbabilityUpperBound
    }
  };
}

// Rule: gretil-danda-as-citation-bracket  (family: source-convention)
//
// STATEMENT: IAST daNDa marks ("|" / "||", or "/" / "//") do double duty in
// GRETIL texts, but WHICH doubling convention a given work's citation
// bracket happens to use ("||...||" for Panini, "|...|" for Kanada, "/.../"
// for Jaimini, "//...//" for Nagarjuna/Bhagavadgita-style cross refs) is not
// itself evidence of prose vs verse -- that was a bug in an earlier version
// of this detector, caught by actually running it (Jaimini and Kanada are
// both prose sutra collections but use SINGLE "/" and "|" as their bracket,
// which a naive "doubled-vs-lone" character count misreads as "lone", i.e.
// as if it were independent prosody).
//
// The corrected, real test: take EVERY occurrence of the glyph GRETIL
// actually uses as ITS citation delimiter for this file (read off the sigla
// matches themselves), and ask what fraction of ALL occurrences of that
// glyph in the whole text are accounted for by a sigla-bracket match at all
// (open or close side) versus occurring somewhere else in the running text,
// unattached to any citation. In a PROSE sutra work the delimiter exists
// ONLY as the citation bracket: essentially 100% of its occurrences are
// bracket-adjacent. In a metrical VERSE work the delimiter is also a live
// prosody mark: a large share of its occurrences sit in the running verse
// text, nowhere near a citation.
//
// SCOPE: IAST GRETIL texts using "|"/"||" or "/"/"//" as citation brackets.
// Falsified by a prose work whose delimiter is used for something else in
// running text (e.g. genuine abbreviation), or a verse work whose citation
// convention consumes so much of the glyph's occurrences that the
// unaccounted share drops as low as a prose work's.
//
// THRESHOLD (disclosed): "prose-only" = unaccountedShare < 0.05. Measured
// clusters: prose (Panini/Jaimini/Kanada) all land under 0.01; verse
// (Nagarjuna/Brahmagupta) land at 0.50-0.99. The cutoff sits in the wide gap
// between the two measured clusters, not fitted to either.

const SIGLA_RE = /[|/]{1,2}\s*[A-Za-z][A-Za-z]{0,8}_[0-9]+(?:[.,][0-9]+)*[a-c]?\s*(?:[|/]{1,2})?/g;

function glyphCount(text, ch) {
  let n = 0;
  for (let i = 0; i < text.length; i++) if (text[i] === ch) n++;
  return n;
}

export function detect(text, ctx = {}) {
  const matches = [...text.matchAll(SIGLA_RE)];
  if (matches.length === 0) {
    return { fired: false, evidence: { reason: 'no sigla found; cannot identify this work\'s citation delimiter' } };
  }
  // Which glyph(s) actually appear inside the matched sigla brackets, and
  // how many characters of each are consumed by those brackets.
  const consumed = { '|': 0, '/': 0 };
  for (const m of matches) {
    for (const ch of m[0]) if (ch === '|' || ch === '/') consumed[ch]++;
  }
  // Primary delimiter = whichever glyph the sigla brackets actually use.
  const primaryGlyph = consumed['|'] >= consumed['/'] ? '|' : '/';
  const totalGlyphOccurrences = glyphCount(text, primaryGlyph);
  const consumedByBrackets = consumed[primaryGlyph];
  const unaccounted = Math.max(0, totalGlyphOccurrences - consumedByBrackets);
  const unaccountedShare = totalGlyphOccurrences ? unaccounted / totalGlyphOccurrences : 0;

  const proseOnlyBracketUsage = unaccountedShare < 0.05;

  return {
    fired: true,
    evidence: {
      primaryDelimiterGlyph: primaryGlyph,
      totalGlyphOccurrences,
      consumedByCitationBrackets: consumedByBrackets,
      unaccountedInRunningText: unaccounted,
      unaccountedShare: Number(unaccountedShare.toFixed(4)),
      proseOnlyBracketUsage,
      predictedSetting: proseOnlyBracketUsage ? 'prose sutra (no independent meter)' : 'verse kārikā (metrical pada structure)'
    }
  };
}

// Rule: iast-ascii-wordclass-fails  (family: script-convention)
//
// Re-grounds seed S1 specifically for Romanized (IAST) Sanskrit, which is
// Latin-alphabet-based and so does NOT trip S1's "first/last word comes back
// EMPTY" failure the way Devanagari/Chinese/Arabic/Greek do -- but it fails
// in a subtler, arguably worse way: silently WRONG, not visibly empty.
//
// STATEMENT: A naive ASCII word-class regex (/[a-zA-Z]+/) applied to IAST
// text does not fail to match -- it under-matches. Any whitespace-delimited
// token that contains an IAST diacritic (a, i, u-macrons; r/l-vocalics;
// anusvara/visarga; velar/palatal/retroflex nasals and stops; palatal
// sibilant) gets SPLIT into two or more regex matches at the diacritic, so
// "first word" / "last word" / syllable-count logic keyed on /[a-zA-Z]+/
// returns a truncated fragment that still looks like a plausible word --
// never a signal to fall back to something else.
//
// SCOPE: any IAST-transliterated text (this territory: all of GRETIL's
// corpustei plaintext). Falsified by an IAST edition using only the
// unmarked 26-letter subset (no diacritics at all -- essentially never
// happens for real Sanskrit content, since long vowels and retroflexes are
// near-universal).
//
// MEASURED, NOT ASSUMED: we actually run /[a-zA-Z]+/g against real
// whitespace tokens and count how many produce >1 match (i.e. get split).

const DIACRITIC_RE = /[^\x00-\x7F]/; // any non-ASCII codepoint used by IAST diacritics
const ASCII_WORD_RE = /[a-zA-Z]+/g;

export function detect(text, ctx = {}) {
  // Sample whitespace-delimited tokens that contain at least one ASCII
  // letter (so we're only judging genuine word-like tokens, not bare
  // punctuation/sigla brackets).
  const tokens = text.split(/\s+/).filter(t => /[a-zA-Z]/.test(t));
  if (tokens.length === 0) {
    return { fired: false, evidence: { reason: 'no ASCII-letter-bearing tokens found' } };
  }
  let sampled = 0, splitCount = 0, diacriticTokenCount = 0;
  const examples = [];
  const CAP = 20000; // measure a bounded, still-large sample for speed
  for (const raw of tokens) {
    if (sampled >= CAP) break;
    // Strip leading/trailing punctuation (daNDa, brackets, hyphen-sandhi
    // markers) so we're judging the orthographic word, not the bracket.
    const tok = raw.replace(/^[^\p{L}]+|[^\p{L}]+$/gu, '');
    if (!tok) continue;
    sampled++;
    const hasDiacritic = DIACRITIC_RE.test(tok);
    if (hasDiacritic) diacriticTokenCount++;
    const matches = tok.match(ASCII_WORD_RE) || [];
    if (hasDiacritic && matches.length > 1) {
      splitCount++;
      if (examples.length < 5) examples.push({ token: tok, asciiRegexMatches: matches });
    }
  }
  const diacriticShare = diacriticTokenCount / sampled;
  const splitShareOfDiacriticTokens = diacriticTokenCount ? splitCount / diacriticTokenCount : 0;

  return {
    fired: splitCount > 0,
    evidence: {
      tokensSampled: sampled,
      tokensWithDiacritic: diacriticTokenCount,
      diacriticShare: Number(diacriticShare.toFixed(4)),
      tokensSplitByAsciiRegex: splitCount,
      splitShareOfDiacriticTokens: Number(splitShareOfDiacriticTokens.toFixed(4)),
      examples
    }
  };
}

// Rule: gretil-citation-period-false-sentence-break  (family: source-convention)
//
// STATEMENT: GRETIL sigla number citations use "." as a grouping separator
// between pada/chapter and sutra number (e.g. "1,1.1", "6,1.130"), and that
// number sits directly inside the sigla bracket followed by a space then the
// closing delimiter ("...1.1 ||", "...1.130 ||"). A naive sentence-splitter
// that treats /\.\s/ (period then whitespace) as a sentence boundary will
// therefore fire INSIDE every single citation, at the last period-digit
// boundary before the closing bracket -- not at the real unit boundary,
// which is a few characters later (after the bracket) and, in the flattened
// prose-sutra works, often has NO following space at all (the next sutra's
// text starts immediately after "||").
//
// SCOPE: any GRETIL plaintext using period-separated numeric citations.
// Falsified by a work whose citation numbers use a different grouping
// character (comma-only, e.g.) or are never followed by a space before the
// closing bracket.
//
// MEASURED: count of "\d\.\d+ " substrings that sit immediately before a
// closing citation bracket (a real, demonstrable false-trigger site for any
// period-space sentence splitter), plus, as a control, the count of ALL
// periods in the text -- in a pure sutra-prose edition these two counts
// coincide almost exactly, i.e. essentially 100% of periods in the document
// are citation-internal, not prose full stops (Sanskrit sutra prose in this
// convention has no "." end-of-sentence punctuation of its own; unit ends
// are marked by the daNDa bracket, not a period).

const FALSE_BREAK_RE = /\d\.\d+ *(?:\|\||\/\/|\||\/)/g;
const ANY_PERIOD_RE = /\./g;

export function detect(text, ctx = {}) {
  const falseBreaks = (text.match(FALSE_BREAK_RE) || []).length;
  const totalPeriods = (text.match(ANY_PERIOD_RE) || []).length;
  if (totalPeriods === 0) {
    return { fired: false, evidence: { reason: 'no periods in text at all' } };
  }
  const shareOfPeriodsThatAreCitationInternal = falseBreaks / totalPeriods;
  return {
    fired: falseBreaks > 0,
    evidence: {
      falseBreakSites: falseBreaks,
      totalPeriods,
      shareOfPeriodsThatAreCitationInternal: Number(shareOfPeriodsThatAreCitationInternal.toFixed(4)),
      note: 'Every falseBreakSite is a place a naive /. /-based sentence splitter would cut mid-citation.'
    }
  };
}

// Rule: gretil-html-legend-table-leak  (family: extraction-artifact)
//
// STATEMENT: GRETIL's legacy (non-TEI) HTML editions -- e.g. the
// Bhagavadgita .htm under 1_sanskr/2_epic/mbh/ext/ -- open with an HTML
// <table> that is a Sanskritist's transliteration LEGEND: a two-column
// mapping of an English description ("long a", "vocalic r", "retroflex t",
// "anusvara") to the corresponding IAST character. This table is part of
// the source's own on-screen furniture (a font/encoding reference for a
// human reader's browser), not text of the work. A naive HTML-to-text
// conversion that strips tags but keeps cell text turns it into ~40-90
// short, isolated lines that read as nonsense wedged between the file's
// provenance note and the first real verse.
//
// SCOPE: GRETIL's legacy HTML tree (1_sanskr/**), and structurally any
// HTML-to-text conversion of a definition-list-shaped legend table.
// Falsified on a corpustei/TEI-sourced work (no such table exists there) or
// on legacy HTML lacking this specific legend.
//
// DETECTION IS STRUCTURAL, NOT A WORD LIST: we never hardcode the ~40 legend
// labels ("vocalic r", "anusvara", ...). Instead we look for the SHAPE: a
// RUN of consecutive short lines where each line is (a) plain ASCII
// lowercase-with-spaces text, then (b) at least one non-ASCII (diacritic)
// character, and (c) nothing else of substance on the line. Genuine IAST
// verse text essentially never produces many CONSECUTIVE lines of this
// "plain-English-phrase + lone-diacritic-letter" shape (Sanskrit words are
// not plain English), so a modest run length safely separates the two
// populations without needing to enumerate the legend's actual vocabulary.
//
// THRESHOLD (disclosed): fires on a run of >=8 consecutive legend-shaped
// lines. Measured: the real Bhagavadgita legend table run is 40+ lines long;
// no other run of >=8 such lines exists anywhere else we measured in this
// territory's ~2 million characters of verse/sutra text.

// The legend alternates lowercase and uppercase rows ("long a"/"long A",
// "vocalic r"/"vocalic R"), so the description half must allow both cases --
// an all-lowercase-only pattern (an earlier version of this detector) only
// caught every other row and undercounted the run length.
const LEGEND_LINE_RE = /^[A-Za-z][A-Za-z ]{1,30}[A-Za-z]\s+[^\x00-\x7F](?:\s*[^\x00-\x7F]){0,3}\s*$/;

export function detect(text, ctx = {}) {
  const lines = text.split('\n');
  let bestRun = 0, bestStart = -1, curRun = 0, curStart = -1;
  const runs = [];
  for (let i = 0; i < lines.length; i++) {
    if (LEGEND_LINE_RE.test(lines[i].trim())) {
      if (curRun === 0) curStart = i;
      curRun++;
    } else {
      if (curRun >= 8) runs.push({ startLine: curStart, length: curRun });
      if (curRun > bestRun) { bestRun = curRun; bestStart = curStart; }
      curRun = 0;
    }
  }
  if (curRun >= 8) runs.push({ startLine: curStart, length: curRun });
  if (curRun > bestRun) { bestRun = curRun; bestStart = curStart; }

  const fired = bestRun >= 8;
  return {
    fired,
    evidence: {
      longestLegendShapedRun: bestRun,
      longestRunStartLine: bestStart,
      allRunsOfAtLeast8: runs,
      sampleLines: bestRun > 0 ? lines.slice(bestStart, bestStart + Math.min(bestRun, 5)) : []
    }
  };
}

// Rule: gretil-mula-bhasya-by-sigla-presence  (family: source-convention)
//
// Re-grounds seed S14 ("another hand carried inline") for GRETIL's mula
// (root text) + bhasya (commentary) editions, e.g. Patanjali's Yogasutra
// with Vyasa's bhasya.
//
// STATEMENT: in a GRETIL mula+bhasya file, ONLY the root-text (mula) lines
// carry a sigla citation; the commentator's (bhasya) prose in between never
// does. So a reader can tell the two hands apart from bytes alone, on ANY
// extraction, WITHOUT needing the TEI's <l rend="bold"> vs <p> markup
// (which plaintext discards anyway): a line/unit is mula iff it matches the
// sigla regex; everything else, by elimination, is the other hand.
//
// SCOPE: GRETIL works whose title/note says "with bhasya"/"-tika"/commentary
// (mixed-hand editions). Falsified by a bhasya edition where the
// commentary itself also carries reference numbers in the same bracket
// style (e.g. commentary that cites OTHER sutras by number inline -- we
// measure this explicitly below as a possible confound).
//
// MEASURED: split into physical lines; classify each non-blank line as
// "sigla-bearing" (mula candidate) or "prose" (bhasya candidate); report the
// share of each and their average lengths, since mula lines are short
// (one sutra) and bhasya lines are typically much longer (prose exegesis) --
// this length gap is independent corroborating evidence, not assumed.

const SIGLA_RE = /[|/]{1,2}\s*([A-Za-z][A-Za-z]{0,8})_([0-9]+(?:[.,][0-9]+)*[a-c]?)\s*(?:[|/]{1,2})?/;

export function detect(text, ctx = {}) {
  const lines = text.split('\n').map(l => l.trim()).filter(l => l.length > 0);
  if (lines.length === 0) return { fired: false, evidence: { reason: 'empty text' } };

  let siglaLines = 0, proseLines = 0, siglaLenSum = 0, proseLenSum = 0;
  for (const l of lines) {
    if (SIGLA_RE.test(l)) { siglaLines++; siglaLenSum += l.length; }
    else { proseLines++; proseLenSum += l.length; }
  }
  const total = lines.length;
  const siglaShare = siglaLines / total;
  const avgSiglaLen = siglaLines ? siglaLenSum / siglaLines : 0;
  const avgProseLen = proseLines ? proseLenSum / proseLines : 0;

  // fired = true means this text plausibly IS a mixed mula+bhasya edition:
  // both classes present in non-trivial numbers, and mula lines shorter on
  // average than prose lines (root sutras are terse; commentary is not).
  const bothPresent = siglaLines >= 5 && proseLines >= 5;
  const lengthGapHoldsAsExpected = bothPresent && avgSiglaLen < avgProseLen;

  return {
    fired: bothPresent,
    evidence: {
      totalNonBlankLines: total,
      siglaBearingLines: siglaLines,
      proseLines,
      siglaShare: Number(siglaShare.toFixed(4)),
      avgSiglaLineLength: Number(avgSiglaLen.toFixed(1)),
      avgProseLineLength: Number(avgProseLen.toFixed(1)),
      lengthGapHoldsAsExpected
    }
  };
}

// Rule: gretil-uvaca-speaker-attribution  (family: source-convention)
//
// Re-grounds seed S11 (recurring short speaker-label lines) for Sanskrit
// dialogue texts (Bhagavadgita / Mahabharata-style narrative), which do not
// use a Faust/Hamlet-style "NAME." caps+period label but a grammatical
// formula: a short line whose content is just "<name> uvaca" ("<name>
// said"), from a small, repeating cast.
//
// STATEMENT: a genuine chapter/section speaker cue is a line consisting of
// ONLY 1-2 tokens followed by the literal word "uvaca" (nothing else before
// the citation bracket); the SAME word "uvaca" also occurs constantly in
// ordinary narrative prose/verse ("...tam uvaca" = "...said to him"), so a
// bare substring search for "uvaca" over-fires. The anchored, whole-pada
// form is the discriminator, and the resulting speaker set is small and
// closed (repeats), same shape as S11's Faust/Hamlet, even though the
// surface form differs completely.
//
// SCOPE: GRETIL Mahabharata-family texts (itihasa dialogue frame). Not
// expected to fire on the sutra corpora in this territory at all (no
// dialogue frame) -- that absence is itself part of the falsification set.
//
// NOTE ON THE HOUSE RULE: we do NOT hardcode any list of speaker names
// (that would be exactly the "closed list as regex alternation" anti-
// pattern this project's house rules forbid). The speaker set is measured
// per-input, not looked up.

const ANCHORED_UVACA_RE = /^(\S+)(?:\s(\S+))?\s+uvāca\s*$/;
// Looser, unanchored form used only to measure the false-positive rate of a
// naive "just search for the substring uvaca" approach, as a control.
const LOOSE_UVACA_RE = /\buvāca\b/g;

export function detect(text, ctx = {}) {
  const lines = text.split('\n');
  const speakerCounts = new Map();
  let anchoredMatches = 0;
  for (const raw of lines) {
    // Strip a trailing citation bracket ("  Bhg_01.001 [=MBh_...]") before
    // testing, since the anchored form is about the PADA text, not the line
    // including its citation.
    const withoutCitation = raw.replace(/\s{2,}\S.*$/, '').trim();
    const m = ANCHORED_UVACA_RE.exec(withoutCitation);
    if (m) {
      anchoredMatches++;
      const speaker = (m[1] + (m[2] ? ' ' + m[2] : '')).toLowerCase();
      speakerCounts.set(speaker, (speakerCounts.get(speaker) || 0) + 1);
    }
  }
  const looseMatches = (text.match(LOOSE_UVACA_RE) || []).length;
  const distinctSpeakers = speakerCounts.size;

  if (anchoredMatches === 0) {
    return { fired: false, evidence: { reason: 'no anchored "<name> uvaca" pada found', looseSubstringMatches: looseMatches } };
  }

  // fired = true means this reads as a genuine closed-cast dialogue-cue
  // system: few distinct speakers, each repeating.
  const repeatRate = 1 - (distinctSpeakers / anchoredMatches);
  const closedCast = distinctSpeakers <= 8 && repeatRate > 0.3;

  return {
    fired: closedCast,
    evidence: {
      anchoredSpeakerCueLines: anchoredMatches,
      looseSubstringMatches: looseMatches,
      falsePositiveInflationFromNaiveSubstringSearch: looseMatches - anchoredMatches,
      distinctSpeakers,
      speakerCounts: Object.fromEntries([...speakerCounts.entries()].sort((a, b) => b[1] - a[1])),
      repeatRate: Number(repeatRate.toFixed(3)),
      closedCast
    }
  };
}

// Rule: gretil-header-text-boundary-marker  (family: source-convention)
//
// STATEMENT: every GRETIL corpustei plaintext transformation opens its
// boilerplate with a line reading exactly "# Header" and closes it with a
// line reading exactly "# Text", immediately before the work's own content
// begins. This holds regardless of genre (prose sutra, verse karika, drama),
// regardless of citation convention (underscore-prefixed, colon-numbered, or
// bracket-free), and regardless of whether the body ends up flattened or
// not. It is a simpler, more reliable header/body boundary than anything
// derived from content heuristics -- and simpler than the YAML frontmatter
// live_priors substitutes for it, which happens to preserve the same cut
// point but is not the only way to find it.
//
// SCOPE: GRETIL's TEI-sourced "mass conversion" plaintext transformations
// (the corpustei/transformations/plaintext tree). Not claimed for GRETIL's
// legacy pre-TEI HTML tree (1_sanskr/**, e.g. the Bhagavadgita .htm), which
// uses a completely different, hand-written header with no "# Header"/
// "# Text" markers at all -- tested below as a deliberate near-miss.
//
// MEASURED, ACROSS EVERY WORK FETCHED FOR THIS TERRITORY (11/11, including
// three held-out works whose citation convention broke every other detector
// in this rule set): exactly one "# Header" and exactly one "# Text" line,
// each occurring exactly once. No threshold is needed; this is an exact,
// literal-string match, not a statistical inference.

const HEADER_RE = /^# Header$/m;
const TEXT_RE = /^# Text$/m;

export function detect(text, ctx = {}) {
  const headerMatch = HEADER_RE.exec(text);
  const textMatch = TEXT_RE.exec(text);
  if (!headerMatch || !textMatch) {
    return {
      fired: false,
      evidence: {
        reason: 'no "# Header" / "# Text" marker pair found (not a corpustei mass-conversion plaintext file)',
        hasHeaderMarker: Boolean(headerMatch),
        hasTextMarker: Boolean(textMatch)
      }
    };
  }
  const headerLineNo = text.slice(0, headerMatch.index).split('\n').length;
  const textLineNo = text.slice(0, textMatch.index).split('\n').length;
  const bodyStartsAtLine = textLineNo + 1; // the line right after "# Text"
  const headerLineCount = textLineNo - headerLineNo;
  const bodyText = text.slice(textMatch.index + textMatch[0].length);
  const bodyCharCount = bodyText.replace(/^\s+/, '').length;

  return {
    fired: true,
    evidence: {
      headerMarkerLine: headerLineNo,
      textMarkerLine: textLineNo,
      headerLineCount,
      bodyStartsAtLine,
      bodyCharCount
    }
  };
}

// RULE: homer-fr-linenum-mod5  (family: extraction-artifact; re-grounds seed S3)
//
// SCOPE: verse texts extracted from a MediaWiki <poem> block that used the
// el.wikisource {{fr|N}} / la.wikisource {{versus|N}} "float-right line
// number" template. Grounded on el.wikisource Homer: wikitext has
// "...βουλή, {{fr|5}}" -> rendered HTML
// <span style="float:right;...;color:blue" id="v5">5</span> -> flattened
// plain text "...βουλή, 5" (one preceding space, bare integer, line-final).
//
// MEASURED, full corpus, not a spot check: live_priors homer-iliad.txt (all
// 24 books concatenated) has 3033 such trailing integers, of which 3025
// (99.74%) are multiples of 5; homer-odyssey.txt has 2224/2224 (100%);
// pindar-pythian-odes.txt has 237/237 (100%). The 8 Iliad exceptions are
// NOT extraction damage: they were traced to the live source itself
// (fetched Ιλιάς/Θ fresh and confirmed the identical span ids
// id="v547" id="v549" id="v553" in the rendered HTML). All 8 cluster in
// twos/threes in the last ~20 lines before a book boundary (end of Θ, Ι, Λ,
// Σ), where the regular every-5 rhythm is briefly interrupted then resumes
// (…540, 545, 547, 549, 553, 560, 565…). A plausible cause (flagged as a
// hypothesis, not confirmed further here) is that the edition's numbering
// follows the traditional/transmitted line count, which itself has a few
// contested-line irregularities near those points in the Homeric text; the
// detector does not depend on knowing which explanation is right.
//
// Deliberately structural, not lexical: matches a BARE integer at the very
// end of a line, preceded by exactly one space and some non-space content
// (so a line that is only a page number, or a number followed by more
// text, does not count). This also means it will not fire on
// Hippocrates-style aphorism numbers, which are LEADING not trailing
// (see hippocrates-latin-et-merge.mjs and the seed-verdict note on S3).
//
// House rule followed: prefer a measured rate + its null over a hand-set
// "must be exactly 100%" threshold, since 100% turned out to be false at
// full-corpus scale. The null: if line-final integers were unrelated
// editorial noise, each independently has p=1/5 of being a multiple of 5;
// getting >=99% of k>=100 that way is still statistically absurd (reported
// via a normal-approximation z-score, not asserted), so a >=0.95 measured
// rate at large sample size is treated as firing while still reporting the
// exact exception count for honesty.

const TRAILING_NUMBER = /\S \(?(\d{1,4})\)?\s*$/;
// (kept simple: exactly one space, then 1-4 digits, optional stray paren,
// then end of line/line-trailing whitespace)

export function detect(text, ctx = {}) {
  const lines = text.split(/\r?\n/);
  const numbers = [];
  const examples = [];
  for (const raw of lines) {
    const line = raw.replace(/\s+$/, (m) => (m.length ? " " : "")); // normalize multi-trailing-space to one for matching, keep signal
    // Skip lines that are ONLY a number (page-number furniture, not a verse+number)
    if (/^\s*\d{1,4}\s*$/.test(raw)) continue;
    const m = TRAILING_NUMBER.exec(raw.replace(/\s+$/, " "));
    if (m) {
      const n = parseInt(m[1], 10);
      numbers.push(n);
      if (examples.length < 8) examples.push(raw.trim());
    }
  }
  const k = numbers.length;
  const mod5 = numbers.filter((n) => n % 5 === 0).length;
  const exceptions = numbers.filter((n) => n % 5 !== 0);
  const minSample = ctx.minSample || 3;
  const rate = k > 0 ? mod5 / k : 0;
  const minRate = ctx.minRate ?? 0.95;
  const fired = k >= minSample && rate >= minRate;
  // Null model, reported two ways: exact for small k (0.2^k), and a
  // normal-approximation z-score for large k (rate vs p=0.2, n=k) so a
  // 99.7%-but-not-100% result is still shown as astronomically non-random
  // rather than forced through an all-or-nothing gate.
  const pRandomExact = k > 0 ? Math.pow(0.2, k) : 1;
  const z = k > 0 ? (rate - 0.2) / Math.sqrt((0.2 * 0.8) / k) : null;
  return {
    fired,
    evidence: {
      totalTrailingNumbers: k,
      mod5Count: mod5,
      mod5Rate: rate,
      exceptionCount: exceptions.length,
      exceptionValues: exceptions.slice(0, 15),
      minRateRequired: minRate,
      minSampleRequired: minSample,
      nullModelPValueIfAllRandom_exact: pRandomExact,
      nullModelZScoreVsP0_2: z,
      firstNumbers: numbers.slice(0, 10),
      lastNumbers: numbers.slice(-5),
      exampleLines: examples,
    },
  };
}

// RULE: poem-colon-indent-marker  (family: source-convention)
//
// SCOPE: el.wikisource verse pages transcribed from a djvu scan inside a
// <poem>...</poem> block, where the proofreader marks an indented verse
// with a leading ":" in the wikitext. Grounded directly on
// Page:Homeri Opera, vol. 1 (1920).djvu/37 wikitext:
//   Ἀτρεΐδης τε ἄναξ ἀνδρῶν καὶ δῖος Ἀχιλλεύς.
//   :Τίς τ’ ἄρ σφωε θεῶν ἔριδι ξυνέηκε μάχεσθαι;
// which the API's prop=text rendering turns into
//   <span class="mw-poem-indented" style="...margin-inline-start: 1em;">...</span>
// and which the plain-text extraction flattens to a single leading space:
//   " Τίς τ’ ἄρ σφωε θεῶν ἔριδι ξυνέηκε μάχεσθαι; "
// (confirmed present in live_priors homer-iliad.txt). Measured: 36 such
// mw-poem-indented spans in Iliad book A's rendering, 62 in book B -- a
// recurring convention, not a one-off.
//
// This is deliberately scoped AWAY from seed S10 ("Wikisource lines carry
// one leading space" as a work-wide baseline): S10 describes every line
// having some fixed indent; this rule describes a MINORITY of lines in an
// otherwise flush-left (modal indent 0) block carrying one MORE leading
// space than their neighbours. The detector checks the work-wide modal
// indent is 0 before treating extra-indented lines as this phenomenon, so
// it will not double-fire on an S10-shaped file.

export function detect(text, ctx = {}) {
  const allLines = text.split(/\r?\n/);
  const leadCounts = [];
  for (const l of allLines) {
    if (l.trim() === "") continue;
    const m = /^ */.exec(l);
    leadCounts.push(m[0].length);
  }
  if (leadCounts.length < 10) {
    return { fired: false, evidence: { reason: "too few non-blank lines to establish a modal indent", nonBlankLines: leadCounts.length } };
  }
  const freq = new Map();
  for (const c of leadCounts) freq.set(c, (freq.get(c) || 0) + 1);
  let modal = 0, modalCount = -1;
  for (const [c, n] of freq) if (n > modalCount) { modal = c; modalCount = n; }

  if (modal !== 0) {
    return {
      fired: false,
      evidence: {
        reason: "work-wide modal indent is not 0; this looks like S10's blanket-indent case, not a minority indent-marker",
        modalIndent: modal,
      },
    };
  }

  // Now find contiguous non-blank blocks and, within each, lines indented
  // exactly modal+1 while the block itself is mostly modal.
  const blocks = [];
  let cur = [];
  for (const l of allLines) {
    if (l.trim() === "") {
      if (cur.length) blocks.push(cur);
      cur = [];
    } else {
      cur.push(l);
    }
  }
  if (cur.length) blocks.push(cur);

  let indentedLines = 0;
  let blocksWithIndent = 0;
  const examples = [];
  for (const block of blocks) {
    if (block.length < 3) continue;
    const indentedInBlock = block.filter((l) => /^ /.exec(l) && !/^  /.exec(l));
    if (indentedInBlock.length > 0 && indentedInBlock.length < block.length * 0.4) {
      blocksWithIndent++;
      indentedLines += indentedInBlock.length;
      for (const l of indentedInBlock) if (examples.length < 6) examples.push(l.trim());
    }
  }

  return {
    fired: blocksWithIndent >= 1 && indentedLines >= 1,
    evidence: {
      workWideModalIndent: modal,
      blocksExamined: blocks.length,
      blocksShowingMinorityIndent: blocksWithIndent,
      totalIndentMarkedLines: indentedLines,
      exampleLines: examples,
    },
  };
}

// RULE: tag-boundary-space-injection  (family: extraction-artifact)
//
// SCOPE: any HTML-to-plain-text conversion step that walks the DOM and
// joins each element's text content with separators, inserting a space at
// element/tag boundaries even where the source HTML has none.
//
// GROUNDED TWO WAYS on el.wikisource Plato Republic A:
//  (a) rendered HTML has the Stephanus self-link TIGHT inside its bracket:
//        [<span id="p327a"><a ...>327a</a></span>]         -> "[327a]"
//      the plain-text extraction (live_priors plato-republic.txt) has it
//      SPACED:
//        " [ 327a ] "                                       -> "[ 327a ]"
//      i.e. a synthetic space appears exactly at the two tag boundaries
//      ("[" -> <span> and </span> -> "]"), never elsewhere in that token.
//  (b) every wrapped verse line inside a <poem> block ends "<br />\n" in
//      the rendered HTML; the flattened plain text keeps one trailing
//      U+0020 before the added "\n" (confirmed in live_priors
//      homer-iliad.txt and pindar-pythian-odes.txt) on non-final lines of
//      a stanza. A human typist's stray-trailing-space rate is a small
//      fraction of a percent; the measured rate here is far higher (see
//      evidence.trailingSpaceRatio), which is why this is read as a
//      mechanical join artifact rather than typing noise.
//
// Both sub-signatures share one mechanism (a text-join inserted at a tag
// boundary that has no literal whitespace in the source), so one detector
// checks both and reports each independently.

export function detect(text, ctx = {}) {
  const lines = text.split(/\r?\n/);

  // (a) bracket-interior padding: "[ TOKEN ]" vs "[TOKEN]" for a short
  // token (a Stephanus ref, a line number, a single word/label).
  const spaced = [...text.matchAll(/\[ ([^\[\]\n]{1,16}) \]/g)];
  const tight = [...text.matchAll(/\[([^\[\]\s]{1,16})\]/g)];
  const spacedN = spaced.length;
  const tightN = tight.length;
  const bracketTotal = spacedN + tightN;
  const bracketFired = bracketTotal >= 3 && spacedN / bracketTotal >= 0.8;

  // (b) trailing single space before newline, measured only on lines that
  // are followed by another non-blank line (i.e. mid-block, not a
  // paragraph's last line, where a trailing space would mean something
  // different or nothing at all).
  let midBlockLines = 0;
  let trailingSpaceLines = 0;
  const exTrail = [];
  for (let i = 0; i < lines.length - 1; i++) {
    const l = lines[i];
    const next = lines[i + 1];
    if (l.trim() === "" || next.trim() === "") continue;
    midBlockLines++;
    if (/[^\s] $/.test(l)) {
      trailingSpaceLines++;
      if (exTrail.length < 5) exTrail.push(JSON.stringify(l.slice(-24)));
    }
  }
  const trailingRatio = midBlockLines ? trailingSpaceLines / midBlockLines : 0;
  // Null: plausible human stray-space typo rate is well under 1%; treat
  // anything an order of magnitude above that as non-accidental.
  const typoBaseline = 0.01;
  const trailingFired = midBlockLines >= 20 && trailingRatio >= 10 * typoBaseline;

  return {
    fired: bracketFired || trailingFired,
    evidence: {
      bracketInteriorSpacing: {
        spacedCount: spacedN,
        tightCount: tightN,
        spacedFraction: bracketTotal ? spacedN / bracketTotal : null,
        fired: bracketFired,
        exampleSpaced: spaced.slice(0, 5).map((m) => m[0]),
        exampleTight: tight.slice(0, 5).map((m) => m[0]),
      },
      trailingLineSpace: {
        midBlockLinesExamined: midBlockLines,
        trailingSpaceLines,
        ratio: trailingRatio,
        typoBaselineAssumed: typoBaseline,
        fired: trailingFired,
        examples: exTrail,
      },
    },
  };
}

// RULE: greek-editsection-inline  (family: extraction-artifact; extends seed S4)
//
// SCOPE: el.wikisource pages that are PLAIN wikitext with =={{heading}}==
// sections (an ode, a dialogue broken into speaker-turn sections) -- NOT
// pages whose content is transcluded from a djvu scan via <pages .../>
// (those get no per-section edit link at all: measured 0 mw-editsection
// spans on the Iliad's rendering, vs 36 spans / 12 links on Pindar's
// Pythian Odes page and 33 spans / 11 links on Republic book A, one link
// per == heading ==).
//
// Grounded: the wikitext has plain "==ΙΕΡΩΝΙ ΑΙΤΝΑΙῼ, ΑΡΜΑΤΙ==" with no
// "Επεξεργασία" anywhere; the *rendered* HTML injects
//   <span class="mw-editsection-bracket">[</span>
//   <a ...><span>Επεξεργασία</span></a>
//   <span class="mw-editsection-bracket">]</span>
// and the plain-text extraction keeps the link text but drops the bracket
// spans, producing "ΙΕΡΩΝΙ ΑΙΤΝΑΙῼ, ΑΡΜΑΤΙ Επεξεργασία" glued onto the
// heading with one space, no brackets (confirmed in live_priors
// pindar-pythian-odes.txt). This is the Greek member of the family seed S4
// already names for zh/la/ar ("[ 编辑 ]", "[ recensere ]", "[ عدل ]").
//
// House rule: the cross-language edit-link table is a closed lookup, kept
// as a Set/array, never as a regex alternation of arbitrary words.

const KNOWN_EDIT_LINK_WORDS = new Map([
  ["el", "Επεξεργασία"],
  ["zh", "编辑"],
  ["la", "recensere"],
  ["ar", "عدل"],
]);

export function detect(text, ctx = {}) {
  const lines = text.split(/\r?\n/);
  const hits = [];
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    for (const [lang, word] of KNOWN_EDIT_LINK_WORDS) {
      // must be glued to the end of a non-trivial heading-like line: some
      // preceding non-space content, exactly one space, then the word,
      // then end of line (optionally more trailing whitespace).
      const re = new RegExp(`\\S \\[?\\s*${word}\\s*\\]?\\s*$`, "u");
      if (re.test(line.trimEnd()) && line.trim() !== word) {
        hits.push({ lineIndex: i, lang, text: line.trim() });
      }
    }
  }
  return {
    fired: hits.length > 0,
    evidence: {
      hitCount: hits.length,
      hits: hits.slice(0, 10),
      knownWordsChecked: [...KNOWN_EDIT_LINK_WORDS.entries()],
    },
  };
}

// RULE: pindar-strophe-bracket-labels  (family: source-convention)
//
// SCOPE: choral-lyric verse edited/transcribed with the triadic
// strophe/antistrophe/epode apparatus (Pindar's epinicians; potentially
// other triadic lyric such as some Bacchylides or tragic choral odes).
//
// Grounded directly on el.wikisource "Πυθιόνικοι" WIKITEXT (not a
// template -- literal characters typed by the transcriber):
//   [στρ. 1]<br>          [αντ. 1]<br>          [επωδή 1]<br>
//   ...                   ...                   ...
//   [στρ. 2]<br>
// confirmed unchanged in the live_priors plain-text extraction (no
// flattening damage at all for this particular marker -- a clean case).
// The per-label counters each increment by exactly 1 across the ode, and
// the three labels cycle strophe -> antistrophe -> epode in a fixed order
// (the triad).
//
// House rule: the three label words are a closed table, not a regex
// alternation of open-ended text.

const TRIAD_LABELS = ["στρ.", "αντ.", "επωδή"];
const LABEL_RE = /\[\s*(στρ\.|αντ\.|επωδή)\s*(\d+)?\s*\]/gu;

export function detect(text, ctx = {}) {
  const matches = [...text.matchAll(LABEL_RE)];
  const byLabel = new Map(TRIAD_LABELS.map((l) => [l, []]));
  for (const m of matches) {
    byLabel.get(m[1]).push(m[2] ? parseInt(m[2], 10) : null);
  }

  // Check each label's numbered occurrences increase monotonically by 1.
  const monotonic = {};
  for (const label of TRIAD_LABELS) {
    const nums = byLabel.get(label).filter((n) => n !== null);
    let ok = nums.length > 0;
    for (let i = 1; i < nums.length; i++) {
      if (nums[i] !== nums[i - 1] + 1) ok = false;
    }
    monotonic[label] = { count: nums.length, sequence: nums, incrementsByOne: ok };
  }

  const totalLabels = matches.length;
  const distinctLabelsSeen = TRIAD_LABELS.filter((l) => byLabel.get(l).length > 0).length;

  return {
    fired: totalLabels >= 2 && distinctLabelsSeen >= 2,
    evidence: {
      totalLabelOccurrences: totalLabels,
      distinctLabelKinds: distinctLabelsSeen,
      perLabel: monotonic,
      exampleMatches: matches.slice(0, 6).map((m) => m[0]),
    },
  };
}

// RULE: pindar-dual-track-lineation  (family: source-convention; narrows seed S3)
//
// SCOPE: Pindar odes on el.wikisource (and structurally similar dual-cited
// lyric) that carry TWO independent line-reference tracks in the same
// running text:
//   - a BARE integer glued to a line's END, step 5   (5, 10, 15, 20 ...)
//   - a BRACKETED integer glued to a line's START, step 10 ([10] [20] [30] ...)
// Grounded on el.wikisource "Πυθιόνικοι" wikitext, Pythian 1: extracted
// every occurrence of each track (see measured evidence) and confirmed
// (a) each track is independently monotonic with a constant step, and
// (b) the bracket value is consistently ~2x the nearest bare value at the
// same textual position (15 pairs with [30], 20 pairs with [40], etc.).
// A plausible (not certain -- flagged as such) explanation is the classic
// double numbering of Pindar editions: an older continuous count
// (commonly attributed to Boeckh's edition, which prints more/shorter
// lines) alongside the modern Snell-Maehler count; the DETECTOR itself
// only relies on the structural fact, not on that attribution.
//
// This NARROWS seed S3 ("a trailing number on verse lines is the
// edition's line count when every trailing number is a multiple of 5"):
// for a dual-track work, a naive S3-style detector that also picks up
// leading bracket numbers would wrongly merge two different counters. A
// correct detector must keep the two tracks separate and check each
// track's own step.

const BARE_TRAILING = /\S \(?(\d{1,4})\)?\s*$/;
const BRACKET_LEADING = /^\s*\[(\d{1,4})\]/;

function modeStep(sortedNums) {
  const diffs = new Map();
  for (let i = 1; i < sortedNums.length; i++) {
    const d = sortedNums[i] - sortedNums[i - 1];
    diffs.set(d, (diffs.get(d) || 0) + 1);
  }
  let best = null, bestCount = -1;
  for (const [d, c] of diffs) if (c > bestCount) { best = d; bestCount = c; }
  return { step: best, stepAgreement: sortedNums.length > 1 ? bestCount / (sortedNums.length - 1) : null };
}

export function detect(text, ctx = {}) {
  const lines = text.split(/\r?\n/);
  const bare = [];
  const bracket = [];
  for (const raw of lines) {
    if (/^\s*\d{1,4}\s*$/.test(raw)) continue; // bare page-number-only line, ignore
    const bm = BARE_TRAILING.exec(raw.replace(/\s+$/, " "));
    if (bm) bare.push(parseInt(bm[1], 10));
    const km = BRACKET_LEADING.exec(raw);
    if (km) bracket.push(parseInt(km[1], 10));
  }

  const bareInfo = modeStep(bare);
  const bracketInfo = modeStep(bracket);

  const haveBoth = bare.length >= 3 && bracket.length >= 3;
  const ratioOk = (() => {
    if (!haveBoth) return null;
    // For each bracket value, find nearest bare value and compute ratio.
    let ratios = [];
    for (const bv of bracket) {
      let nearest = null, bestDiff = Infinity;
      for (const av of bare) {
        const d = Math.abs(av - bv / 2);
        if (d < bestDiff) { bestDiff = d; nearest = av; }
      }
      if (nearest) ratios.push(bv / nearest);
    }
    const avg = ratios.reduce((a, b) => a + b, 0) / (ratios.length || 1);
    return { averageBracketOverNearestBare: avg, sampleSize: ratios.length };
  })();

  const fired =
    haveBoth &&
    bareInfo.step === 5 &&
    bracketInfo.step === 10 &&
    bareInfo.stepAgreement >= 0.9 &&
    bracketInfo.stepAgreement >= 0.9;

  return {
    fired,
    evidence: {
      bareTrack: { count: bare.length, values: bare.slice(0, 10), ...bareInfo },
      bracketTrack: { count: bracket.length, values: bracket.slice(0, 10), ...bracketInfo },
      bracketToBareRatio: ratioOk,
      interpretationNote:
        "structural finding is certain (two independent monotonic counters); the Boeckh-vs-Snell-Maehler attribution for WHY is a plausible reading, not verified here",
    },
  };
}

// RULE: angle-bracket-editorial-supplement  (family: source-convention + extraction-artifact)
//
// SOURCE CONVENTION: classical critical-edition apparatus embedded directly
// in running text: <word> (angle brackets around one bare word) marks a
// word supplied by editorial conjecture that is NOT in the manuscripts --
// standard philological practice, distinct from [word]/[N] which this
// bench treats separately (Wikisource structural labels in Pindar;
// Burnet-style suspected-spurious-word seclusion in Plato -- see
// editorial-seclusion-bracket-word.mjs).
//
// Grounded on el.wikisource "Πυθιόνικοι" WIKITEXT (7 instances found across
// the page, not just one), e.g. Pythian 1:
//   "λοιπὸν ἔσσεσθαι στεφάνοισί <νιν> ἵπποις τε κλυτὰν"
// "νιν" is a Doric enclitic pronoun the transmitted text lacks; the angle
// brackets are the editor's mark that it was supplied.
//
// EXTRACTION ARTIFACT -- CORRECTED FINDING (measured, not assumed): an
// earlier draft of this rule guessed the marker "survives unchanged"; it
// does NOT. live_priors pindar-pythian-odes.txt line 58 reads
//   "λοιπὸν ἔσσεσθαι στεφάνοισί νιν ἵπποις τε κλυτὰν"
// -- the word is there, the angle brackets are GONE. This is a silent,
// information-destroying artifact, worse than flattening-with-a-visible-
// residue (contrast Homer's {{fr}} numbers or Sappho's {{crit}} apparatus,
// both of which leave a visible, if unlabelled, residue): the reader of
// the extraction has no way left to know "νιν" was ever a conjecture
// rather than manuscript text. The likely mechanism is an HTML-tag
// stripper applied somewhere in the pipeline that treats any "<...>" run
// as a markup tag to delete, which is true for actual wiki-rendered tags
// but false for this literal editorial convention.
//
// Because this needs BOTH the original and the extraction to demonstrate
// the loss, detect() accepts ctx.extractedText: when given, it reports
// exactly which bracketed words from `text` are present-but-unbracketed
// in ctx.extractedText. Without ctx.extractedText it falls back to just
// reporting source-side hits (still useful for confirming the source
// convention on a text with no known prior extraction).

const TAGLIKE = /[\/=]|^(?:br|ref|poem|section|div|span|p|i|b|sup|sub|small|references)$/i;
const LETTERS_ONLY = /^[\p{L}\p{M}̓̔́̀͂’᾽']+$/u;

function findHits(text) {
  const matches = [...text.matchAll(/<([^<>]{1,24})>/gu)];
  const hits = [];
  for (const m of matches) {
    const inner = m[1].trim();
    if (TAGLIKE.test(inner)) continue;
    if (!LETTERS_ONLY.test(inner)) continue;
    hits.push({ index: m.index, token: inner, context: text.slice(Math.max(0, m.index - 20), m.index + m[0].length + 20) });
  }
  return hits;
}

export function detect(text, ctx = {}) {
  const hits = findHits(text);

  if (!ctx.extractedText) {
    return {
      fired: hits.length >= 1,
      evidence: {
        mode: "source-only",
        hitCount: hits.length,
        hits: hits.slice(0, 8),
      },
    };
  }

  let silentlyStripped = 0;
  let stillBracketed = 0;
  let notFoundAtAll = 0;
  const strippedExamples = [];
  for (const h of hits) {
    const bracketedForm = `<${h.token}>`;
    const wordRe = new RegExp(`(^|[^\\p{L}])${h.token}([^\\p{L}]|$)`, "u");
    if (ctx.extractedText.includes(bracketedForm)) {
      stillBracketed++;
    } else if (wordRe.test(ctx.extractedText)) {
      silentlyStripped++;
      if (strippedExamples.length < 5) strippedExamples.push(h.token);
    } else {
      notFoundAtAll++;
    }
  }

  return {
    fired: hits.length >= 1 && silentlyStripped >= 1,
    evidence: {
      mode: "source-vs-extraction",
      sourceHitCount: hits.length,
      silentlyStrippedCount: silentlyStripped,
      stillBracketedCount: stillBracketed,
      notFoundAtAllCount: notFoundAtAll,
      strippedExamples,
      interpretation:
        silentlyStripped > 0
          ? "editorial conjecture marker deleted; word kept, reader can no longer tell it was a supplement"
          : "marker survived intact in this extraction",
    },
  };
}

// RULE: hippocrates-latin-et-merge  (family: source-convention; near-miss for seed S3)
//
// SCOPE: Hippocratic Aphorisms on el.wikisource (7 sections/Τμήματα, each
// restarting its own aphorism count at 1, via the generic {{π|N.}}
// reference template -- the SAME template el.wikisource reuses for
// Plato's Stephanus letters, see stephanus-marginalia.mjs).
//
// The numbering is otherwise a plain per-section integer run, but at least
// one point merges two traditionally-distinct aphorism numbers under one
// heading using the Latin conjunction "et". Verified byte-for-byte:
// el.wikisource Αφορισμοί/Ζ (7th section) wikitext has
//   "{{π|79 et 80.}} Ἐπὶ αἵματος ἐμέτῳ φθορὴ, ..."
// and live_priors hippocrates-aphorisms.txt line 945 has the identical
// "79 et 80. Ἐπὶ αἵματος ἐμέτῳ φθορὴ, ..." -- a CLEAN case (extraction did
// not damage this token at all); reported honestly as such rather than
// forcing it into the extraction-artifact family.
//
// This is also a documented NEAR-MISS / scope-limiter for seed S3: run
// homer-fr-linenum-mod5.mjs on this same file and it reports fired:false,
// because aphorism numbers are LEADING (start of paragraph) and step by 1
// per item (not TRAILING, step-5, like a verse-line count) -- see
// evidence.leadingVsTrailingCheck below, computed the same way S3's
// detector would, so the contrast is visible from one detector's output.

const NUMBERED_ITEM = /^\s*(\d{1,3})(?:\s+et\s+(\d{1,3}))?\.\s+\S/gmu;

export function detect(text, ctx = {}) {
  const matches = [...text.matchAll(NUMBERED_ITEM)];
  const merges = matches.filter((m) => m[2] !== undefined);
  const plainItems = matches.filter((m) => m[2] === undefined);

  // sanity: plain items should mostly increment by 1 (per-section restarts
  // mean this will break at section boundaries, which is expected and
  // reported, not treated as a failure).
  const nums = plainItems.map((m) => parseInt(m[1], 10));
  let increments = 0, breaks = 0;
  for (let i = 1; i < nums.length; i++) {
    if (nums[i] === nums[i - 1] + 1) increments++;
    else breaks++;
  }

  // contrast check: are these numbers leading (paragraph-initial) rather
  // than trailing (line-final, S3's shape)? Count how many matches are at
  // the very start of their line AND how many lines in the whole text end
  // in a bare trailing number (S3 shape) -- expect the former to dominate.
  const trailingNumberLines = (text.match(/\S \d{1,4}\s*$/gmu) || []).length;

  return {
    fired: merges.length >= 1,
    evidence: {
      totalNumberedItems: matches.length,
      latinEtMerges: merges.map((m) => m[0].trim()),
      plainIncrementsByOne: increments,
      plainSectionBreaks: breaks,
      leadingVsTrailingCheck: {
        leadingNumberedItems: matches.length,
        trailingNumberLinesElsewhereInText: trailingNumberLines,
        note: "S3/homer-fr-linenum-mod5 keys on TRAILING numbers; aphorism numbers here are LEADING, so that detector correctly does not fire on this file",
      },
    },
  };
}

// RULE: stephanus-marginalia  (family: source-convention; narrows seed S13)
//
// SCOPE: Plato dialogues on el.wikisource. Grounded two ways, from the
// ACTUAL wikitext behind two DIFFERENT dialogues:
//
//  (1) Republic (hand-typed wikitext, no djvu scan): the human editor types
//      literal brackets around a generic template call --
//        "[{{π|327a}}] Σωκράτης κατέβην..."
//      which the site's OWN rendering shows as a TIGHT "[327a]" (no space
//      inside the brackets in the HTML: "[<span id="p327a">...327a...</span>]");
//      the plain-text extraction pads it to "[ 327a ]" (see
//      tag-boundary-space-injection.mjs for that half of the mechanism).
//
//  (2) Sophist (djvu-scan transclusion, Burnet 1903 OCT): a page-specific
//      template is used bare, WITH THE PROOFREADER'S OWN SPACES already in
//      the wikitext on both sides --
//        "ὅς φησιν ἄλλους {{Αρίθμηση Burnet|p.216b|b}} τε θεοὺς"
//      -- confirmed from Σελίδα:Platonis opera.../375. The FIRST such call
//      on a scan page doubles as a running head ("St.I" / "p.216") that
//      merges with the dramatis-personae list at the top of the page
//      (both found verbatim in live_priors plato-sophist.txt lines 11-13).
//
// Net effect for a detector: the single Stephanus reference system shows
// up as letter tokens from a closed 5-letter set {a,b,c,d,e} that are
// SOMETIMES glued right before a recurring speaker-label lead (when a page
// break happens to land on a turn change -- seed S13's assumption) and
// just as often sit alone mid-sentence, always space-separated (never
// truly glued with zero space) once the underlying template resolves.
// This NARROWS S13: "glued to a speaker lead" is a common-but-not-required
// special case of "lands at the byte offset of a page break", not a
// dedicated convention of its own.

const STEPHANUS_LETTERS = new Set(["a", "b", "c", "d", "e"]);

export function detect(text, ctx = {}) {
  const bareLetterRe = /(^|[\s.;·])([a-e])( )/gmu;
  const speakerLeadRe = /^[\p{Lu}Ά-Ϋ][\p{Lu}Ά-Ϋ\s]{0,20}\.\s/u;

  const candidates = [...text.matchAll(bareLetterRe)].filter((m) => STEPHANUS_LETTERS.has(m[2]));
  let gluedToSpeaker = 0;
  let midSentence = 0;
  const gluedExamples = [];
  const midExamples = [];
  for (const m of candidates) {
    const after = text.slice(m.index + m[0].length, m.index + m[0].length + 24);
    if (speakerLeadRe.test(after)) {
      gluedToSpeaker++;
      if (gluedExamples.length < 4) gluedExamples.push((m[0] + after).trim().slice(0, 40));
    } else {
      midSentence++;
      if (midExamples.length < 4) midExamples.push(text.slice(Math.max(0, m.index - 15), m.index + m[0].length + 15).trim());
    }
  }

  // bracketed numeric+letter Stephanus refs, tight or spaced (works
  // whether or not tag-boundary-space-injection already padded them).
  const bracketRefs = [...text.matchAll(/\[\s?(\d{2,3}[a-e]?)\s?\]/gu)];

  // running-head merge signature (Sophist-style): a short line consisting
  // of "St.<roman>" or "p.<num>" glued to an all-caps name list.
  const runningHead = [...text.matchAll(/^\s*(St\.[IVXLC]+|p\.\d{2,4})\s+\p{Lu}/gmu)];

  const total = candidates.length + bracketRefs.length + runningHead.length;

  return {
    fired: total >= 2,
    evidence: {
      bareLetterCandidates: candidates.length,
      gluedToSpeakerLabel: gluedToSpeaker,
      midSentenceNotGlued: midSentence,
      gluedExamples,
      midSentenceExamples: midExamples,
      bracketedNumericRefs: bracketRefs.length,
      bracketedExamples: bracketRefs.slice(0, 5).map((m) => m[0]),
      runningHeadMerges: runningHead.length,
      runningHeadExamples: runningHead.slice(0, 3).map((m) => m[0]),
    },
  };
}

// RULE: editorial-seclusion-bracket-word  (family: source-convention)
//
// SCOPE: Plato dialogues transcribed from Burnet's OCT (and, by the same
// well-attested classical-editing convention, other apparatus-carrying
// critical editions in general). A square bracket wrapping a single
// ORDINARY WORD inside running dialogue -- as opposed to a bracket
// wrapping a NUMBER or one of Pindar's closed structural-label words,
// which this bench treats as a different phenomenon, see
// pindar-strophe-bracket-labels.mjs and pindar-dual-track-lineation.mjs --
// is the base print edition's own mark that the editor considers the word
// of doubtful authenticity (a classic OCT/Teubner "seclusit" convention).
//
// Grounded on el.wikisource Σελίδα:Platonis opera, ed. Burnet, tomus
// I.djvu/375 wikitext (Plato, Sophist 216a):
//   "ἑταῖρον δὲ τῶν ἀμφὶ Παρμενίδην καὶ Ζήνωνα [ἑταίρων], μάλα δὲ ἄνδρα..."
// confirmed present verbatim (undamaged) in live_priors plato-sophist.txt
// (24 instances measured across the dialogue, not just this one). Both are
// plain words, not digits, not one of the strophe/antistrophe/epode
// labels -- hence classified separately from the Pindar bracket family
// even though the surface glyph ("[" "]") is identical; disambiguation is
// by CONTENT CLASS, which is the point of this detector.
//
// GENERALIZES BEYOND the djvu-scanned pipeline: live_priors
// plato-republic.txt (hand-typed wikitext, NOT transcluded from Burnet's
// scan) ALSO carries 20 such word-brackets, e.g. "[Γύγου]", "[μῦθον]",
// "[οὐσίαν]" -- because Burnet edited the whole Republic too, and the
// Wikisource transcriber evidently typed the text (including Burnet's own
// critical brackets) directly from that edition rather than from a scan.
// Confirmed NOT to fire on Homer or Hippocrates (0 hits each) -- neither
// is a Burnet-edited dialogue and neither carries this convention.
//
// A single genuine hit is already meaningful (the base rate of an
// ordinary running word being bracketed by transcription accident is
// effectively zero), so no frequency threshold is imposed; count is
// reported for calibration.

const STRUCTURAL_LABELS = new Set(["στρ.", "αντ.", "επωδή", "στρ", "αντ", "επωδη"]);

export function detect(text, ctx = {}) {
  const matches = [...text.matchAll(/\[([^\[\]]{1,30})\]/gu)];
  const hits = [];
  for (const m of matches) {
    const inner = m[1].trim();
    if (/^\d+$/.test(inner)) continue; // a bare line number, e.g. Pindar [10]
    if (/^\d{1,3}[a-e]$/i.test(inner)) continue; // a Stephanus ref, e.g. [327a]
    if (STRUCTURAL_LABELS.has(inner.toLowerCase())) continue;
    if (/^(στρ\.|αντ\.|επωδή)\s*\d*$/u.test(inner)) continue;
    // must be exactly one alphabetic word (letters + Greek diacritics/elision marks only)
    if (!/^[\p{L}\p{M}̓̔́̀͂’᾽']+$/u.test(inner)) continue;
    if (/\s/.test(inner)) continue; // multi-word bracket content is a different phenomenon (e.g. a gloss)
    hits.push({ word: inner, context: text.slice(Math.max(0, m.index - 25), m.index + m[0].length + 5) });
  }
  return {
    fired: hits.length >= 1,
    evidence: {
      hitCount: hits.length,
      hits: hits.slice(0, 8),
    },
  };
}

// RULE: dramatic-vs-narrated-dialogue  (family: source-convention; near-miss for seed S11)
//
// SCOPE: Plato's dialogues on el.wikisource. Some (Sophist, Theaetetus,
// Parmenides, Statesman...) are staged as pure drama -- every turn opens
// with a short recurring speaker abbreviation ending in a period (seed
// S11's "ΘΕΑΙ." x536, "ΞΕ." x505). Others (the Republic) are written as
// Socrates' first-person NARRATED report of a conversation -- turns are
// introduced by a reporting verb ("ἔφη", "ἦν δ' ἐγώ", "ἔφην") with NO
// recurring speaker-label lead at all.
//
// Grounded directly on source: el.wikisource Σοφιστής (via the Burnet
// scan) opens "ΘΕΟ. Κατὰ τὴν χθὲς ὁμολογίαν..." / "ΣΩ. Ἆρ' οὖν..." --
// dramatic. el.wikisource Πολιτεία/Α (Republic I, hand-typed, no scan)
// opens "Σωκράτης κατέβην χθὲς..." and proceeds entirely as "ὁ οὖν
// Πολέμαρχος ἔφη·" / "ἦν δ' ἐγώ" / "ἔφη ὁ Γλαύκων" -- confirmed zero
// recurring all-caps speaker leads in Republic I's own wikitext and in the
// live_priors plato-republic.txt extraction.
//
// This is an explicit, source-grounded NOT-FIRE case for seed S11's
// speaker-label detector: a rule built only from Sophist/Theaetetus-style
// evidence would over-generalize to "every Platonic dialogue has speaker
// labels", which Republic falsifies.

const NARRATIVE_VERBS = new Set([
  "ἔφη", "ἔφην", "εἶπον", "εἶπε", "εἶπεν",
]);
// apostrophe-normalized forms handled by stripping combining/curly marks before lookup
const NARRATIVE_PHRASES = ["ἦν δ' ἐγώ", "ἦν δ’ ἐγώ", "ἦ δ' ὅς", "ἦ δ’ ὅς"];

function normalizeApos(s) {
  return s.replace(/[’᾽]/g, "'");
}

export function detect(text, ctx = {}) {
  const lines = text.split(/\r?\n/).filter((l) => l.trim() !== "");

  // speaker-lead candidate: a line that STARTS with an all-caps Greek run
  // (2+ letters) immediately followed by a period.
  const leadRe = /^\s*([\p{Lu}Ά-Ϋ]{2,15})\.\s/u;
  const leadCounts = new Map();
  for (const l of lines) {
    const m = leadRe.exec(l);
    if (m) leadCounts.set(m[1], (leadCounts.get(m[1]) || 0) + 1);
  }
  const recurringLeads = [...leadCounts.entries()].filter(([, n]) => n >= 5);

  // narrative-verb frequency, scanning the whole text (not line-anchored,
  // since these occur mid-sentence).
  const norm = normalizeApos(text);
  let narrativeHits = 0;
  const wordTokens = norm.match(/\p{L}+(?:'\p{L}+)?/gu) || [];
  for (const w of wordTokens) if (NARRATIVE_VERBS.has(w)) narrativeHits++;
  for (const phrase of NARRATIVE_PHRASES) {
    narrativeHits += norm.split(normalizeApos(phrase)).length - 1;
  }

  const isDramatic = recurringLeads.length >= 2;
  const isNarrated = !isDramatic && narrativeHits >= 5;

  return {
    fired: isDramatic, // "fired" = matches seed S11's dramatic-label phenomenon
    evidence: {
      classification: isDramatic ? "dramatic-labeled" : isNarrated ? "narrated-reported-speech" : "inconclusive",
      recurringSpeakerLeads: recurringLeads.slice(0, 10),
      distinctRecurringLeadCount: recurringLeads.length,
      narrativeVerbOccurrences: narrativeHits,
      linesExamined: lines.length,
    },
  };
}

// RULE: sappho-inline-crit-apparatus  (family: extraction-artifact)
//
// SCOPE: el.wikisource lyric poems edited with a {{crit|...}} template
// (apparatus criticus / textual variants) placed inline, immediately after
// the word it annotates, with no delimiting punctuation of its own.
//
// Grounded on el.wikisource "Ύμνος προς την Αφροδίτη" (Sappho fr. 1)
// wikitext -- 16 {{crit|...}} calls in this one poem, e.g.
//   "Ποικιλόθρον᾽{{crit|''v.l.'' ποικιλόφρον {{sc|m}}.}} ἀθάνατ᾽ Ἀφρόδιτα..."
// which flattens (confirmed in live_priors sappho-poems.txt) to
//   "Ποικιλόθρον᾽ v.l. ποικιλόφρον m . ἀθάνατ᾽ Ἀφρόδιτα..."
// i.e. the template braces vanish, the italic wikitext markup around
// "v.l." vanishes, and the {{sc|m}} small-caps template leaves a bare
// manuscript siglum with a stray space before the following period -- all
// indistinguishable, once flattened, from the poem's own words.
//
// The manuscript sigla are a CLOSED TABLE for this edition (confirmed by
// enumerating every {{sc|...}} call in the fetched wikitext): {c, dm,
// dmau, l, m, mss, p, v}. House rule: implemented as a Set, not a regex
// alternation.
//
// Firing logic distinguishes "apparatus flattened into the poem's own
// lines" from "a legitimate endnotes/apparatus section" (which would be
// fine, and is NOT what this rule flags) by CONTIGUITY: a real endnotes
// section is one unbroken run of hit-lines at the end of the document; the
// flattened-in-place case instead interleaves hit-lines with ordinary
// non-hit verse lines throughout a poem. (An earlier version of this
// detector required the hits to SPREAD across a large fraction of the
// whole file, which wrongly failed on a short poem embedded in a much
// larger multi-poem file -- fixed after measuring live_priors
// sappho-poems.txt, where the Aphrodite hymn's 12 hit-lines land in the
// file's first 2.5% by position but are correctly recognized as
// interleaved-not-clustered.)

const KNOWN_SIGLA = new Set(["c", "dm", "dmau", "l", "m", "mss", "p", "v", "a", "u", "d"]);
const APPARATUS_MARKERS = new Set(["v.l."]);

export function detect(text, ctx = {}) {
  const lines = text.split(/\r?\n/);
  const hitLineIdx = [];
  let siglumHits = 0;
  let markerHits = 0;
  const examples = [];

  lines.forEach((line, i) => {
    // siglum immediately followed by a period, as its own token (bounded
    // by spaces/punctuation), NOT part of a longer word.
    const siglumMatches = [...line.matchAll(/(^|[\s(])([a-z]{1,5})( ?)\.(?=$|[\s),])/g)];
    let lineHas = false;
    for (const m of siglumMatches) {
      if (KNOWN_SIGLA.has(m[2])) {
        siglumHits++;
        lineHas = true;
      }
    }
    for (const marker of APPARATUS_MARKERS) {
      if (line.includes(marker)) {
        markerHits++;
        lineHas = true;
      }
    }
    if (lineHas) {
      hitLineIdx.push(i);
      if (examples.length < 6) examples.push(line.trim().slice(0, 80));
    }
  });

  const nonBlankTotal = lines.filter((l) => l.trim() !== "").length;
  // "Looks like flattened-in apparatus" vs "looks like a real endnotes
  // section" is decided by CONTIGUITY, not by what fraction of the WHOLE
  // file the hits span (a short poem's own apparatus will only ever cover
  // a small slice of a file that concatenates many poems, which is not by
  // itself suspicious). A real endnotes section is one unbroken run of
  // hit-lines; apparatus flattened into the poem's own lines instead
  // interleaves hit-lines with ordinary non-hit verse lines.
  let hasGapBetweenHits = false;
  for (let i = 1; i < hitLineIdx.length; i++) {
    if (hitLineIdx[i] - hitLineIdx[i - 1] > 1) hasGapBetweenHits = true;
  }
  const clusteredAtEnd = hitLineIdx.length >= 2 && hitLineIdx[0] > lines.length * 0.85;

  const fired = hitLineIdx.length >= 3 && hasGapBetweenHits && !clusteredAtEnd;

  return {
    fired,
    evidence: {
      distinctLinesWithApparatus: hitLineIdx.length,
      siglumTokenHits: siglumHits,
      markerHits,
      hitLinesInterleavedWithNonHitLines: hasGapBetweenHits,
      clusteredAtEndLikeRealEndnotes: clusteredAtEnd,
      nonBlankLinesTotal: nonBlankTotal,
      exampleLines: examples,
      knownSigla: [...KNOWN_SIGLA],
    },
  };
}

// RULE: gutenberg-id-label-mismatch  (family: extraction-artifact; pipeline provenance)
//
// SCOPE: any locally-stored file whose name/label claims a Project
// Gutenberg ebook id, checked against a RAW (boilerplate-intact) fetch of
// that same file's own declared "[eBook #N]" / Title: header.
//
// CONCRETE CASE THAT MOTIVATED THIS RULE: live_priors ships
// "pg17270_The_Aeneid__Latin_.txt" with NO source_url and NO PG
// boilerplate (already stripped). Fetching the live, canonical
// https://www.gutenberg.org/cache/epub/17270/pg17270.txt today returns
// "The Interlude of Wealth and Health" (an anonymous English play) --
// confirmed via both the raw .txt header and the ebook's own <title>
// ("The Interlude of Wealth and Health by Anonymous | Project
// Gutenberg"). The TEXT actually stored under that filename is genuine,
// intact Virgil (byte-identical, after stripping PG boilerplate, to
// Gutenberg ebook **#227**, "Aeneidos" by Virgil, Language: Latin, fetched
// fresh and diffed line-for-line: 10,371/10,371 lines identical). So this
// is a pure ID-LABEL bug in the fetch/manifest pipeline, not damage to the
// text itself -- exactly the class of error "learn from originals, don't
// trust prior extractions" exists to catch: the content is trustworthy,
// the citation is not, and only fetching the original id surfaces that.
//
// SECOND CONFIRMED CASE, same territory: live_priors ships
// "pg10671_The_Iliad__Greek_.txt". Fetching the live, canonical
// https://www.gutenberg.org/cache/epub/10671/pg10671.txt today returns
// Erasmus Darwin's "The Botanic Garden. Part 2, Containing the Loves of
// the Plants. A Poem." (English, eBook #10671, confirmed via the raw
// .txt's own header). Not Greek, not Homer, not even a related genre.
// Two of two Gutenberg-labelled files checked in this territory were
// mislabelled, both in the same way (id echoes correctly, title is
// simply wrong) -- treated here as a real, if small-sample, base rate
// rather than a one-off: any Gutenberg id inherited from this pipeline is
// worth this check before it is trusted for citation.
//
// This detector is necessarily two-sided: it needs the freshly-fetched
// RAW text (with boilerplate) to read the true id/title, and a declared id
// to check it against (normally parsed by the caller from the local
// filename, passed as ctx.declaredId / ctx.declaredTitleFragment).

export function detect(text, ctx = {}) {
  const idMatch = /\[eBook #(\d+)\]/.exec(text);
  const titleMatch = /^Title:\s*(.+)$/mu.exec(text);
  const actualId = idMatch ? idMatch[1] : null;
  const actualTitle = titleMatch ? titleMatch[1].trim() : null;

  if (!ctx.declaredId) {
    return {
      fired: false,
      evidence: {
        note: "no ctx.declaredId supplied (parse it from the local filename's pgNNNNN token); reporting the source's own declared id/title only",
        actualId,
        actualTitle,
      },
    };
  }

  const idMismatch = actualId !== null && String(ctx.declaredId) !== actualId;
  const titleLooksUnrelated =
    ctx.declaredTitleFragment && actualTitle
      ? !actualTitle.toLowerCase().includes(String(ctx.declaredTitleFragment).toLowerCase())
      : null;
  // The bug this rule actually catches (see the Aeneid/#17270 case above)
  // is content/title mismatch even when the fetched id ECHOES the
  // declared id correctly -- id 17270 truthfully reports itself as id
  // 17270, the problem is that 17270 was never Aeneid to begin with. So
  // firing must key on title mismatch, not only id mismatch.
  const fired = idMismatch || titleLooksUnrelated === true;

  return {
    fired,
    evidence: {
      idMismatch,
      declaredId: ctx.declaredId,
      actualId,
      actualTitle,
      declaredTitleFragment: ctx.declaredTitleFragment || null,
      titleLooksUnrelated,
    },
  };
}

// RULE: verse-linebreak-capitalization-blind  (family: source-convention; re-grounds seed S2 for verse)
//
// SCOPE: classical verse (tested on both Greek and Latin). Claim: the
// verse LINE BREAK is orthographically invisible to capitalization --
// capitalization follows ordinary sentence-initial / proper-noun rules
// straight through a line break, so a naive "does this line start with a
// capital letter?" test is not a lineation signal.
//
// MEASURED, not assumed (per house policy of preferring a measured
// statistic to a hand-set rule): on Gutenberg ebook #227 (Vergil,
// Aeneidos, Latin), of 9,895 scored verse lines (all-caps heading lines
// like "LIBER I" excluded), 6,454 -- 65.2% -- begin with a LOWERCASE
// letter. That alone refutes "every verse line is capitalized". The
// SAME pattern holds in Greek: Iliad 1.1-1.2 "Μῆνιν ἄειδε... / οὐλομένην,
// ἣ μυρί'..." -- line 2 is lowercase because it continues the sentence,
// exactly like Latin "...ab oris / Italiam..." vs "...venit / litora...".
// This extends seed S2's "letter case is NOT evidence" (stated there for
// PROSE wrap-detection) into verse lineation.
//
// Uses Unicode letter-case properties (\p{Lu}/\p{Ll}), not an ASCII
// A-Z/a-z range, so it also scores Greek text correctly (per seed S1's
// warning against ASCII-only classes).

export function detect(text, ctx = {}) {
  const lines = text.split(/\r?\n/);
  let scored = 0;
  let lower = 0;
  let upper = 0;
  const lowerExamples = [];

  for (const raw of lines) {
    const line = raw.trim();
    if (!line) continue;
    // Skip ALL-CAPS heading-like lines (e.g. "LIBER I", "ΙΛΙΑΔΟΣ Α") --
    // those are titles/furniture, not the phenomenon under test.
    const letters = line.match(/\p{L}/gu) || [];
    if (letters.length === 0) continue;
    const isAllCaps = letters.every((ch) => ch === ch.toUpperCase()) && letters.some((ch) => ch !== ch.toLowerCase());
    if (isAllCaps && letters.length <= 20) continue;

    const m = /\p{L}/u.exec(line);
    if (!m) continue;
    const ch = m[0];
    scored++;
    if (/\p{Ll}/u.test(ch)) {
      lower++;
      if (lowerExamples.length < 8) lowerExamples.push(line.slice(0, 60));
    } else if (/\p{Lu}/u.test(ch)) {
      upper++;
    }
  }

  const lowerFraction = scored ? lower / scored : 0;
  // Null/threshold justification: plausible OCR or stray-punctuation noise
  // is well under 1-2%; a lowercase-start rate this far above that (>15%)
  // cannot be explained as noise and positively falsifies a
  // line-capitalizes rule. This is reported as a measured fraction, not
  // asserted as a fixed cutoff for "how verse works".
  const noiseCeiling = 0.02;
  const fired = scored >= 100 && lowerFraction > 10 * noiseCeiling;

  return {
    fired,
    evidence: {
      scoredLines: scored,
      lowercaseStart: lower,
      uppercaseStart: upper,
      lowercaseFraction: lowerFraction,
      noiseCeilingAssumed: noiseCeiling,
      exampleLowercaseLines: lowerExamples,
    },
  };
}

// RULE: latin-elision-unmarked  (family: script-convention)
//
// SCOPE: Latin verse. Claim: Latin orthography does not mark elision at
// all (no apostrophe-like character appears where scansion elides a
// final vowel/vowel+m before a following vowel/h), in contrast to Greek,
// which marks elision constantly (', ’, ᾽ all attested in the Homer/Sappho
// fetches in this territory's originals/ directory).
//
// MEASURED on Gutenberg ebook #227 (Vergil, Aeneidos, Latin), ~466K
// characters: zero occurrences of U+2019 (’) or U+1FBD (᾽) anywhere. The
// only apostrophe-like character present is the ASCII "'" (835 times),
// and it is used exclusively as a quotation mark around direct speech,
// confirmed by paired open/close contexts, e.g.
//   haec secum:  'Mene incepto desistere victam, ... ?'
// never at a word-internal elision boundary. To make the claim more than
// an absence, this detector ALSO counts plausible elision CONTEXTS (a
// word ending in a/e/i/o/u/y/am/em/im/om/um directly followed by a space
// and a word starting with a vowel or h) so that "zero marks" is shown
// against a backdrop where elision is phonologically expected often, not
// merely a text with no elision to mark in the first place.

const VOWEL_FINAL = /[aeiouyAEIOUY]$|[aeiouyAEIOUY]m$/;
const VOWEL_OR_H_INITIAL = /^[haeiouyHAEIOUY]/;

export function detect(text, ctx = {}) {
  const elisionMarks = (text.match(/[’᾽]/gu) || []).length;

  const words = text.match(/[A-Za-z]+/g) || [];
  let elisionContexts = 0;
  for (let i = 0; i < words.length - 1; i++) {
    if (VOWEL_FINAL.test(words[i]) && VOWEL_OR_H_INITIAL.test(words[i + 1])) elisionContexts++;
  }

  const asciiApos = (text.match(/'/g) || []).length;
  const pairedQuotePattern = [...text.matchAll(/'[^'\n]{3,80}[.?!,:]'/gu)];

  return {
    fired: elisionMarks === 0 && elisionContexts >= 50,
    evidence: {
      elisionMarkCount: elisionMarks,
      plausibleElisionContexts: elisionContexts,
      asciiApostropheCount: asciiApos,
      asciiApostrophePairedAsQuoteCount: pairedQuotePattern.length,
      exampleQuotePairs: pairedQuotePattern.slice(0, 3).map((m) => m[0].slice(0, 60)),
    },
  };
}

// RULE: ascii-triple-hyphen-dash  (family: source-convention)
//
// SCOPE: plain-ASCII Project Gutenberg editions that render a rhetorical
// dash / aposiopesis break as a fixed-width run of hyphens rather than a
// Unicode em-dash.
//
// MEASURED on Gutenberg ebook #227 (Vergil, Aeneidos, Latin): every one of
// 88 hyphen-runs of length >=2 is EXACTLY 3 characters wide, word-adjacent
// with no surrounding spaces (e.g. "gesserat Argis---\n  necdum...",
// "Quos ego---sed motos..." -- the famous Virgilian aposiopesis). No run
// of length 2 or 4+ occurs anywhere in the file. This is reported as a
// per-edition fingerprint (the width is measured, not assumed to always be
// 3 for every Gutenberg text) so the detector generalizes: it reports
// whichever width dominates, and fires when one width accounts for
// (nearly) all runs.

export function detect(text, ctx = {}) {
  const runs = [...text.matchAll(/-{2,}/g)];
  const lengths = new Map();
  for (const m of runs) {
    const len = m[0].length;
    lengths.set(len, (lengths.get(len) || 0) + 1);
  }
  const total = runs.length;
  let dominantLen = null, dominantCount = 0;
  for (const [len, count] of lengths) {
    if (count > dominantCount) { dominantLen = len; dominantCount = count; }
  }
  const dominantFraction = total ? dominantCount / total : 0;

  const examples = runs
    .filter((m) => m[0].length === dominantLen)
    .slice(0, 5)
    .map((m) => text.slice(Math.max(0, m.index - 20), m.index + m[0].length + 10));

  return {
    fired: total >= 3 && dominantFraction >= 0.9,
    evidence: {
      totalDashRuns: total,
      lengthDistribution: Object.fromEntries(lengths),
      dominantLength: dominantLen,
      dominantFraction,
      exampleContexts: examples,
    },
  };
}

// RULE: macron-edition-fingerprint  (family: source-convention)
//
// SCOPE: Latin verse. Claim: whether an edition marks long vowels with
// macrons (ā ē ī ō ū, and the same for uppercase) is a purely mechanical,
// highly reliable fingerprint distinguishing a PEDAGOGICAL/scansion
// edition from a plain reading edition of the identical work.
//
// GROUNDED as a genuine cross-edition contrast, same passage, both
// fetched fresh: la.wikisource Aeneis/Liber I (Greenough 1900 edition via
// The Latin Library) opens "Ille ego, quī quondam gracilī modulātus
// avēna..." (macrons throughout); Gutenberg ebook #227 (Aeneidos, no
// named editor) has the identical passage's canonical opening "Arma
// virumque cano, Troiae qui primus ab oris..." with plain unmarked
// vowels throughout. Measured macron density on a sample of each source
// confirms the contrast is not incidental (see evidence.perWordRate).

const MACRON_VOWELS = /[āēīōūĀĒĪŌŪ]/gu;

export function detect(text, ctx = {}) {
  const macronCount = (text.match(MACRON_VOWELS) || []).length;
  const words = (text.match(/\p{L}+/gu) || []).length;
  const perWordRate = words ? macronCount / words : 0;

  return {
    fired: perWordRate > 0.1, // macron edition: well over 1 in 10 words carries at least one
    evidence: {
      macronCharacterCount: macronCount,
      wordCount: words,
      macronsPerWord: perWordRate,
      classification: perWordRate > 0.1 ? "macron/scansion edition" : "plain (unmarked) edition",
    },
  };
}

// RULE: athetized-proem-letter-labels  (family: source-convention; edge case for line-numbering detectors)
//
// SCOPE: editions of the Aeneid (and potentially other works with a
// transmitted-but-rejected proem) that print the pseudo-Virgilian "ille
// ego qui quondam" lines before the canonical opening "Arma virumque
// cano". Ancient biographical tradition (Donatus/Servius) holds these
// lines were suppressed before publication; editions that print them
// anyway conventionally label them with LETTERS rather than folding them
// into the numbered line count.
//
// GROUNDED on la.wikisource Aeneis/Liber I wikitext: the four lines
// "Ille ego, quī quondam gracilī modulātus avēna {{versus|A}} / carmen...
// {{versus|B}} / ut quamvis... {{versus|C}} / gratum opus... {{versus|D}}"
// precede "Arma virumque canō..." which starts the real numbered sequence
// at {{versus|5}} (Template:versus is la.wikisource's line-number
// template -- confirmed by definition to float-right an id, the same
// family as el.wikisource's {{fr}}: see homer-fr-linenum-mod5.mjs -- so it
// flattens to a bare trailing token exactly like Homer's numbers, just
// with a LETTER instead of a digit for this preamble).
//
// A line-numbering detector that assumes every trailing marker is
// numeric will mis-handle this edition unless it explicitly tolerates a
// short letter-labelled preamble before the first digit appears.

export function detect(text, ctx = {}) {
  const lines = text.split(/\r?\n/);
  const letterLabelRe = /\S \(?([A-Z])\)?\s*$/;
  const numberLabelRe = /\S \(?(\d{1,4})\)?\s*$/;

  let firstNumberIdx = -1;
  const letterHitsBeforeFirstNumber = [];
  for (let i = 0; i < lines.length; i++) {
    const raw = lines[i];
    if (/^\s*\d{1,4}\s*$/.test(raw)) continue;
    const nm = numberLabelRe.exec(raw.replace(/\s+$/, " "));
    if (nm && firstNumberIdx === -1) {
      firstNumberIdx = i;
      break;
    }
    const lm = letterLabelRe.exec(raw.replace(/\s+$/, " "));
    if (lm) letterHitsBeforeFirstNumber.push({ lineIndex: i, letter: lm[1], text: raw.trim() });
  }

  // Require the letters to be a short consecutive run (A, B, C, ...) to
  // rule out a coincidental single capital-letter line ending.
  let consecutive = letterHitsBeforeFirstNumber.length > 0;
  for (let i = 1; i < letterHitsBeforeFirstNumber.length; i++) {
    const prev = letterHitsBeforeFirstNumber[i - 1].letter.charCodeAt(0);
    const cur = letterHitsBeforeFirstNumber[i].letter.charCodeAt(0);
    if (cur !== prev + 1) consecutive = false;
  }

  return {
    fired: letterHitsBeforeFirstNumber.length >= 2 && consecutive && firstNumberIdx !== -1,
    evidence: {
      letterLabelledLinesBeforeFirstNumber: letterHitsBeforeFirstNumber,
      isConsecutiveRun: consecutive,
      firstNumericLabelLineIndex: firstNumberIdx,
    },
  };
}

// RULE heim-language-chooser-table (source-convention)
// heimskringla.no hand-pastes a wikitext table at the top of EVERY page (poems and
// sagas alike): header cell literally "Velg språk" ("choose language"), a second-row
// label "Denne teksten finnes ... følgende språk" ("this text exists in the following
// languages"), and per-language columns drawn from a CLOSED, small set of Scandinavian/
// classical language names. The table's ROW COUNT is NOT fixed -- it varies per page
// (12-20 rows measured across 6 heimskringla.no pages) because each page catalogues a
// different number of known parallel-language editions. A detector must match the
// stable header/label cells, never require a fixed byte-length block.
//
// Scope: heimskringla.no wikitext (fetched via action=parse&prop=wikitext). Does NOT
// fire on is.wikisource.org (measured 0/3 on Snorra Edda subpages).

const LANGUAGE_LABELS = new Set([
  "Norrønt", "Islandsk", "Norsk", "Dansk", "Svensk", "Færøysk", "Latin",
]);

const HEADER_CELL = "Velg språk";
const SECOND_ROW_LABEL_PREFIX = "Denne teksten finnes"; // rest of the sentence varies slightly (seen with/without "i flere utgaver")

export function detect(text, ctx = {}) {
  const startIdx = text.indexOf("{|");
  if (startIdx === -1 || !text.slice(0, 4000).includes(HEADER_CELL)) {
    return { fired: false, evidence: { reason: "no {| ... Velg språk header found in first 4000 chars" } };
  }
  const endIdx = text.indexOf("|}", startIdx);
  const block = endIdx === -1 ? text.slice(startIdx, startIdx + 4000) : text.slice(startIdx, endIdx + 2);

  const rowCount = (block.match(/^\|-/gm) ?? []).length;
  const foundLanguages = [...LANGUAGE_LABELS].filter((lang) => block.includes(lang));
  const hasSecondRowLabel = block.includes(SECOND_ROW_LABEL_PREFIX);
  const hasHeaderCell = block.includes(HEADER_CELL);

  const fired = hasHeaderCell && foundLanguages.length >= 2;

  return {
    fired,
    evidence: {
      tableBytes: block.length,
      rowCount,
      hasHeaderCell,
      hasSecondRowLabel,
      languagesFound: foundLanguages,
      languagesFoundCount: foundLanguages.length,
      note: "rowCount and tableBytes are expected to DIFFER across pages of the same work-family; only hasHeaderCell/hasSecondRowLabel/languagesFound are the stable signal",
    },
  };
}

// RULE guoni-jonsson-caption-and-navbox (source-convention; RE-GROUNDS seed S6)
//
// S6 (seed, measured on an extraction) described ONE recurring block: "Eddukvæði /
// Sæmundar-Edda / GUÐNI JÓNSSON / bjó til prentunar" x45. Re-grounded on the ORIGINAL
// wikitext, this is actually TWO SEPARATE, differently-built kinds of recurring page
// furniture that happen to sit near each other, generated by two different mechanisms
// depending on which site is the source of the territory:
//
//   (a) heimskringla.no: a hand-typed centered caption block naming the editor
//       ("[[Guðni Jónsson|GUÐNI JÓNSSON]]<br>bjó til prentunar" or lowercase-name
//       variant) -- copy-pasted per page, byte-identical in wording, not a template.
//   (b) is.wikisource.org: a genuine MediaWiki TEMPLATE TRANSCLUSION "{{Verk|title=...
//       |author=...|previous=...|next=...|notes=|section=...|year=...}}" as line 1 of
//       EVERY subpage, which the parser expands into the "<-Prologus | title | Next->"
//       navigation strip; the editor caption ("Guðni Jónsson<br>bjó til prentunar")
//       is separately hand-typed just below it, same as (a).
//
// Measured: 9/9 fetched Guðni-Jónsson-edited pages (6 heimskringla.no Eddukvæði poems +
// 3 is.wikisource Snorra Edda subpages) carry the caption exactly once. A heimskringla.no
// page from a DIFFERENT edition (Ynglinga saga, eds. N. Linder og H. A. Haggson, 1869-72)
// carries the language-table (see heim-language-chooser-table.mjs) but 0 occurrences of
// "bjó til prentunar" -- the caption is edition-specific, not site-wide.

const CAPTION_PHRASE = "bjó til prentunar";
const EDITOR_NAME_NEEDLE = "jónsson"; // case-folded match against "Guðni Jónsson" / "GUÐNI JÓNSSON"

function countOccurrences(haystack, needle) {
  let count = 0, idx = 0;
  while ((idx = haystack.indexOf(needle, idx)) !== -1) { count++; idx += needle.length; }
  return count;
}

function parseVerkTemplate(text) {
  const m = text.match(/\{\{Verk\|([^}]*)\}\}/);
  if (!m) return null;
  const params = {};
  for (const part of m[1].split("|")) {
    const eq = part.indexOf("=");
    if (eq === -1) continue;
    params[part.slice(0, eq).trim()] = part.slice(eq + 1).trim();
  }
  return params;
}

export function detect(text, ctx = {}) {
  const captionCount = countOccurrences(text, CAPTION_PHRASE);
  const lower = text.toLowerCase();
  const editorNameNearby = captionCount > 0 && (() => {
    const idx = lower.indexOf(CAPTION_PHRASE);
    const window = lower.slice(Math.max(0, idx - 80), idx);
    return window.includes(EDITOR_NAME_NEEDLE);
  })();

  const verk = parseVerkTemplate(text);
  const verkPresent = verk !== null;
  const verkHasNavFields = verkPresent && "previous" in verk && "next" in verk && "section" in verk;

  const fired = (captionCount > 0 && editorNameNearby) || verkPresent;

  return {
    fired,
    evidence: {
      captionCount,
      editorNameNearby,
      mechanism: verkPresent ? "template-transclusion(Verk)" : (captionCount > 0 ? "hand-typed-caption" : "none"),
      verkTemplateParams: verk,
      verkHasNavFields,
      note: "expect captionCount===1 on Guðni-Jónsson-edited pages; 0 on other editors' pages from the same site (e.g. Ynglinga saga)",
    },
  };
}

// RULE eddic-dd-per-line-verse (source-convention; RE-GROUNDS seed S2)
//
// heimskringla.no's standalone Eddukvæði poems mark EVERY metrical half-line with a
// MediaWiki definition-indent prefix "::" (one or more colons), which the parser
// renders as one <dd> per line inside a flat <dl>. Stanza numbers get their own
// "::N." line; stanzas are separated by a literal blank-spacer line "::&nbsp;" (renders
// as <dd>&#160;</dd>); a suspected textual gap is marked by a bolded dash run (see the
// separate voluspa-lacuna-dash-marker rule). This is deliberate LINEATION, not a
// hard-wrap-and-reflow artifact -- so seed S2's wrap heuristic must not fire on it.
//
// S2 re-grounded: applying S2's own formula (a line is "wrap-broken" iff appending the
// next line's first word would exceed the block's 95th-percentile line length AND the
// line lacks closing punctuation; wrapped iff >half of interior lines are wrap-broken)
// to three heimskringla.no poems gives brokenFrac = 18.4% (Völuspá), 2.4% (Hávamál),
// 5.6% (Lokasenna) -- all far under the 50% threshold, so S2 correctly returns
// "not-wrapped". The coefficient of variation of line length (0.20-0.26) is also
// reported: real hard-wrapped prose clusters tightly near the wrap width (low CV);
// deliberately lineated verse does not.
//
// Also measured: is.wikisource/heimskringla.no prose paragraphs are typically stored as
// ONE long unbroken wikitext line per paragraph (no accidental mid-paragraph line
// breaks at all -- wrapping is a browser/CSS-render-time behavior, never present in the
// stored bytes). S2's antecedent (multiple "interior lines" to test) therefore does not
// even arise for MediaWiki-sourced prose; it only arises for deliberately-lineated verse.
// SCOPE NARROWING: S2 is applicable to plain-text/PDF/OCR sources with pre-wrapped
// bytes; it is inapplicable (untestable, not merely non-firing) to MediaWiki wikitext
// prose.

const CLOSE_PUNCT = /[.,;:!?"'’”)\]]$/;

function pct95(nums) {
  const s = [...nums].sort((a, b) => a - b);
  return s[Math.min(s.length - 1, Math.floor(0.95 * s.length))];
}

export function detect(text, ctx = {}) {
  const rawLines = text.split(/\r?\n/);
  const ddLines = rawLines.filter((l) => /^:+/.test(l));
  const bodyLines = ddLines
    .map((l) => l.replace(/^:+/, ""))
    .filter((l) => {
      const t = l.trim();
      return t && t !== "&nbsp;" && !/^\d+\.$/.test(t) && !/^'''-+'''$/.test(t);
    });
  const stanzaNumberLines = ddLines.filter((l) => /^:+\d+\.$/.test(l.trim()));
  const blankSpacerLines = ddLines.filter((l) => l.replace(/^:+/, "").trim() === "&nbsp;");

  const fired = ddLines.length > 0 && stanzaNumberLines.length >= 2;

  let s2 = null;
  if (fired && bodyLines.length >= 8) {
    const W = pct95(bodyLines.map((l) => l.length));
    let broken = 0;
    for (let i = 0; i < bodyLines.length - 1; i++) {
      const line = bodyLines[i];
      const nextFirst = (bodyLines[i + 1].trim().split(/\s+/)[0] ?? "");
      const wouldNotFit = line.length + 1 + nextFirst.length > W;
      const noClose = !CLOSE_PUNCT.test(line.trim());
      if (wouldNotFit && noClose) broken++;
    }
    const brokenFrac = broken / (bodyLines.length - 1);
    const lens = bodyLines.map((l) => l.length);
    const mean = lens.reduce((a, b) => a + b, 0) / lens.length;
    const variance = lens.reduce((a, b) => a + (b - mean) ** 2, 0) / lens.length;
    const cv = Math.sqrt(variance) / mean;
    s2 = { W_p95: W, brokenFrac, s2Verdict: brokenFrac > 0.5 ? "WRAPPED" : "not-wrapped", meanLineLen: mean, coefficientOfVariation: cv };
  }

  return {
    fired,
    evidence: {
      totalLines: rawLines.length,
      ddLineCount: ddLines.length,
      stanzaNumberLineCount: stanzaNumberLines.length,
      blankSpacerLineCount: blankSpacerLines.length,
      bodyLineCount: bodyLines.length,
      s2Regrounding: s2,
    },
  };
}

// RULE transcriber-forced-paragraph-break (source-convention / script-convention)
//
// MediaWiki collapses a single "\n" inside a paragraph into a plain space; only a
// BLANK line starts a new paragraph. The is.wikisource.org transcription of Snorra
// Edda's prose (Gylfaginning, Skáldskaparmál, Háttatal) instead marks many internal
// paragraph/turn breaks with a literal forced line break "<br>" followed by two
// non-breaking spaces "&nbsp;&nbsp;" (mimicking the printed edition's paragraph-indent)
// WITHOUT a blank line -- so the break is invisible to a blank-line-based paragraph
// splitter and only visible via this literal byte marker.
//
// Measured counts of the literal marker "<br>&nbsp;&nbsp;": Gylfaginning 185,
// Skáldskaparmál 112, Háttatal 80. In Gylfaginning and Skáldskaparmál (which frame their
// content as a dialogue) a closed, small set of named interlocutors recurs right after
// the marker; in Háttatal (a discursive, single-voice commentary with a catechism-style
// "Hvat er ...?" register but no named second speaker) the SAME marker is used purely to
// force generic paragraph breaks. The rule fires on the general marker in any of the
// three; the speaker-turn sub-classification is reported only when the following word
// matches the closed interlocutor table.

// Closed table of named interlocutors actually observed immediately after the marker
// (Gylfaginning: Hárr/Jafnhárr/Þriði/Gangleri frame; Skáldskaparmál: Ægir/Bragi frame).
// "Þá" ("then") is a generic anaphoric continuation, not a name, and is deliberately
// excluded -- see note in evidence about that coverage gap.
const INTERLOCUTORS = new Set(["Hárr", "Jafnhárr", "Þriði", "Gangleri", "Hann", "Sá", "Úlfrinn", "Bragi", "Ægir"]);
const SPEECH_VERBS = new Set(["segir", "svarar", "mælti"]);
const MARKER = "<br>&nbsp;&nbsp;";
const MARKER_HTML_RENDERED = "<br />"; // rendered HTML uses self-closing <br />; &nbsp; passes through as literal entity text in prop=text too in this corpus

function tally(text, marker) {
  const positions = [];
  let idx = 0;
  while ((idx = text.indexOf(marker, idx)) !== -1) {
    positions.push(idx);
    idx += marker.length;
  }
  return positions;
}

export function detect(text, ctx = {}) {
  const positions = tally(text, MARKER);
  let speakerTurns = 0;
  const speakerCounts = {};
  for (const pos of positions) {
    const after = text.slice(pos + MARKER.length, pos + MARKER.length + 40).trim();
    const word = after.split(/[\s,:]/)[0];
    if (INTERLOCUTORS.has(word)) {
      // check a speech verb follows within the next couple words (strip trailing
      // punctuation -- wikitext has e.g. "Hárr segir:" immediately before the quote)
      const secondWordRaw = after.split(/\s+/)[1] ?? "";
      const secondWord = secondWordRaw.replace(/[.,;:!?"']+$/u, "");
      if (SPEECH_VERBS.has(secondWord)) {
        speakerTurns++;
        speakerCounts[word] = (speakerCounts[word] ?? 0) + 1;
      }
    }
  }

  const fired = positions.length >= 1;

  return {
    fired,
    evidence: {
      markerCount: positions.length,
      speakerTurnSubset: speakerTurns,
      genericParagraphBreaks: positions.length - speakerTurns,
      speakerCounts,
      note: "genericParagraphBreaks counts include real speaker turns introduced by the anaphoric pronoun 'Þá' (\"then\") rather than a name -- a known, stated coverage gap of the closed interlocutor table, not evidence the marker itself is merely generic",
    },
  };
}

// RULE verse-blockquote-blank-line-doubling (extraction-artifact)
//
// Grounded by diffing the fetched is.wikisource.org wikitext against live_priors'
// snorra-edda.txt at two independent citations (Gylfaginning stanzas "5." and "2."):
// the ORIGINAL marks each quoted verse line with a single literal "<br>" and NO blank
// line between consecutive lines (a <blockquote> of N lines has zero blank interior
// lines). The live_priors flattened .txt instead inserts a BLANK LINE between every
// single one of those lines -- i.e. the extractor's HTML/wikitext-to-text step treated
// each "<br>" as a paragraph break (-> "\n\n") rather than a simple line break (-> "\n").
// This is a pipeline INCONSISTENCY, not a general text convention: the same pipeline
// correctly renders heimskringla.no's "::"-per-<dd> verse (see eddic-dd-per-line-verse)
// as ordinary single-newline-joined lines with blanks ONLY at genuine stanza gaps.
//
// GENERALIZATION (confirmed on a 3rd, non-verse sample): the live_priors snorra-edda.txt
// contains an even longer alternating run (292 lines) near its end, in the Skáldatal
// section (a plain LIST of skalds' names, one per line, e.g. "Haraldr hárfagri." /
// "Auðunn illskælda." / "Þorbjörn hornklofi."). Fetching Snorra Edda/Skáldatal's own
// wikitext confirms the identical source pattern: each name is its own "<br>Name."
// line with zero blank lines between them in the ORIGINAL. So the true scope of this
// artifact is broader than "verse quotations": it is ANY <br>-only itemized list in
// this source family, verse or prose. The rule and detector are written at that
// (correct, broader) scope; "verse" in the id is a naming artifact of where it was
// first found, not a scope limit.
//
// Detector: pure text-shape test, no knowledge of the source markup needed. Scans for
// a maximal run of lines that strictly alternates (short non-blank, blank, short
// non-blank, blank, ...). Significance is a Born null, not a hand-set length cutoff:
// treat each line as an i.i.d. Bernoulli(p) blank/non-blank draw, p = the file's own
// blank-line rate; P(a specific run of L lines matches the alternation exactly) =
// (p*(1-p))^(L/2); Bonferroni-correct by the number of candidate start lines in the
// file. fired = corrected p < 0.01 (the conventional significance level, applied AFTER
// the look-elsewhere correction -- the one place this detector uses a fixed number, and
// it is a significance convention, not a content threshold).

const MAX_VERSELIKE_LEN = 60;

export function detect(text, ctx = {}) {
  const lines = text.split(/\r?\n/);
  const isBlank = lines.map((l) => l.trim() === "");
  const nBlank = isBlank.filter(Boolean).length;
  const n = lines.length;
  const p = n ? nBlank / n : 0;

  let bestRun = 0, bestStart = -1;
  let i = 0;
  while (i < n) {
    // a run starts at a non-blank, verse-like-length line
    if (!isBlank[i] && lines[i].trim().length > 0 && lines[i].length <= MAX_VERSELIKE_LEN) {
      let j = i;
      let expectBlank = false;
      while (j < n) {
        const shouldBeBlank = expectBlank;
        if (shouldBeBlank) {
          if (!isBlank[j]) break;
        } else {
          if (isBlank[j] || lines[j].length > MAX_VERSELIKE_LEN) break;
        }
        expectBlank = !expectBlank;
        j++;
      }
      const runLen = j - i;
      if (runLen > bestRun) { bestRun = runLen; bestStart = i; }
      i = j > i ? j : i + 1;
    } else {
      i++;
    }
  }

  const perPairProb = p * (1 - p);
  const rawP = bestRun >= 2 ? Math.pow(perPairProb, Math.floor(bestRun / 2)) : 1;
  const correctedP = Math.min(1, n * rawP);

  const fired = bestRun >= 6 && correctedP < 0.01;

  return {
    fired,
    evidence: {
      totalLines: n,
      blankLineRate: p,
      longestAlternatingRun: bestRun,
      longestRunStartLine: bestStart,
      sampleAtStart: bestStart >= 0 ? lines.slice(bestStart, bestStart + Math.min(bestRun, 8)) : [],
      nullModel: "each line i.i.d. Bernoulli(blankLineRate); P(specific alternating run of L) = (p*(1-p))^(L/2)",
      rawRunProbability: rawP,
      bonferroniCorrectedP: correctedP,
      significanceThreshold: 0.01,
    },
  };
}

// RULE ascii-word-regex-fails-extended-latin (script-convention; EXTENDS seed S1)
//
// S1 (seed) measured eoreader7's native/the-fold/medium.js word-capture regex
// (`body.toLowerCase().replace(/[’']/g,"").match(/[a-z]+/)`, used for first/last
// word, rhyme, etc.) returning an EMPTY first word on 98-100% of lines in 17 of 57
// works, all in non-Latin scripts (Chinese, Arabic, Greek, Devanagari, Russian). Old
// Norse is written in the LATIN alphabet, so it was not in that list -- but it routinely
// uses letters outside plain a-z (þ, ð, æ, ö and the acutes á, é, í, ó, ú, ý), which are
// ordinary alphabetic letters in Old Norse, not optional diacritics the way French
// accents mostly are. Re-grounded directly on the fetched heimskringla.no ORIGINAL
// wikitext (not the extraction): replaying medium.js's exact regex against every true
// word of Völuspá's 544 verse lines mismatches (truncates or empties) 55.1% of "first
// word" captures; Hávamál's 1093 lines mismatch 47.1%. This is the SAME failure mode as
// S1, at a comparable rate, on a script S1's original survey did not cover -- S1's scope
// widens to "any Latin-EXTENDED orthography using letters outside a-z as ordinary
// letters", not just "non-Latin scripts".
//
// Threshold provenance (not hand-set): measured the identical mismatch rate on a plain
// Modern English control sample (Bellows 1923 translation, first 3927 tokenizable
// words) = 1.66% (65/3927) -- the residual noise floor from stray typography even in an
// all-ASCII language. fired = rate > 5x that measured floor (>8.3%), a large, clearly
// separated margin above real-world ASCII noise, not an arbitrary round number.

const ENGLISH_CONTROL_BASELINE = 0.016552075375604786; // measured, see probe-control-english.mjs
const FIRE_MULTIPLE = 5;

function mediumFirstWord(word) {
  const cleaned = word.toLowerCase().replace(/[’']/g, "");
  return (cleaned.match(/[a-z]+/) ?? [""])[0];
}

export function detect(text, ctx = {}) {
  const sampleSize = ctx.sampleSize ?? 4000;
  const words = text.split(/\s+/).filter(Boolean).slice(0, sampleSize);
  let total = 0, mismatched = 0;
  const extraLetterTally = {};
  const samples = [];
  for (const w of words) {
    const trueWord = w.replace(/^[^\p{L}]+|[^\p{L}]+$/gu, "").toLowerCase();
    if (!trueWord) continue;
    total++;
    const trueWordNoApos = trueWord.replace(/[’']/g, "");
    const captured = mediumFirstWord(trueWord);
    if (captured !== trueWordNoApos) {
      mismatched++;
      if (samples.length < 10) samples.push({ trueWord: trueWordNoApos, captured });
      for (const ch of trueWordNoApos) {
        if (!/[a-z]/.test(ch) && /\p{L}/u.test(ch)) {
          extraLetterTally[ch] = (extraLetterTally[ch] ?? 0) + 1;
        }
      }
    }
  }
  const rate = total ? mismatched / total : 0;
  const fired = total >= 50 && rate > FIRE_MULTIPLE * ENGLISH_CONTROL_BASELINE;

  return {
    fired,
    evidence: {
      totalWordsSampled: total,
      mismatched,
      mismatchRate: rate,
      englishControlBaseline: ENGLISH_CONTROL_BASELINE,
      fireThreshold: FIRE_MULTIPLE * ENGLISH_CONTROL_BASELINE,
      extraLetterTally,
      samples,
    },
  };
}

// RULE voluspa-lacuna-dash-marker (source-convention; DELIBERATELY NARROW scope)
//
// Within Guðni Jónsson's Eddukvæði edition as published on heimskringla.no, a suspected
// textual gap or interpolation point (a standard textual-critical judgment call in
// Völuspá scholarship, e.g. around the "dwarf-list" stanzas) is marked by a stand-alone
// list line consisting solely of a bolded run of hyphens: "::'''---------'''" (9
// hyphens). Measured: exactly 2 occurrences in Völuspá (between stanzas 8/9 and 16/17),
// 0 occurrences in the other 5 heimskringla.no Eddukvæði poems fetched (Hávamál,
// Vafþrúðnismál, Grímnismál, Lokasenna, Þrymskviða). This is intentionally scoped
// narrowly: it is a Völuspá-edition-specific critical-apparatus convention, NOT a
// general Eddukvæði-wide or heimskringla.no-wide convention, and the rule says so rather
// than overclaiming from n=1.

export function detect(text, ctx = {}) {
  const lines = text.split(/\r?\n/);
  const hits = [];
  for (let i = 0; i < lines.length; i++) {
    if (/^:+'''-{5,}'''$/.test(lines[i].trim())) {
      const prevStanza = [...lines.slice(0, i)].reverse().find((l) => /^:+\d+\.$/.test(l.trim()));
      const nextStanza = lines.slice(i + 1).find((l) => /^:+\d+\.$/.test(l.trim()));
      hits.push({
        line: i,
        dashCount: (lines[i].match(/-/g) ?? []).length,
        bracketsAfterStanza: prevStanza ? prevStanza.trim().replace(/^:+/, "") : null,
        bracketsBeforeStanza: nextStanza ? nextStanza.trim().replace(/^:+/, "") : null,
      });
    }
  }

  return {
    fired: hits.length > 0,
    evidence: {
      count: hits.length,
      occurrences: hits,
      note: "expected count is 0 for most Eddukvæði poems; a nonzero count elsewhere should be reported as widening this rule's scope, not assumed",
    },
  };
}

// Rule rule-01-speaker-label-line-geometry (source-convention)
//
// STATEMENT: a play-text's recurring speaker label is set in one of two
// mutually exclusive line geometries, and a single work is overwhelmingly
// (not just mostly) one or the other:
//   INLINE      "Label. speech continues on the same physical line"
//   STANDALONE  "Label." occupies its own line; the speech begins on the
//               next non-blank line.
// This is a per-EDITION convention, not fixed by period or by language:
// the 1623 First Folio (inline) and Alexander Dyce's 1850s edited text of
// Marlowe (also inline) share the OLD convention; a modern Gutenberg
// "Complete Works" Shakespeare re-setting (standalone) and Goethe's
// German Faust I (standalone, native to German drama printing) share the
// NEW convention. Geometry does not track spelling-modernization or
// language by itself -- it must be measured per witness.
//
// METHOD (no hand-set label list): find candidate labels by frequency --
// a token of 1-3 words, each word ALL-CAPS (Latin or Greek) or Titlecase,
// immediately followed by ".", that begins a line at least MIN_REPEATS
// times. For every occurrence of that exact "Label." at line-start, check
// whether the character right after it (skipping one space) is more text
// on the same line (INLINE evidence) or end-of-line (STANDALONE evidence).
// Decide with a two-sided binomial test against p=0.5 (no arbitrary cut
// like "90%"): report the p-value that the observed lopsidedness is due
// to chance. Both real witnesses below land at p < 1e-30 in one direction
// or the other -- this is not a borderline call.
//
// SCOPE: printed / digitized play texts (any language) whose speaker cue
// is "ShortLabel." at the start of a line. Does not apply to prose
// narrative with embedded dialogue (Cervantes: see rule-11), nor to
// Ancient-Greek dialogues, which abbreviate to 2-4 letters and are
// handled with their own derivation in rule-04 (that rule's inline vs.
// standalone question is trivial: Greek MSS/editions here are always
// inline, single manuscript-style paragraphs).

const MIN_REPEATS = 8;

function binomTwoSidedLogP(k, n) {
  // log2 P(X<=min(k,n-k) or X>=max(k,n-k)) under Binomial(n, 0.5), via the
  // normal approximation to log-binomial-CDF tail (n here is in the
  // hundreds, so this is accurate enough to say "astronomically small").
  // We report log2(p) so a huge lopsided n doesn't just print "0".
  const p = 0.5;
  const kk = Math.min(k, n - k);
  if (n === 0) return 0;
  const mean = n * p;
  const sd = Math.sqrt(n * p * (1 - p));
  if (sd === 0) return 0;
  const z = (kk - mean) / sd; // negative when lopsided
  // log2 of the one-sided normal tail P(Z <= z), doubled for two-sided,
  // via a standard asymptotic bound: log P(Z<=z) ~ -z^2/2 - log(-z*sqrt(2pi))
  if (z >= 0) return 0; // not lopsided at all
  const lnP = -0.5 * z * z - Math.log(-z * Math.sqrt(2 * Math.PI));
  return (lnP + Math.log(2)) / Math.LN2;
}

export function detect(text, ctx = {}) {
  // Gutenberg .txt is served CRLF (see rule-09): split on any line-ending
  // style so a trailing \r never breaks a "...(.*)$" match downstream.
  const lines = text.split(/\r\n|\r|\n/);
  // Leading whitespace is allowed (Folio indents "  King.", Marlowe "     FAUSTUS.");
  // each of 1-3 words starts with a capital (Latin or Greek) so this matches
  // both ALL-CAPS labels (FAUSTUS, MEPHISTOPHELES) and Titlecase ones (King,
  // Second Scholar); group 2 is whatever follows the label on the same line.
  const WORD = "[A-Z\\u0391-\\u03A9][A-Za-z\\u0391-\\u03C9']*";
  const labelToken = new RegExp(`^[ \\t]{0,12}(${WORD}(?: ${WORD}){0,2})\\.(.*)$`);
  const counts = new Map(); // label -> {inline, standalone}
  for (const line of lines) {
    const m = labelToken.exec(line);
    if (!m) continue;
    const label = m[1] + '.';
    const isInline = m[2].trim().length > 0;
    if (!counts.has(label)) counts.set(label, { inline: 0, standalone: 0 });
    const c = counts.get(label);
    if (isInline) c.inline++; else c.standalone++;
  }
  const qualifying = [...counts.entries()].filter(
    ([, c]) => c.inline + c.standalone >= MIN_REPEATS
  );
  let totalInline = 0, totalStandalone = 0;
  const perLabel = [];
  for (const [label, c] of qualifying) {
    totalInline += c.inline;
    totalStandalone += c.standalone;
    perLabel.push({ label, inline: c.inline, standalone: c.standalone });
  }
  const n = totalInline + totalStandalone;
  if (n === 0 || qualifying.length === 0) {
    return { fired: false, evidence: { reason: 'no recurring ALL-CAPS/Titlecase label found', qualifyingLabels: 0 } };
  }
  const log2p = binomTwoSidedLogP(totalInline, n);
  const dominant = totalInline >= totalStandalone ? 'inline' : 'standalone';
  const dominantFraction = Math.max(totalInline, totalStandalone) / n;
  return {
    fired: true,
    evidence: {
      qualifyingLabels: qualifying.length,
      totalOccurrences: n,
      totalInline,
      totalStandalone,
      dominantGeometry: dominant,
      dominantFraction: Number(dominantFraction.toFixed(4)),
      log2PValueOfLopsidedness: Number(log2p.toFixed(2)),
      sampleLabels: perLabel.slice(0, 6),
    },
  };
}

// Rule rule-02-bracket-population-split (source-convention, re-grounds seed S12)
//
// GROUNDING: Project Gutenberg #779 (Marlowe's DOCTOR FAUSTUS, ed. Dyce)
// carries the transcriber's own declared note, dropped by the live_priors
// extraction but present in the fetched original
// (originals/pg779_marlowe_faustus_dyce_full.txt, right before the PG
// license boilerplate):
//   "SQUARE BRACKETS: The square brackets, i.e. [ ] are copied from the
//   printed book, without change. The open [Exit brackets use in the book
//   have been closed [by mh]. ... the footnotes have been consolidated at
//   the end of the play ... each footnote is given a unique identity in
//   the form [XXX]."
// So THIS ONE FILE's square brackets are a mix of two populations that
// look identical (both "[...]") but have opposite provenance:
//   - letter-content brackets, e.g. "[Exit.]", "[Aside.]", "[Exeunt
//     MEPHISTOPHILIS.]" -- the ORIGINAL 1604/1616 print convention
//     (S12), copied "without change" (a few had a missing "]" silently
//     added by the transcriber, per the note).
//   - digit-only brackets, e.g. "[104]" -- a 20th-century Gutenberg
//     e-text footnote apparatus that does not exist in the print book at
//     all and must not be read as a stage direction.
// A reader (or a naive S12 detector) that treats every "[...]" as a stage
// direction will misclassify every footnote marker. The split is
// decidable from the bracket's own content alone: digits-only vs.
// contains-a-letter.
//
// SCOPE: any single-bracket "[...]" convention text (this family of
// Gutenberg drama e-texts; also expected wherever a transcriber
// consolidates footnotes into bracketed numerals -- test on other
// Gutenberg drama texts). Does NOT apply to double-bracket "[[...]]"
// (wiki-link artifacts, a different family) or to texts that use footnote
// markers as superscript numbers with no brackets at all.

export function detect(text, ctx = {}) {
  const brackets = [...text.matchAll(/\[([^\[\]]{1,80})\]/g)].map((m) => m[1]);
  let digitOnly = 0;
  let letterContent = 0;
  const digitSamples = [];
  const letterSamples = [];
  for (const inner of brackets) {
    if (/^\d+$/.test(inner)) {
      digitOnly++;
      if (digitSamples.length < 6) digitSamples.push(inner);
    } else if (/[A-Za-zΑ-ω]/.test(inner)) {
      letterContent++;
      if (letterSamples.length < 6) letterSamples.push(inner);
    }
  }
  const total = brackets.length;
  const fired = total >= 10 && digitOnly >= 3 && letterContent >= 3;
  return {
    fired,
    evidence: {
      totalBracketSpans: total,
      digitOnlyCount: digitOnly,
      letterContentCount: letterContent,
      otherCount: total - digitOnly - letterContent,
      digitOnlySamples: digitSamples,
      letterContentSamples: letterSamples,
      interpretation: fired
        ? 'two disjoint bracket populations present: digit-only = modern footnote apparatus, letter-content = period stage direction'
        : 'not enough of both populations to call this a mixed-provenance bracket text',
    },
  };
}

// Rule rule-03-german-parenthetical-stage-direction (source-convention,
// script-level contrast with S12)
//
// GROUNDING: measured on the freshly-fetched Goethe Faust I (pg2229,
// byte-identical to the live_priors copy -- see comparisons). Stage
// directions in this German print tradition are set in ROUND
// PARENTHESES, not English's square brackets:
//   "MEPHISTOPHELES (zu Faust)."   "(Verschwindet mit Faust.)"
//   "STIMME (von oben)."           "STIMME (von innen, verhallend)."
// Square brackets [ ] do not occur at all as a stage-direction device in
// this file. This is the same S12 FUNCTION (bracketed recurring
// furniture marking an action/aside) wearing a different bracket
// character by literary tradition -- English-tradition print uses [ ],
// German-tradition print uses ( ). A detector hard-coded to "[" would
// silently see zero stage directions in every German play.
//
// A second, distinct pattern shares the same parenthesis device: the
// SPEAKER LABEL line itself sometimes carries a parenthetical modifier
// glued to it before the final period -- "MEPHISTOPHELES (zu Faust)."
// -- rather than the direction standing as its own separate line. Both
// forms are measured separately below.
//
// SCOPE: German-tradition play texts (also expected in Schiller,
// Lessing, Büchner). Will NOT fire on English or Ancient-Greek texts in
// this territory (they use [ ] or nothing). A near-miss worth checking:
// French/Italian editions sometimes also use ( ) for stage directions,
// so this rule's signature (parenthesis + verb/preposition-shaped
// content) is not exclusively German -- state that honestly rather than
// claiming a language-exclusive signature.

export function detect(text, ctx = {}) {
  const parenSpans = [...text.matchAll(/\(([^()]{2,60})\)/g)].map((m) => m[1]);
  const bracketSpans = [...text.matchAll(/\[([^\[\]]{1,60})\]/g)];
  // A stage-direction-shaped parenthetical: starts lowercase (German verbs/
  // prepositions are lowercase unless a noun) OR contains a capitalized
  // proper name after a preposition -- cheap heuristic, just used to
  // separate likely-direction parens from e.g. "(I)"/"(1)" scene-number
  // parens, which we count separately.
  let directionLike = 0;
  let sceneNumberLike = 0;
  const directionSamples = [];
  for (const inner of parenSpans) {
    if (/^[IVX0-9]{1,4}$/.test(inner)) { sceneNumberLike++; continue; }
    if (/[a-zäöüß]/.test(inner)) {
      directionLike++;
      if (directionSamples.length < 8) directionSamples.push(inner);
    }
  }
  // speaker-label-with-glued-parenthetical: "^WORD+ \(.*\)\.$" as a whole line
  const lines = text.split(/\r\n|\r|\n/);
  let labelWithGlue = 0;
  const labelGlueSamples = [];
  const labelGlueRe = /^[A-ZÄÖÜ][A-ZÄÖÜ ]*\s\([^()]{2,40}\)\.$/;
  for (const line of lines) {
    if (labelGlueRe.test(line.trim())) {
      labelWithGlue++;
      if (labelGlueSamples.length < 5) labelGlueSamples.push(line.trim());
    }
  }
  const fired = directionLike >= 10 && bracketSpans.length === 0;
  return {
    fired,
    evidence: {
      squareBracketCount: bracketSpans.length,
      parenSpanCount: parenSpans.length,
      directionLikeParenCount: directionLike,
      sceneNumberLikeParenCount: sceneNumberLike,
      directionSamples,
      speakerLabelWithGluedParentheticalCount: labelWithGlue,
      speakerLabelWithGluedParentheticalSamples: labelGlueSamples,
      interpretation: fired
        ? 'stage directions are carried entirely by ( ), zero [ ] usage: the German-tradition device, functionally equivalent to S12 but a different character'
        : 'not a parenthesis-only stage-direction text',
    },
  };
}

// Rule rule-04-greek-sigla-and-margin-glue (script-convention + extraction-
// artifact; re-grounds seed S11 for Greek, and re-grounds/explains S13)
//
// GROUNDING (from the true Wikisource wikitext, not the plain-text
// extraction): fetched el.wikisource.org's Θεαίτητος and Σοφιστής pages
// via api.php action=parse&prop=wikitext. The WORK page's own wikitext is
// only a thin transclusion stub (see rule-06); the real per-page text
// lives at Σελίδα:Platonis opera, ed. Burnet, tomus I.djvu/273 (etc).
// There, the Stephanus page/section reference is produced by an explicit
// template, e.g.:
//   {{Αρίθμηση Burnet|p.142b|b}} ΕΥ. Ζῶντι καὶ μάλα μόλις...
// The template's DISPLAY argument (here "b") is a bare Latin letter a-e.
// When this renders to plain text the template collapses to just that
// letter, with no delimiter before the next character -- which is
// exactly the byte pattern already in live_priors/.../plato-theaetetus.txt:
//   " b ΕΥ. Ζῶντι καὶ μάλα μόλις..."
// So S13's "glued to speaker leads" is now explained mechanically: it is
// a numbering TEMPLATE's collapsed display value, not part of anyone's
// sentence, and it is always ONE of a small closed set {a,b,c,d,e} (the
// Stephanus sub-page letters) -- a TABLE, not a regex character-class
// guess.
//
// Separately, the speaker abbreviation itself (ΕΥ., ΣΩ., ΘΕΑΙ., ΞΕ., ...)
// is DERIVED here from the dialogue's own declared speaker-list line
// (e.g. "ΣΩΚΡΑΤΗΣ ΘΕΟΔΩΡΟΣ" / "ΕΛΕΑΤΗΣ ΞΕΝΟΣ ΘΕΑΙΤΗΤΟΣ" near the top,
// right after the "St.I" marker) rather than a hand-typed list of Greek
// names -- so the same code works on the Crito's ΣΩ./ΚΡ. or the
// Symposium's larger cast without editing. Measured here: every
// recurring "PREFIX." token in the body that reaches the line-start
// frequency bar is confirmed to be a literal prefix of one declared
// name, but the PREFIX LENGTH is not derivable by a formula (ΘΕΟΔΩΡΟΣ ->
// ΘΕΟ. is 3 letters, ΞΕΝΟΣ -> ΞΕ. is 2, ΘΕΑΙΤΗΤΟΣ -> ΘΕΑΙ. is 4): it is a
// per-name, editorially-fixed siglum, honestly scoped as such.
//
// SCOPE: Greek-Wikisource Platonic-dialogue plain-text extractions from
// this same Burnet OCT pipeline. Expected to hold on any dialogue in the
// same djvu (Euthyphro..Statesman): Crito, Phaedo, Apology, etc. Will NOT
// fire on a dialogue with only one named interlocutor (nothing to
// abbreviate against) or on non-dialogue Greek prose (Herodotus,
// Thucydides).

const MARGIN_LETTERS = new Set(['a', 'b', 'c', 'd', 'e']); // closed TABLE, not a regex range guess

export function detect(text, ctx = {}) {
  const lines = text.split(/\r\n|\r|\n/);
  // 1. find the declared speaker-list line: an early line of 2+ ALL-CAPS
  //    Greek words (each >=3 letters), ignoring a leading "St.I"/"p.NNN" tag.
  const GREEKCAP = 'Α-Ω';
  const nameListLine = /^\s*(?:St\.\S*\s+)?(?:p\.\S+\s+)?(([Α-Ω]{3,}\s+)+[Α-Ω]{3,})\s*$/;
  let declaredNames = [];
  for (let i = 0; i < Math.min(lines.length, 40); i++) {
    const m = nameListLine.exec(lines[i]);
    if (m) {
      const words = m[1].trim().split(/\s+/);
      if (words.length >= 2) { declaredNames = declaredNames.concat(words); }
    }
  }
  declaredNames = [...new Set(declaredNames)];

  // 2. find recurring "PREFIX." tokens at line-start (after an optional
  //    margin letter + space), and check each is a real prefix of a
  //    declared name.
  const abbrevCounts = new Map();
  const marginGlueHits = [];
  const abbrevAtLineStart = new RegExp(`^\\s*([${GREEKCAP}]{2,6})\\.`);
  for (const line of lines) {
    const stripped = line.replace(/^\s+/, '');
    const m = abbrevAtLineStart.exec(stripped);
    if (m) abbrevCounts.set(m[1], (abbrevCounts.get(m[1]) || 0) + 1);
    // margin-glue check: line begins with exactly one Latin letter from
    // the closed Stephanus set, one space, then a Greek abbreviation.
    const gm = /^([a-e]) ([Α-Ω]{2,6}\.)/.exec(stripped);
    if (gm && MARGIN_LETTERS.has(gm[1])) marginGlueHits.push(stripped.slice(0, 20));
  }
  const recurring = [...abbrevCounts.entries()].filter(([, n]) => n >= 5);
  const matchedToName = recurring.filter(([abbr]) =>
    declaredNames.some((name) => name.startsWith(abbr))
  );

  const fired = declaredNames.length >= 2 && matchedToName.length >= 2;
  return {
    fired,
    evidence: {
      declaredNames,
      recurringAbbreviations: recurring.map(([abbr, n]) => ({ abbr: abbr + '.', count: n })),
      abbreviationsMatchingADeclaredNamePrefix: matchedToName.map(([abbr, n]) => {
        const name = declaredNames.find((nm) => nm.startsWith(abbr));
        return { abbr: abbr + '.', count: n, fullName: name, prefixLength: abbr.length, nameLength: name ? name.length : null };
      }),
      marginLetterGlueCount: marginGlueHits.length,
      marginLetterGlueSamples: marginGlueHits.slice(0, 6),
    },
  };
}

// Rule rule-05-greek-punctuation-inventory (script-convention)
//
// Ancient Greek's own punctuation system uses FOUR stop-like marks with
// DIFFERENT shapes from Latin script: "." full stop (same glyph as
// Latin), "," comma (same glyph), a raised dot U+0387 ANO TELEIA (a
// colon/semicolon-strength pause), and a mark shaped like a Latin
// semicolon (;) that FUNCTIONS AS A QUESTION MARK. A reader (or
// eoreader7's stock ASCII-class reader, see seed S1) that assumes ";"
// always means "weak pause" will misread every Greek question as a
// statement.
//
// GROUNDING: measured directly on the full live_priors plato-theaetetus
// and plato-sophist bodies (15477+ words each per the manifest). BOTH
// dialogues: proper ANO TELEIA (U+0387) count = 0, GREEK QUESTION MARK
// (U+037E) count = 0. The mid-level pause is instead carried by plain
// ASCII colon ":" (U+003A) at only 13 and 7 occurrences total -- i.e.
// this Burnet-OCT-via-Wikisource digitization has effectively COLLAPSED
// the four-way system to three working marks: "." (2071/2096
// occurrences), "," (1973/1093), and ";" used at high frequency (457/463)
// for the QUESTION function, not a semicolon-pause function. A rule
// tuned only from theory ("Greek uses U+0387") would fire on nothing in
// this real corpus; the by-the-actual-bytes rule is: treat bare ASCII ";"
// in a polytonic-Greek text as the sentence-boundary/question mark, not
// as English's weak-pause semicolon.
//
// SCOPE: modern digitizations of Ancient Greek (Wikisource, Perseus-
// derived, most plain-text OCT transcriptions). Will differ on a source
// that deliberately keeps the traditional glyphs (test held-out targets);
// expect FEWER "?"/"!" always (Greek has neither natively) regardless.

export function detect(text, ctx = {}) {
  const isPolytonicGreek = /[ἀ-῿]/.test(text); // polytonic diacritics = a strong script signal
  const counts = {
    period: (text.match(/\./g) || []).length,
    comma: (text.match(/,/g) || []).length,
    asciiSemicolon: (text.match(/;/g) || []).length,
    asciiColon: (text.match(/:/g) || []).length,
    anoTeleia: (text.match(/·/g) || []).length,
    greekQuestionMark: (text.match(/;/g) || []).length,
    asciiQuestionMark: (text.match(/\?/g) || []).length,
    asciiExclamation: (text.match(/!/g) || []).length,
  };
  const usesAsciiSemicolonAsQuestion =
    counts.asciiSemicolon > 50 && counts.anoTeleia === 0 && counts.greekQuestionMark === 0;
  const fired = isPolytonicGreek && usesAsciiSemicolonAsQuestion;
  return {
    fired,
    evidence: {
      isPolytonicGreek,
      counts,
      collapsedToAsciiSemicolon: usesAsciiSemicolonAsQuestion,
      interpretation: fired
        ? 'proper ano teleia (U+0387) / Greek question mark (U+037E) are absent; ASCII ";" is doing the question-mark job here'
        : 'this text keeps (or never had) the dedicated Greek punctuation codepoints -- do not assume the collapse',
    },
  };
}

// Rule rule-06-wikisource-transclusion-stub (extraction-artifact --
// warns about a FUTURE fetch mistake, not about the plain-text files
// already in live_priors)
//
// GROUNDING: fetched el.wikisource.org/w/api.php?action=parse&page=
// Θεαίτητος&prop=wikitext directly (originals/theaetetus_wikitext_raw.json).
// The ENTIRE wikitext of the "work" page is:
//   {{Κεφαλίδα | τίτλος = Θεαίτητος | ... }}
//   <pages index="Platonis opera, ed. Burnet, tomus I.djvu" from=273 to=374/>
//   [[Κατηγορία:Φιλοσοφία|Θεαιτητος]] ...
// -- 934 bytes total, ZERO Greek dialogue text. The real transcription
// lives on 101 separate Σελίδα:.../N sub-pages (confirmed by fetching
// Σελίδα:Platonis opera, ed. Burnet, tomus I.djvu/273 directly: that
// returns the actual "ΕΥ. Ἄρτι, ὦ Τερψίων..." text). The Sophist's work
// page is the same shape: a <pages ... from=375 to=460/> stub, 850 bytes.
// A pipeline that does "fetch page X, take prop=wikitext, treat that as
// the source" -- exactly what the task brief suggests as one valid
// method -- gets almost nothing for any Wikisource text built on the
// ProofreadPage extension (all of Greek Wikisource's classical corpus,
// and most-not-recently-typed work on any language's Wikisource). You
// must use prop=text (which resolves the transclusion server-side) or
// walk the Σελίδα:/Page: sub-pages yourself.
//
// This is a warning about the FETCH step, not a defect in the
// plain-text files already sitting in live_priors (those already
// contain real dialogue text, so whatever produced them did resolve the
// transclusion correctly -- most likely by using prop=text or an
// index.php?action=raw render). It is included because the task
// instructions themselves say "use api.php (action=parse&prop=wikitext
// or text ...)" as if the two were interchangeable; grounded here, they
// are NOT for this entire class of source.
//
// SCOPE: any MediaWiki "parse&prop=wikitext" response for a book-page
// that was typed with the ProofreadPage extension (djvu/pdf-index-backed
// wikis: most old-book content on any language Wikisource). Does not
// apply to prop=text responses (already resolved) or to non-transcluded
// wiki pages (most Wikipedia articles).

export function detect(text, ctx = {}) {
  let wikitext = text;
  let sourceWasJson = false;
  try {
    const parsed = JSON.parse(text);
    const wt = parsed && parsed.parse && (parsed.parse.wikitext ?? parsed.parse.text);
    if (typeof wt === 'string') { wikitext = wt; sourceWasJson = true; }
  } catch { /* not JSON, treat `text` as raw wikitext already */ }

  const transclusionMatch = /<pages\s+index\s*=\s*"([^"]+)"\s+from\s*=\s*(\d+)\s+to\s*=\s*(\d+)\s*\/?>/i.exec(wikitext);
  // count Greek/Latin letters outside the transclusion tag as a proxy for
  // "how much actual body text is present in this blob"
  const withoutTag = transclusionMatch ? wikitext.replace(transclusionMatch[0], '') : wikitext;
  const letterCount = (withoutTag.match(/[A-Za-zΑ-ω]/g) || []).length;
  const fired = Boolean(transclusionMatch) && letterCount < 500;
  return {
    fired,
    evidence: {
      sourceWasJsonApiResponse: sourceWasJson,
      totalWikitextBytes: wikitext.length,
      transclusionTagFound: Boolean(transclusionMatch),
      transclusionIndex: transclusionMatch ? transclusionMatch[1] : null,
      transclusionFromPage: transclusionMatch ? Number(transclusionMatch[2]) : null,
      transclusionToPage: transclusionMatch ? Number(transclusionMatch[3]) : null,
      impliedSourcePageCount: transclusionMatch
        ? Number(transclusionMatch[3]) - Number(transclusionMatch[2]) + 1
        : null,
      letterCountOutsideTag: letterCount,
      interpretation: fired
        ? 'this "wikitext" is a thin transclusion wrapper; the real text is on the Page:/Σελίδα: sub-pages named by the index/from/to -- fetch prop=text or walk those sub-pages instead'
        : 'not a bare transclusion stub (either no <pages/> tag, or substantial text sits outside it)',
    },
  };
}

// Rule rule-07-page-boundary-nop-anomaly (extraction-artifact, subtle --
// see the honest null/near-miss result in the evidence)
//
// GROUNDING: the real Σελίδα: wikitext (rule-06's targets) ends each
// scanned page with a `{{nop}}` template when a sentence CONTINUES onto
// the next page-image, specifically to suppress the paragraph break
// MediaWiki would otherwise insert at that page boundary:
//   "...γὰρ ἐγὼ τοὺς φιλοσόφους τοιούτους προσαγορεύω.\n\nΣΩ. Καὶ καλῶς
//   γε...{{nop}}<noinclude><references/></noinclude>"
// So: if {{nop}} is missing or misapplied, a scan-page boundary would
// surface in the plain text as an unmotivated SINGLE-blank-line
// paragraph break mid-sentence -- no closing punctuation before it, a
// lowercase continuation after it.
//
// MEASURED (a real null AND a real, instructive false-positive):
// Theaetetus: 0/50 boundaries match this shape -- a clean null; every
// break is a genuine speaker-turn boundary. Sophist: the naive version
// of this check first flagged 2/59, both at the SAME place --
//   "...πεζῇ τε ὧδε ἑκάστοτε λέγων καὶ μετὰ μέτρων—
//    <4 blank lines>
//    οὐ γὰρ μήποτε τοῦτο δαμῇ, φησίν, εἶναι μὴ ἐόντα·
//    ἀλλὰ σὺ τῆσδ' ἀφ' ὁδοῦ διζήμενος εἶργε νόημα.
//    <4 blank lines>
//    b παρ' ἐκείνου τε οὖν μαρτυρεῖται..."
// -- which is Plato quoting Parmenides' own hexameter VERSE inside prose
// (237a). It is not a scan seam: the tell is that the gap is FOUR blank
// lines, not the one blank line every ordinary speaker-turn break uses.
// So the detector below counts the blank-line run length at each
// boundary and only treats a SINGLE-blank-line gap as a scan-seam
// candidate; a multi-blank-line gap is reported separately as
// "quotation/verse set-off" evidence, which a page-boundary defect has
// no reason to produce. With that fix: Sophist is also a clean 0/58.
//
// SCOPE: any plain-text extraction of a ProofreadPage-transcluded work,
// any language. Expected to almost never fire on a well-proofread
// Wikisource "featured text" (as measured here); expected TO fire on a
// rougher, less-reviewed transcription, or on a pipeline that reflowed
// paragraphs at fixed byte/page intervals instead of respecting {{nop}}.
// A text that quotes verse inside prose (Sophist, Symposium's speeches)
// will show multi-blank-line gaps -- report those, do not count them as
// anomalies, and do not mistake their absence for "this text has no
// scan-boundary risk".

const CLOSERS = /[.!?:;·;)"'»”]\s*$/; // Latin + Greek stops/questions + quote-closers

export function detect(text, ctx = {}) {
  // Split on runs of blank lines, but KEEP the run length: match a gap of
  // 1+ blank lines and record how many.
  const re = /(\r?\n[ \t]*){2,}/g;
  const blocks = [];
  let lastEnd = 0;
  let m;
  while ((m = re.exec(text))) {
    blocks.push({ text: text.slice(lastEnd, m.index), gapBlankLines: (m[0].match(/\n/g) || []).length - 1 });
    lastEnd = re.lastIndex;
  }
  blocks.push({ text: text.slice(lastEnd), gapBlankLines: null });
  const nonEmpty = blocks.filter((b) => b.text.trim().length > 0);

  let anomalies = 0;
  let multiBlankGaps = 0;
  const samples = [];
  const quoteSetOffSamples = [];
  for (let i = 0; i < nonEmpty.length - 1; i++) {
    const a = nonEmpty[i].text.trim();
    const gap = nonEmpty[i].gapBlankLines;
    const b = nonEmpty[i + 1].text.trim();
    if (!a || !b || gap == null) continue;
    const bFirstLine = b.split(/\r?\n/)[0];
    const bStartsLower = /^[a-zα-ω]/.test(bFirstLine.replace(/^[a-e]\s+/, ''));
    const aEndsOpen = !CLOSERS.test(a);
    if (gap >= 2) {
      if (aEndsOpen && bStartsLower) {
        multiBlankGaps++;
        if (quoteSetOffSamples.length < 4) {
          quoteSetOffSamples.push({ gapBlankLines: gap, endOfPrev: a.slice(-40), startOfNext: bFirstLine.slice(0, 40) });
        }
      }
      continue; // multi-blank gaps are never counted as scan-seam candidates
    }
    if (aEndsOpen && bStartsLower) {
      anomalies++;
      if (samples.length < 5) samples.push({ endOfPrev: a.slice(-40), startOfNext: bFirstLine.slice(0, 40) });
    }
  }
  const totalBoundaries = nonEmpty.length - 1;
  const fired = anomalies > 0;
  return {
    fired,
    evidence: {
      totalParagraphBoundaries: totalBoundaries,
      singleBlankLineAnomalies: anomalies,
      multiBlankLineQuoteSetOffs: multiBlankGaps,
      anomalyRate: totalBoundaries ? Number((anomalies / totalBoundaries).toFixed(4)) : 0,
      samples,
      quoteSetOffSamples,
      interpretation: fired
        ? `${anomalies} single-blank-line break(s) look like a page-scan seam (no closing punctuation before, lowercase continuation after)`
        : multiBlankGaps > 0
        ? `0 scan-seam anomalies; ${multiBlankGaps} multi-blank-line gap(s) look like verse/quotation set-off instead (not a defect)`
        : 'no such seam found: every blank-line break here coincides with real closing punctuation or a genuine new unit',
    },
  };
}

// Rule rule-08-transcriber-expanded-speaker-labels (extraction-artifact +
// source-convention)
//
// GROUNDING: Gutenberg #779's own "Original Comments on the preparation
// of the E-Text" (present in the freshly-fetched original, DROPPED by
// the live_priors extraction -- see comparisons) states:
//   "CHANGES TO THE TEXT: Character names were expanded. For Example,
//   SECOND SCHOLAR was SEC. SCHOL."
// Verified in the live_priors body: "SEC. SCHOL." occurs 0 times,
// "SECOND SCHOLAR." occurs 20 times. So the speaker labels visible in
// THIS e-text are transcriber-normalized full role-names, not the Dyce
// print edition's own abbreviations -- and nothing in the live_priors
// copy itself (the note is gone) tells a reader that. A rule that
// assumed "this Marlowe edition abbreviates speakers like the Folio
// does" would be flatly wrong for this file.
//
// The detector below cannot see the missing note (it is simply absent).
// Instead it tests, FOR EACH recurring multi-word role label actually
// found (e.g. "SECOND SCHOLAR"), whether any plausible abbreviated
// variant of THAT SAME label ("SEC. SCHOL.", "SECO. SCHOLA.", ...,
// generated by truncating each word to every length from 2 letters up to
// one short of the full word) occurs anywhere in the text. Searching for
// abbreviations of the specific labels in play -- rather than any short
// capitalized word at all -- avoids false "short form found" hits from
// unrelated capitalized words (stage directions, footnote sigla like
// "Sig.", a scene's "Palace.").
//
// SCOPE: Gutenberg drama e-texts of this vintage/house style. A positive
// (fired) result is a WARNING to re-fetch the source's own "Original
// Comments" section before trusting any speaker-label byte pattern as
// period-authentic; it is not itself proof the print edition abbreviated
// (only the dropped note proves that, which is why the comparison notes
// quote it directly instead of relying on this proxy alone).

function abbreviationVariantsExist(label, text) {
  const words = label.split(' ');
  for (let len = 2; len < Math.max(...words.map((w) => w.length)); len++) {
    const pattern = words.map((w) => escapeRe(w.length > len ? w.slice(0, len) : w)).join('\\.\\s?');
    const re = new RegExp('\\b' + pattern + '\\.', '');
    if (re.test(text)) return true;
  }
  return false;
}
function escapeRe(s) { return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }

export function detect(text, ctx = {}) {
  const lines = text.split(/\r\n|\r|\n/);
  const multiWordLabel = /^[ \t]{0,12}([A-Z][A-Z]+(?: [A-Z][A-Z]+){1,2})\.(?:\s|$)/;
  const multiWordCounts = new Map();
  for (const line of lines) {
    const mw = multiWordLabel.exec(line);
    if (mw) multiWordCounts.set(mw[1], (multiWordCounts.get(mw[1]) || 0) + 1);
  }
  // Drop obvious non-speaker false hits (title-page/running-head lines
  // that happen to look like a 2-3-word caps label) by requiring the
  // label to also appear as a genuine INLINE-or-standalone speaker cue,
  // i.e. recur at least MIN times, which title/running-head lines don't.
  const MIN = 3;
  const recurringMultiWord = [...multiWordCounts.entries()].filter(([, n]) => n >= MIN);
  const explicitTranscriberNote = /character names were expanded/i.test(text);

  const perLabel = recurringMultiWord.map(([label, count]) => ({
    label,
    count,
    abbreviatedVariantFound: abbreviationVariantsExist(label, text),
  }));
  const anyExpanded = perLabel.filter((p) => !p.abbreviatedVariantFound);
  const fired = perLabel.length >= 1 && anyExpanded.length === perLabel.length && !explicitTranscriberNote;
  return {
    fired,
    evidence: {
      recurringMultiWordLabels: perLabel,
      explicitTranscriberNotePresent: explicitTranscriberNote,
      interpretation: fired
        ? `all ${perLabel.length} recurring multi-word label(s) have zero abbreviated variant anywhere in this text, and no explanatory note survives in this copy -- likely transcriber-expanded; re-fetch the source's own production notes before trusting these as the print edition's own style`
        : explicitTranscriberNote
        ? 'this copy still carries the transcriber\'s own note -- no need to infer, it says so directly'
        : perLabel.length === 0
        ? 'no recurring multi-word role label found (this source may abbreviate by nature, like the Folio)'
        : 'at least one multi-word label DOES have an abbreviated variant in this same text -- not blanket-expanded',
    },
  };
}

// Rule rule-09-gutenberg-crlf (source-convention, platform-wide, not per-work)
//
// GROUNDING: found the hard way while building rule-01. Every one of the
// FIVE originals fetched fresh for this territory --
//   pg2270 (Shakespeare First Folio, en, 1623 spelling)
//   pg100  (Shakespeare Complete Works, en, modernized)
//   pg779  (Marlowe Doctor Faustus, en, Dyce 1850s)
//   pg2229 (Goethe Faust I, de)
//   pg2000 (Cervantes Don Quijote, es)
// -- is CRLF on 100% of its lines (135360/135360, 196398/196398,
// 3454/3454, 7542/7542, 38059/38059 measured directly on the curled
// bytes). This holds across four centuries of source material and three
// languages: it is a convention of the GUTENBERG PRODUCTION PLATFORM, not
// of any work, period or language. A downstream JS line-based regex like
// /^Label\.(.*)$/ (no "s"/dotAll flag, no line-ending normalization)
// SILENTLY MATCHES ZERO LINES on such a file: "." does not consume the
// trailing \r, so "$" (end-of-string, no "m" flag) can never be reached.
// This is not hypothetical -- it is exactly the bug rule-01 first hit in
// this session, on this territory's own First Folio file, before its
// line-splitting was fixed to `text.split(/\r\n|\r|\n/)`.
//
// EXTRACTION CHECK: the two live_priors files here that got a full
// byte-for-byte verification against their fetched original (Goethe
// pg2229, and the "pg5196" Quixote file which is really pg2000's body)
// PRESERVED CRLF at 100% of their body lines. The three Shakespeare/
// Marlowe live_priors files preserve CRLF at 100% of their FOLIO/PLAY
// BODY lines too; the only LF-only lines in those files are the short
// hand-written frontmatter block the corpus-builder prepended (Title/
// Author/Source/...), which is a legitimate, separate layer, not a
// defect. So for this territory the CRLF signature was not lost by
// extraction -- but nothing guarantees a future extraction preserves it,
// and any code that reads these .txt files must not assume bare \n.
//
// SCOPE: any file fetched from gutenberg.org/cache/epub/. Expect this to
// hold on every PG book regardless of language; the held-out targets
// below test that directly. Will NOT fire on Wikisource-derived files
// (el.wikisource.org serves LF; see the Plato originals in this same
// territory) or on files this pipeline re-saved with normalized line
// endings.

export function detect(text, ctx = {}) {
  const lineBreaks = text.match(/\r\n|\r(?!\n)|(?<!\r)\n/g) || [];
  let crlf = 0, lfOnly = 0, crOnly = 0;
  for (const b of lineBreaks) {
    if (b === '\r\n') crlf++;
    else if (b === '\r') crOnly++;
    else lfOnly++;
  }
  const total = lineBreaks.length;
  const fraction = total ? crlf / total : 0;
  const fired = total >= 20 && fraction >= 0.99;
  return {
    fired,
    evidence: {
      totalLineBreaks: total,
      crlfCount: crlf,
      lfOnlyCount: lfOnly,
      crOnlyCount: crOnly,
      crlfFraction: Number(fraction.toFixed(4)),
      hazard: 'a per-line regex ending in "$" without dotAll and without ' +
        'stripping \\r will match 0 lines on a 100% CRLF file',
    },
  };
}

// Rule rule-10-frontmatter-title-vs-body-title (extraction-artifact,
// general provenance QA -- bytes-only, so narrower than the real bug
// that motivated it)
//
// GROUNDING: re-fetching this territory's Gutenberg sources turned up TWO
// real wrong-catalog-ID cases (see comparisons):
//   - live_priors/01-literature-books/gutenberg/pg5196_Don_Quixote__Spanish_.txt
//     -- real Gutenberg #5196 is "Their Mariposa Legend" by Charlotte B.
//     Herr (English). This file's actual body IS genuine Cervantes
//     (byte-identical to a fresh pull of the real Quixote id, #2000).
//   - live_priors/.../pg2636_Faust__German_.txt -- real #2636 is
//     Sabatini's "Historical Nights' Entertainment" (English). This
//     file's body is genuine Goethe (byte-identical to #2229).
// In BOTH cases the human-readable filename ("Don_Quixote", "Faust") is
// right and the body is right -- only the invisible numeric catalog ID
// is wrong. THAT specific error is undetectable from bytes alone (you
// would have to re-query gutenberg.org, which detectors here may not
// do); it is reported directly as a finding, not as a rule.
//
// What IS bytes-only detectable, and a real (if rarer) sibling risk, is a
// mismatch between a file's OWN hand-written frontmatter "Title: ..."
// line and the actual title-page text at the head of its own body --
// e.g. if a frontmatter block were ever copy-pasted onto the wrong body,
// or hand-typed wrong. Every frontmatter'd file in this territory
// (Folio, modern Shakespeare, Marlowe) checks out clean (see evidence) --
// a real, honest null, not a defect. The Quixote/Faust files have NO
// frontmatter block at all (they start straight into body text), which
// is itself notable: there was nothing for a check like this one to
// verify, which is exactly the kind of file where the ID error slipped
// through unnoticed.
//
// SCOPE: any corpus file that prepends a "Title: ..." (optionally
// wrapped to a second indented line) frontmatter field before its body.
// Silent (does not fire, evidence.hasFrontmatterTitle=false) on a file
// with no such field -- that is a "cannot check" result, not a
// "verified clean" one, and should be read as such.

const STOPWORDS = new Set(['the', 'of', 'and', 'a', 'an', 'with', 'life', 'death', 'part', 'first', 'second', 'de', 'la', 'el', 'les', 'das', 'der', 'die']);

function significantWords(s) {
  return (s.toLowerCase().match(/[a-zà-öø-ÿΑ-ω]{4,}/g) || []).filter((w) => !STOPWORDS.has(w));
}

export function detect(text, ctx = {}) {
  const lines = text.split(/\r\n|\r|\n/);
  // frontmatter Title: field, possibly wrapped onto the next indented line
  let titleLine = '';
  const tIdx = lines.findIndex((l) => /^Title:\s*/.test(l));
  let hasFrontmatterTitle = false;
  if (tIdx !== -1 && tIdx < 10) {
    hasFrontmatterTitle = true;
    titleLine = lines[tIdx].replace(/^Title:\s*/, '');
    if (lines[tIdx + 1] && /^\s{4,}\S/.test(lines[tIdx + 1]) && !/:/.test(lines[tIdx + 1])) {
      titleLine += ' ' + lines[tIdx + 1].trim();
    }
  }
  if (!hasFrontmatterTitle) {
    return { fired: false, evidence: { hasFrontmatterTitle: false, note: 'no Title: frontmatter field in the first 10 lines -- nothing to check; see rule note on the Quixote/Faust ID cases this blind spot let through' } };
  }
  // Precisely finding "where the frontmatter block ends" is fragile --
  // continuation-line indentation style differs file to file (the Folio
  // wraps with 7 spaces, Marlowe's "Composed:" continuation has none at
  // all). Instead of bounding that edge exactly, just look at a generous
  // window after the Title: line: wide enough to run past frontmatter of
  // any style and reach the real title page, which cannot manufacture a
  // false NON-fire (more text only ever gives overlap MORE chances to be
  // found, so widening this window makes the check more lenient, not
  // less honest).
  const titlePageRegion = lines.slice(tIdx + 1, tIdx + 60).join(' ');

  const declaredWords = new Set(significantWords(titleLine));
  const bodyWords = new Set(significantWords(titlePageRegion));
  const overlap = [...declaredWords].filter((w) => bodyWords.has(w));
  const fired = declaredWords.size >= 2 && overlap.length === 0;
  return {
    fired,
    evidence: {
      hasFrontmatterTitle: true,
      declaredTitle: titleLine,
      declaredSignificantWords: [...declaredWords],
      titlePageRegionSample: titlePageRegion.slice(0, 160),
      overlapWords: overlap,
      interpretation: fired
        ? 'zero shared significant words between the declared Title: and the body\'s own title-page region -- this file\'s frontmatter and body may not belong together'
        : `${overlap.length} shared word(s) (${overlap.join(', ') || 'n/a'}) confirm the frontmatter matches this body`,
    },
  };
}

// Rule rule-11-spanish-raya-dialogue (script-convention: dialogue-inside-
// narrative, the Cervantes case the brief specifically asks for)
//
// GROUNDING: measured on the freshly-fetched Don Quijote (pg2000,
// byte-identical body to the live_priors "pg5196" file -- see
// comparisons). Direct speech inside Spanish narrative prose is NOT
// marked with quotation marks; a paragraph of dialogue simply OPENS with
// an em dash "—" (U+2014, the "raya"):
//   "— Porque, ¿cómo queréis vos que no me tenga confuso el qué dirá..."
// 2983 such lines in this one novel. When the narrator's own attribution
// tag interrupts a quote mid-sentence, the raya reappears around the tag
// itself and the quote resumes after it:
//   "— Decid —le repliqué yo, oyendo lo que me decía—: ¿de qué modo..."
// (open raya / speech / close raya / tag / re-open raya / colon / speech
// continues). A DIFFERENT bracket-like device, guillemets « », marks a
// nested WRITTEN document quoted inside the narration (e.g. the found
// manuscript's own opening line, "«Apenas había el rubicundo Apolo
// tendido..."), not spoken dialogue -- so the two must not be conflated
// as "the same quotation mark used twice"; they mark different things
// (utterance vs. quoted-document).
//
// This is why a bracket/quote inventory alone (as useful as it is for
// English "..."/German „..." or French «...») is not enough for Spanish
// narrative-with-dialogue: the dialogue turn boundary here is a LINE-
// INITIAL PUNCTUATION MARK, not a paired delimiter at all.
//
// BONUS, grounded while checking why "»" (290) so heavily outnumbers "«"
// (57) in this same novel: it is not mis-paired. A run of "»" at the
// START of several consecutive paragraphs --
//   "...con que lo escribistes.\n\n»En lo de..."
//   "...provecho el día de hoy.\n\n»En lo que..."
// -- is the classic continued-quotation mark: a multi-paragraph quoted
// document opens with a single "«", then EVERY subsequent paragraph still
// inside that same quotation is re-prefixed with "»" (not closed), and
// only the true end of the whole quoted block closes with "»" once more.
// So guillemet count alone is not "quotes should balance 1:1" evidence
// of corruption -- for a multi-paragraph quotation it never will.
//
// SCOPE: Spanish (and by extension French, which shares the raya
// convention) narrative prose containing direct speech. Will NOT fire on
// verse, on a pure play-text (speaker-label-per-line, no narrator), or on
// English/German narrative (which use paired quotation marks instead).

export function detect(text, ctx = {}) {
  const lines = text.split(/\r\n|\r|\n/);
  let rayaOpeningLines = 0;
  const rayaSamples = [];
  let midQuoteTagPattern = 0;
  for (const line of lines) {
    const t = line.trim();
    if (/^—\s*\S/.test(t)) {
      rayaOpeningLines++;
      if (rayaSamples.length < 4) rayaSamples.push(t.slice(0, 70));
    }
    // "— ... —tag—: ..." or "— ... —tag—," mid-quote attribution shape
    if (/^—[^—]{2,80}—[^—]{2,40}—[:,]/.test(t)) {
      midQuoteTagPattern++;
    }
  }
  const guillemetOpenCount = (text.match(/«/g) || []).length;
  const guillemetCloseCount = (text.match(/»/g) || []).length;
  const asciiQuoteCount = (text.match(/"/g) || []).length;
  const paragraphInitialCloseGuillemet = (text.match(/\n\s*\n\s*»/g) || []).length;

  const fired = rayaOpeningLines >= 20;
  return {
    fired,
    evidence: {
      rayaOpeningLineCount: rayaOpeningLines,
      rayaOpeningSamples: rayaSamples,
      midQuoteAttributionTagCount: midQuoteTagPattern,
      guillemetOpenCount,
      guillemetCloseCount,
      paragraphInitialCloseGuillemetCount: paragraphInitialCloseGuillemet,
      asciiDoubleQuoteCount: asciiQuoteCount,
      interpretation: fired
        ? 'dialogue turns are marked by a line-initial em dash (raya), not paired quotation marks; guillemets (if present) mark a different thing -- quoted written material inside the narration, not spoken dialogue'
        : 'em dash is not being used as a recurring line-initial dialogue marker here',
    },
  };
}

// Rule rule-12-inword-editorial-bracket (extraction-artifact)
//
// GROUNDING: found while testing rule-02 as a "near miss" on the First
// Folio Henry IV Part 1 original-spelling text. Its 6 bracket spans are
// NOT stage directions at all:
//   "S[aint]. Nicholas"   "fro[m] the Sheriffe"   "me[n] of such great leading"
//   "the K[ing]. being in danger"
// In every case the bracket sits INSIDE a single word with no whitespace
// on either side ("S" + "[aint]" + "." glued together) -- the Folio's own
// printed abbreviation ("S." for Saint, "fro" for from, "K." for King)
// was silently completed by a modern transcriber, who bracketed only the
// LETTERS THEY ADDED. This is a third, distinct bracket population,
// structurally different from both halves of rule-02 (which are always
// whitespace-bounded tokens): here the bracket has a non-space, non-
// punctuation character immediately before "[" AND immediately after "]"
// with no gap. Reading through this bracket (deleting it and keeping its
// letters) gives the modernized word; reading only the material outside
// brackets gives the Folio's own printed abbreviation. A "genuine
// original spelling" claim about this text is only true outside these
// spans.
//
// SCOPE: Gutenberg-style diplomatic transcriptions of early modern
// English print that mark editorial letter-supply this way. Will NOT
// fire on an edition that just silently expands abbreviations with no
// bracket (most modernized editions).
//
// MUST BE SCOPED TO LETTER-CONTENT BRACKETS ONLY. A digit-only footnote
// marker (rule-02) is conventionally typeset glued to the word it
// annotates too ("Mars did mate[1]") -- measured on this same Marlowe
// file, 90 of 175 digit-brackets are glued that way. Gluing alone would
// conflate the two. Restricting to letter-content brackets and asking
// what FRACTION of those are glued cleanly separates the two texts: the
// Folio sample is 6/6 = 100% glued (every bracket here is a letter
// supply), Marlowe's letter-content brackets are 4/76 = 5% glued (a
// small genuine minority -- "see['t]", "labouring cloud[s]", "cu[t]" --
// against a dominant free-standing stage-direction population).

export function detect(text, ctx = {}) {
  const spans = [...text.matchAll(/\[([^\[\]]{1,20})\]/g)].filter(
    (m) => !/^\d+$/.test(m[1]) // exclude the footnote-marker population (rule-02)
  );
  let glued = 0;
  let free = 0;
  const gluedSamples = [];
  for (const m of spans) {
    const before = text[m.index - 1] || '';
    const after = text[m.index + m[0].length] || '';
    const glueBefore = /[A-Za-zÀ-ſ]/.test(before);
    const glueAfter = /[A-Za-zÀ-ſ]/.test(after);
    if (glueBefore || glueAfter) {
      glued++;
      if (gluedSamples.length < 8) {
        const s = Math.max(0, m.index - 6);
        const e = Math.min(text.length, m.index + m[0].length + 4);
        gluedSamples.push(text.slice(s, e).replace(/\s+/g, ' '));
      }
    } else {
      free++;
    }
  }
  const total = spans.length;
  const gluedFraction = total ? glued / total : 0;
  const fired = total >= 3 && gluedFraction >= 0.5;
  return {
    fired,
    evidence: {
      letterContentBracketSpans: total,
      gluedCount: glued,
      freeStandingCount: free,
      gluedFraction: Number(gluedFraction.toFixed(3)),
      gluedSamples,
      interpretation: fired
        ? 'majority of (non-digit) brackets are glued inside a word: editorial letter-supply over the source\'s own printed abbreviation, not a stage direction'
        : 'letter-content brackets here are mostly free-standing tokens: a genuine stage-direction population (rule-02), gluing is a small minority',
    },
  };
}

// sw-wikilink-fusion
// A piped MediaWiki link [[Target|Label]] rendered by some extraction pipeline
// as "TargetLabel" -- target text and label text concatenated with zero
// separator (no pipe, no brackets, no space). Confirmed against live
// en.wikipedia.org wikitext for the "Mathematics" article: the byte
// "Mathematical analysisanalysis" in the flattened .txt corresponds to
// wikitext [[Mathematical analysis|analysis]] (piped link, target ends
// where label begins, glued).
//
// Detection strategy is deliberately NOT a dictionary or hand-picked word
// list (house rule: no closed-list-as-regex). It is self-referential: the
// document is its own vocabulary. A long unbroken alphabetic run is flagged
// only when it can be split into two halves that BOTH separately occur as
// free-standing whitespace-delimited words elsewhere in the same document.
// Real running prose essentially never glues two independently-attested
// words together with zero separator; a piped-link fusion reliably does,
// because the target and the label are each meaningful phrases the article
// uses elsewhere (the target is usually the article's own subject or a
// cross-referenced topic; the label is the words the prose actually needed).
export function detect(text, ctx = {}) {
  const minHalf = ctx.minHalf ?? 5;
  const minTokenLen = ctx.minTokenLen ?? 10;
  const wordRe = /[A-Za-zÀ-ÖØ-öø-ÿ]+/g;
  const tokens = text.match(wordRe) || [];

  const vocab = new Map();
  for (const w of tokens) {
    const lw = w.toLowerCase();
    vocab.set(lw, (vocab.get(lw) || 0) + 1);
  }

  const hits = [];
  const seen = new Set();
  for (const w of tokens) {
    if (w.length < minTokenLen) continue;
    const lw = w.toLowerCase();
    if (seen.has(lw)) continue;
    for (let i = minHalf; i <= w.length - minHalf; i++) {
      const a = lw.slice(0, i);
      const b = lw.slice(i);
      if (a === lw || b === lw) continue;
      const ca = vocab.get(a) || 0;
      const cb = vocab.get(b) || 0;
      if (ca >= 1 && cb >= 1) {
        hits.push({ token: w, splitAt: i, head: a, tail: b, headCountElsewhere: ca, tailCountElsewhere: cb });
        seen.add(lw);
        break;
      }
    }
  }

  return {
    fired: hits.length > 0,
    evidence: {
      totalWordTokens: tokens.length,
      distinctVocab: vocab.size,
      candidateLongTokens: tokens.filter(w => w.length >= minTokenLen).length,
      fusedHitCount: hits.length,
      examples: hits.slice(0, 20),
      params: { minHalf, minTokenLen },
    },
  };
}

// sw-html-entity-debris
// Numeric/named HTML character references (&#160; &#8203; &nbsp; ...) survive
// un-decoded in a text extraction. Confirmed: en.wikisource.org's rendered
// HTML for "1911 Encyclopaedia Britannica/Mathematics" genuinely contains
// "by&#160;Alfred North Whitehead" (a real non-breaking space inserted by the
// EB1911 header template) -- so the entity itself is not invented by the
// extraction, but a correct HTML->text step must decode it to the Unicode
// character (or a plain space), never leave the literal "&#160;" bytes.
export function detect(text, ctx = {}) {
  const re = /&#\d{1,7};|&#x[0-9a-fA-F]{1,6};|&[a-zA-Z][a-zA-Z0-9]{1,31};/g;
  const matches = text.match(re) || [];
  const counts = new Map();
  for (const m of matches) counts.set(m, (counts.get(m) || 0) + 1);
  const top = [...counts.entries()].sort((a, b) => b[1] - a[1]).slice(0, 12);
  return {
    fired: matches.length > 0,
    evidence: {
      totalEntities: matches.length,
      distinctEntities: counts.size,
      top,
      charsPer10k: text.length ? +(matches.length / (text.length / 10000)).toFixed(2) : 0,
    },
  };
}

// sw-citation-bracket-spacing
// A more specific sibling of sw-html-entity-debris: MediaWiki's <cite>/
// reference numbering renders as
//   <sup class="reference"><a href="#cite_note-1"><span class="cite-bracket">
//   &#91;</span>1<span class="cite-bracket">&#93;</span></a></sup>
// i.e. THREE separate text nodes ("&#91;", "1", "&#93;") with no whitespace
// between them in the real DOM. A DOM-walking extractor that joins every
// child text node with a single space (rather than concatenating inline
// nodes with no separator) turns "Leibnitz,[1] who" into
// "Leibnitz, &#91; 1 &#93; who" -- confirmed against the live rendered HTML
// for en.wikisource.org's EB1911 Mathematics page. The signature is the
// specific spaced pattern, not just the bare entities.
export function detect(text, ctx = {}) {
  const re = /\s&#91;\s*\d+\s*&#93;/g;
  const matches = text.match(re) || [];
  return {
    fired: matches.length > 0,
    evidence: {
      count: matches.length,
      examples: matches.slice(0, 10),
    },
  };
}

// sw-mediawiki-chrome-leak
// Wikisource/Wikipedia page furniture (prev/next breadcrumb arrows, a
// "sister projects" navbox, a bare internal page id) leaking into an
// extraction as if it were article prose. Confirmed against the live
// rendered HTML: this exact block sits inside
//   <div class="ws-header ... ws-noexport noprint dynlayout-exempt">
// i.e. the SOURCE itself marks it non-content with two independent,
// standard, cross-wiki CSS class conventions (ws-noexport is Wikisource's
// own export-exclusion class; noprint is the generic MediaWiki
// print/export-exclusion class also used on Wikipedia/Wikinews/Wiktionary).
// An extractor that does not special-case those classes will pull this
// chrome in verbatim.
export function detect(text, ctx = {}) {
  const head = text.slice(0, ctx.headWindow ?? 2000);
  const hasArrow = /[←→]/.test(head);
  const hasSister = /sister projects/i.test(head);
  const pageidMatch = head.match(/(?:^|[\s])(\d{5,8})(?:[\s]|$)/);
  const hasDisclaimer = /disclaimer/i.test(head);
  const fired = hasArrow && hasSister;
  return {
    fired,
    evidence: {
      hasArrow,
      hasSister,
      hasDisclaimer,
      bareNumericId: pageidMatch ? pageidMatch[1] : null,
      headSample: head.slice(0, 260),
    },
  };
}

// sw-css-block-as-text
// A MediaWiki <style data-mw-deduplicate="TemplateStyles:..."> element's raw
// CSS content is kept as running text because the extractor stripped the
// <style> TAG but not its CONTENT (a regex tag-stripper does this; a real
// DOM parser that drops <style>/<script> subtrees does not). Confirmed
// against the live Wikinews rendered HTML for "Wikinews Shorts: November 13,
// 2008": the raw ".mw-parser-output .wn-social-bookmarks-box{...}" ruleset
// text sits as a direct sibling of a closing </div>, i.e. inline in the
// content flow, not confined to a header wrapper -- so this is a general,
// portable HTML-to-text correctness issue, not specific to any one wrapper
// class.
export function detect(text, ctx = {}) {
  const hasMwHook = /\.mw-parser-output/.test(text);
  const cssRuleRe = /\{[^{}]*:[^{}]*;[^{}]{0,400}?\}/g;
  const ruleMatches = text.match(cssRuleRe) || [];
  const fired = hasMwHook || ruleMatches.length >= (ctx.minRules ?? 3);
  return {
    fired,
    evidence: {
      hasMwParserOutputHook: hasMwHook,
      cssLikeRuleCount: ruleMatches.length,
      sample: (ruleMatches[0] || "").slice(0, 160),
    },
  };
}

// sw-per-item-archival-notice-repeat
// Re-grounds seed S7 ("duplicated fetch content = the fetcher concatenated
// overlapping subpages") against a case where repeated boilerplate is NOT a
// fetch bug. A Wikinews "Shorts" compilation page carries one
// {{Archived-cc-2.5}} licence/archival-notice transclusion PER BRIEF ITEM,
// not one for the whole page. Confirmed against the live rendered HTML's own
// MediaWiki "NewPP limit report" debug comment, which reports
// "Template:Archived-cc-2.5 ... 4" transclusions on a page with exactly 4
// news briefs. The detector is shape-only (repeat count vs item count); it
// does not, and cannot, hard-code the count itself, since it is a property
// of each individual compilation page.
export function detect(text, ctx = {}) {
  const noticeRe = /is no longer publicly editable/gi;
  const notices = text.match(noticeRe) || [];
  const sourcesHeadRe = /(^|\n)\s*Sources\s*(\n|$)/g;
  const sourcesHeads = text.match(sourcesHeadRe) || [];
  // Fallback item-boundary signal when "Sources" headings were not kept
  // verbatim: count of distinct "[edit]" section markers, one per brief.
  const editMarkers = text.match(/\[\s*edit\s*\]/gi) || [];
  const itemCountGuess = sourcesHeads.length || editMarkers.length || null;
  const countsMatch = itemCountGuess != null && notices.length === itemCountGuess;
  return {
    fired: notices.length > 1,
    evidence: {
      noticeRepeatCount: notices.length,
      itemBoundarySignal: itemCountGuess,
      countsMatch,
      interpretation:
        notices.length > 1
          ? countsMatch
            ? "benign: repeat count equals per-item boundary count (source's own per-item template use)"
            : "unexplained by per-item count -- check for true fetch duplication (seed S7)"
          : "no repetition observed",
    },
  };
}

// sw-scan-furniture-noinclude
// Runs on a Wikisource Page:-namespace WIKITEXT (not the flattened article
// text). Confirmed against the live wikitext of
// "Page:EB1911 - Volume 17.djvu/897": the running head and page number are
// declared as machine-readable data --
//   <noinclude>{{EB1911 Page Heading|878|MATERA|MATHEMATICS| }}</noinclude>
// -- and are therefore, by the proofreaders' own convention, EXCLUDED from
// the transcluded article. Their absence downstream is correct behaviour,
// not an extraction bug. A sibling {{EB1911 fine print/s}} ... {{.../e}}
// span marks bibliographic references set in smaller type on the page.
// Independently confirmed by mechanical CV (tesseract --psm 3 tsv) on the
// page-897 scan image: a block at the very top spans both columns reading
// "MATERA—MATHEMATICS" and a lone "878" block sits at the top-left --
// geometry matches the template's own declared fields exactly.
export function detect(text, ctx = {}) {
  const headingRe = /<noinclude>[\s\S]{0,400}?\{\{[^}|]*Page Heading\s*\|([^}]*)\}\}/i;
  const m = text.match(headingRe);
  const fineprint = /\{\{[^}]*fine print\/s\}\}[\s\S]*?\{\{[^}]*fine print\/e\}\}/i.test(text);
  const fields = m ? m[1].split("|").map((s) => s.trim()) : null;
  return {
    fired: !!m,
    evidence: {
      pageHeadingFields: fields, // [pageNumber, leftRunningHead, rightRunningHead, ...]
      hasFinePrintSpan: fineprint,
      wrappedInNoinclude: !!m,
    },
  };
}

// sw-cv-two-column-runninghead
// Pure geometry read of a `tesseract <img> out --psm 3 tsv` output (passed in
// as `text`, the .tsv file's contents). No model, no OCR-text trust required
// -- only the word/line bounding boxes, which are script-independent (the
// task's own framing: "layout geometry works in any script even though only
// English recognition is installed"). Detects: (1) a two-column body, by
// clustering word left-x into two populations separated by a vertical gap
// spanning most of the page height; (2) a running head, by a short text band
// at the very top of the page whose bounding box spans (near-)both columns.
// Confirmed on the actual scan of 1911 Encyclopaedia Britannica vol. 17 page
// 897: two clear column bands plus a top band reading "MATERA—MATHEMATICS",
// exactly matching that page's own {{EB1911 Page Heading}} declaration.
export function detect(text, ctx = {}) {
  const rows = text
    .trim()
    .split("\n")
    .slice(1)
    .map((l) => l.split("\t"));
  const words = [];
  let pageW = 0,
    pageH = 0;
  for (const r of rows) {
    const level = r[0];
    if (level === "1") {
      pageW = +r[6] + +r[8];
      pageH = +r[7] + +r[9];
    }
    if (level !== "5") continue;
    const left = +r[6],
      top = +r[7],
      width = +r[8],
      height = +r[9];
    const wtext = r.slice(11).join("\t");
    if (!wtext || !wtext.trim()) continue;
    words.push({ left, top, width, height, text: wtext });
  }
  if (!words.length) return { fired: false, evidence: { reason: "no words parsed" } };

  const midX = pageW / 2 || Math.max(...words.map((w) => w.left + w.width)) / 2;
  const leftCol = words.filter((w) => w.left + w.width / 2 < midX);
  const rightCol = words.filter((w) => w.left + w.width / 2 >= midX);
  const spanY = (ws) => (ws.length ? Math.max(...ws.map((w) => w.top + w.height)) - Math.min(...ws.map((w) => w.top)) : 0);
  const leftSpan = spanY(leftCol);
  const rightSpan = spanY(rightCol);
  const twoColumn =
    leftCol.length > (ctx.minColWords ?? 15) &&
    rightCol.length > (ctx.minColWords ?? 15) &&
    leftSpan > pageH * 0.3 &&
    rightSpan > pageH * 0.3;

  const topBandCutoff = pageH * (ctx.topBandFraction ?? 0.06);
  const topWords = words
    .filter((w) => w.top < topBandCutoff)
    .sort((a, b) => a.left - b.left);
  const topSpansBothColumns =
    topWords.length > 0 &&
    Math.min(...topWords.map((w) => w.left)) < midX * 0.8 &&
    Math.max(...topWords.map((w) => w.left + w.width)) > midX * 1.2;
  const runningHeadText = topWords.map((w) => w.text).join(" ");

  return {
    fired: twoColumn || topSpansBothColumns,
    evidence: {
      pageW,
      pageH,
      leftColumnWordCount: leftCol.length,
      rightColumnWordCount: rightCol.length,
      twoColumnLayout: twoColumn,
      topBandSpansBothColumns: topSpansBothColumns,
      runningHeadGuess: runningHeadText,
    },
  };
}

// sw-nonlatin-ocr-corruption-predictor
// cv-distilled: predicts, from BYTES ALONE (no OCR run needed), whether an
// English-only tesseract pass over a page image would corrupt a span rather
// than confirm it. Rule: if a span of the ALREADY-KNOWN transcription (e.g.
// the Wikisource Page: wikitext for the same page) contains non-Latin script
// codepoints, an English-trained OCR pass over that region is untrustworthy
// for TEXT (though its box geometry remains trustworthy -- see
// sw-cv-two-column-runninghead). Confirmed directly: the real word
// "μαθηματική" (Greek,
// "mathematike") on EB1911 p.897/898 comes back from
// `tesseract -l eng` as the Latin-lookalike garbage "wadnyarixn".
export function detect(text, ctx = {}) {
  // Count codepoints outside Latin blocks (ASCII + Latin-1 supplement +
  // Latin Extended-A/B) among alphabetic characters only.
  const alpha = text.match(/\p{L}/gu) || [];
  let nonLatin = 0;
  for (const ch of alpha) {
    const cp = ch.codePointAt(0);
    const isLatin = (cp >= 0x41 && cp <= 0x5a) || (cp >= 0x61 && cp <= 0x7a) || (cp >= 0xc0 && cp <= 0x24f);
    if (!isLatin) nonLatin++;
  }
  const fraction = alpha.length ? nonLatin / alpha.length : 0;
  const fired = nonLatin > 0 && fraction >= (ctx.minFraction ?? 0.02);
  return {
    fired,
    evidence: {
      alphaCount: alpha.length,
      nonLatinAlphaCount: nonLatin,
      nonLatinFraction: +fraction.toFixed(4),
      prediction: fired
        ? "an English-only OCR pass over this span's page region would misrecognize it -- trust the wikitext/plain-text transcription for TEXT, use CV only for geometry"
        : "span is Latin-script; English OCR text is plausible if CV is otherwise needed",
    },
  };
}

// sw-de-absatz-inline-numbering
// German federal statute convention (confirmed against the live HTML at
// gesetze-im-internet.de/gg/BJNR000010949.html, class="jnhtml" paragraphs
// inside each class="jnnorm" article block): an Absatz number is a literal
// "(N) " prefix INSIDE the paragraph's own running text, never a distinct
// <ol>/<li> or numbered-list structure. This is a source-convention, not an
// extraction defect -- and, checked against the local GG.md, our corpus
// preserves it faithfully (a "clean" verdict is a valid, useful finding).
// Detector works on a DE-legislation .md file's text.
export function detect(text, ctx = {}) {
  const headingRe = /^#{2,6}\s+(?:Art|§)\s*\d+[a-z]?\s*$/gim;
  const heads = [...text.matchAll(headingRe)];
  let articlesWithInlineNum = 0;
  let articlesWithoutAbsatzNum = 0;
  const samples = [];
  for (let i = 0; i < heads.length; i++) {
    const start = heads[i].index + heads[i][0].length;
    const end = i + 1 < heads.length ? heads[i + 1].index : text.length;
    const body = text.slice(start, end).trim();
    if (!body) continue;
    const paras = body.split(/\n\s*\n/).filter((p) => p.trim());
    const numbered = paras.filter((p) => /^\(\d+\)\s/.test(p.trim()));
    if (numbered.length > 0) {
      articlesWithInlineNum++;
      if (samples.length < 5) samples.push(paras[0].slice(0, 80));
    } else if (paras.length >= 1) {
      articlesWithoutAbsatzNum++;
    }
  }
  return {
    fired: articlesWithInlineNum > 0,
    evidence: {
      articleHeadingsFound: heads.length,
      articlesWithInlineAbsatzNumbers: articlesWithInlineNum,
      articlesWithSingleUnnumberedParagraph: articlesWithoutAbsatzNum,
      samples,
    },
  };
}

// sw-usc-unlabeled-listitem
// U.S. Code sections do NOT all decompose into a (a)(1)(A) label hierarchy.
// Confirmed against the official USLM XML bulk release
// (uscode.house.gov/download/releasepoints/us/pl/119/73/xml_usc01@119-73.zip,
// usc01.xml): Title 1 Section 1's clauses are
//   <p role="listItem" class="indent1">words importing ...;</p>
// with NO <num> label at all -- structure is indentation-only. Title 35
// Section 2, by contrast, carries literal "(a)" / "(b)" / "(1)" tokens as
// real paragraph-leading text. Our local .md renders the first case as an
// unlabeled markdown bullet list (correct: no label fabricated) and the
// second as literal "(a)"-prefixed paragraphs (also correct). A downstream
// reader must check for a literal leading label before assuming a USC
// section has citable (a)(1)(A) addresses.
export function detect(text, ctx = {}) {
  const bulletRe = /^- .+[;.]$/gim;
  const bullets = text.match(bulletRe) || [];
  const labeledRe = /^\([a-zA-Z0-9]{1,3}\)\s/gm;
  const labeled = text.match(labeledRe) || [];
  return {
    fired: bullets.length > 0,
    evidence: {
      unlabeledBulletCount: bullets.length,
      literallyLabeledParagraphCount: labeled.length,
      convention:
        bullets.length > 0 && labeled.length === 0
          ? "indentation-only (unlabeled) subsections -- no (a)(1)(A) address exists in the source"
          : bullets.length === 0 && labeled.length > 0
          ? "literal (a)(1)(A) labels present in source -- citable subsection address exists"
          : bullets.length > 0 && labeled.length > 0
          ? "mixed: some clauses labeled, some not, within the same section"
          : "neither pattern matched",
    },
  };
}

// sw-declared-source-unfetchable
// Provenance check applied reflexively to the corpus's OWN frontmatter.
// Fetching the exact "source" URL a .md file declares
// (uscode.house.gov/view.xhtml?req=granuleid:...) returns either a
// JSF "Document not Found" page, or -- once made to work with undocumented
// query parameters -- a response dominated by JSF application framework
// bytes (a multi-kilobyte base64 javax.faces.ViewState blob, dozens of
// j_idt### auto-generated element ids, jsessionid in every link) rather than
// semantic statute markup. Measured: a working fetch of USC-T1-S1's page
// was 195,267 bytes, of which the single ViewState blob was already >2,700
// bytes with no visible § text anywhere near it. This means the URL in the
// frontmatter's `source` field is a human-facing CITATION target, not
// verified fetch provenance -- the clean, richly cross-linked markdown much
// more plausibly came from the Office of the Law Revision Counsel's USLM XML
// bulk release (whose own <ref>/<note> structure matches the markdown's
// inline links and section-credit formatting).
export function detect(text, ctx = {}) {
  const notFound = /Document not [Ff]ound/.test(text);
  const viewStateMatch = text.match(/javax\.faces\.ViewState[^"]*"\s+value="([^"]+)"/);
  const viewStateLen = viewStateMatch ? viewStateMatch[1].length : 0;
  const jsfHookCount = (text.match(/j_idt\d+/g) || []).length;
  const hasSessionId = /jsessionid=/i.test(text);
  const sectionSymbolCount = (text.match(/§/g) || []).length;
  const fired = notFound || viewStateLen > 500 || jsfHookCount > 10;
  return {
    fired,
    evidence: {
      notFoundPage: notFound,
      viewStateBlobLength: viewStateLen,
      jsfElementIdCount: jsfHookCount,
      hasSessionIdInLinks: hasSessionId,
      totalLength: text.length,
      sectionSymbolOccurrences: sectionSymbolCount,
      frameworkByteFraction: text.length ? +((viewStateLen + jsfHookCount * 8) / text.length).toFixed(4) : 0,
    },
  };
}

// sw-factbook-html-in-json
// The CIA World Factbook mirror this corpus's world-factbook/ family was
// built from (a GEC-code-keyed JSON mirror; confirmed live at
// raw.githubusercontent.com/factbook/factbook.json/master/africa/ag.json,
// matching our own "africa_ag.txt" region_gec naming) stores each field's
// VALUE as a raw HTML string: {"text": "<p>Algeria has known ... <br><br>
// Algeria's long-dominant ...</p>"}. Confirmed byte-for-byte identical,
// including the exact straight apostrophe, between that live JSON and our
// local extraction. This is the source's own convention, faithfully
// preserved -- but it means any reader treating the .txt as clean prose will
// see literal "<p>"/"<br><br>" tag noise unless it HTML-strips field values
// before reading them.
export function detect(text, ctx = {}) {
  const pOpen = (text.match(/<p>/g) || []).length;
  const pClose = (text.match(/<\/p>/g) || []).length;
  const br = (text.match(/<br\s*\/?>/gi) || []).length;
  const hasMdHeadings = /^#{1,6}\s/m.test(text);
  const fired = hasMdHeadings && (pOpen > 0 || br > 0);
  return {
    fired,
    evidence: {
      pOpenTags: pOpen,
      pCloseTags: pClose,
      brTags: br,
      hasMarkdownHeadingsAlongside: hasMdHeadings,
    },
  };
}

// sw-archiveorg-enumeration-bloat
// Archive.org item metadata's "collection" field can carry hundreds of
// per-user "fav-<username>" pseudo-collection tags. Measured: our
// grateful-dead-catalog.txt records item
// "gd71-08-06.aud.bertrando.yerys.129.sbeok.shnf" with ~600+ comma-separated
// collection tags, ~98.5% of that record's bytes. Re-fetching the SAME
// identifier's /metadata/ endpoint fresh (and a second identifier from the
// same catalogue) returned only 2-3 clean tags for BOTH -- meaning either
// archive.org changed what that endpoint returns, or the field is simply too
// volatile (favourites churn) to pin down by count. THE COUNT DOES NOT
// REPLICATE. The only falsifiable, durable signature is therefore SHAPE:
// an enumeration field is bloat when almost all of its comma-separated
// tokens share one literal prefix -- not any specific count.
export function detect(text, ctx = {}) {
  const lineRe = /^collection:\s*(.+)$/gim;
  const fields = [];
  let m;
  const minTokens = ctx.minTokens ?? 10;
  const prefixLen = ctx.prefixLen ?? 4;
  const minFraction = ctx.minFraction ?? 0.9;
  while ((m = lineRe.exec(text))) {
    const tokens = m[1]
      .split(",")
      .map((s) => s.trim())
      .filter(Boolean);
    if (tokens.length < minTokens) continue;
    const counts = new Map();
    for (const t of tokens) {
      const p = t.slice(0, prefixLen);
      counts.set(p, (counts.get(p) || 0) + 1);
    }
    let best = 0,
      bestPrefix = "";
    for (const [p, c] of counts) if (c > best) { best = c; bestPrefix = p; }
    fields.push({ tokenCount: tokens.length, dominantPrefix: bestPrefix, dominantFraction: +(best / tokens.length).toFixed(4) });
  }
  const fired = fields.some((f) => f.dominantFraction >= minFraction);
  return {
    fired,
    evidence: { fieldsChecked: fields.length, fields: fields.slice(0, 10), params: { minTokens, prefixLen, minFraction } },
  };
}

// sw-title-truncated-at-source
// NASA's images-api.nasa.gov itself serves an already-truncated "title"
// field (confirmed byte-for-byte against a fresh call to
// images-api.nasa.gov/search?nasa_id=MSFC-1701491: both the live API and our
// local catalog give the identical, mid-sentence-truncated title
// '2017 "Mission Success is in Our Hands" program with Apollo 17 as').
// The truncation is upstream of any extraction we did -- a source-fact, not
// a corpus bug. DANGLING_ENDERS is a small closed set of English function
// words that cannot legally end a complete sentence/title; it is declared
// as an explicit table (house rule), not a regex alternation standing in for
// a hidden word list.
const DANGLING_ENDERS = new Set([
  "a", "an", "the", "as", "of", "and", "or", "with", "in", "on", "to", "for",
  "by", "from", "at", "is", "was", "into", "onto", "but", "not", "than",
]);

export function detect(text, ctx = {}) {
  const titleRe = /^--- \d+\.\s+(.+)$/gim;
  const hits = [];
  let m;
  while ((m = titleRe.exec(text))) {
    const title = m[1].trim();
    const words = title.split(/\s+/);
    const lastRaw = words[words.length - 1];
    const last = lastRaw.toLowerCase().replace(/[^a-z]/g, "");
    const endsWithClosingPunct = /["'.!?”)]$/.test(title);
    if (!endsWithClosingPunct && DANGLING_ENDERS.has(last)) {
      hits.push(title);
    }
  }
  return {
    fired: hits.length > 0,
    evidence: { danglingTitleCount: hits.length, examples: hits.slice(0, 10) },
  };
}

// sw-catalog-field-projection
// The Met Museum's collectionapi.metmuseum.org/.../objects/{id} endpoint
// returns 57 fields per object (measured live on objectID 123870, "Sarong").
// Our met-museum-catalog.txt keeps exactly 9 of them (objectID, date,
// culture, medium, dimensions, department, classification, creditLine,
// objectURL) and drops the other 48 (artist fields, geography fields, image
// URLs, Wikidata/ULAN links, tags, gallery number, rights text, etc.) even
// when they are non-empty upstream. This is a deliberate schema projection
// by the corpus builder (a script-convention), not corruption -- but a
// reader must know the dropped fields are gone, not merely empty in the
// original. ctx.sourceFields must be supplied (the array of field names the
// live API actually returned for the record under test); this keeps the
// detector honest about needing the original to know what was dropped.
export function detect(text, ctx = {}) {
  if (!ctx.sourceFields) {
    return { fired: false, evidence: { note: "requires ctx.sourceFields from a live API record" } };
  }
  const keptKeys = new Set([...text.matchAll(/^([a-zA-Z]+):/gm)].map((m) => m[1]));
  const dropped = ctx.sourceFields.filter((f) => !keptKeys.has(f));
  const kept = ctx.sourceFields.filter((f) => keptKeys.has(f));
  return {
    fired: dropped.length > 0,
    evidence: {
      totalSourceFields: ctx.sourceFields.length,
      keptFields: kept,
      droppedFieldCount: dropped.length,
      droppedFieldSample: dropped.slice(0, 20),
    },
  };
}

// sw-page-break-marker-by-source
// Contrasts two childrens-books pipelines feeding the SAME territory.
// African Storybook (mirrored from github.com/global-asp/global-asp) marks
// each page break with a bare "##" (a heading marker with empty heading
// text) -- confirmed by a byte-for-byte diff of the live GitHub raw file
// against our local copy (es/0001_un-hombre-muy-alto.md): 0 bytes different,
// so "##" is the SOURCE's own convention, not something our fetch added.
// Global Digital Library books (content.digitallibrary.io; per this
// family's own ATTRIBUTION.md, "page text extracted from each EPUB's <p>
// elements") carry NO marker at all: only blank-line paragraph breaks
// survive, so the original book's page/spread boundaries are lost at
// extraction, not merely unmarked.
export function detect(text, ctx = {}) {
  const bareHashes = text.match(/^##\s*$/gm) || [];
  const namedHeadings = text.match(/^#{1,6}\s+\S.*$/gm) || [];
  const paragraphBreaks = text.split(/\n\s*\n/).filter((p) => p.trim()).length;
  const fired = bareHashes.length > 0;
  return {
    fired,
    evidence: {
      barePageBreakMarkerCount: bareHashes.length,
      namedHeadingCount: namedHeadings.length,
      paragraphCount: paragraphBreaks,
      interpretation: fired
        ? "page-break markers present (African-Storybook-style source)"
        : paragraphBreaks > 1
        ? "no page-break marker found despite multiple paragraphs -- page boundaries likely lost (Global-Digital-Library-style source)"
        : "single block, nothing to say about page boundaries",
    },
  };
}

// sw-provenance-md-is-corpus-metadata
// PROVENANCE.md files inside 09-source-code/*/ are always authored by this
// corpus's OWN fetch scripts, never by the upstream repository. Confirmed:
// git_git/PROVENANCE.md carries a YAML frontmatter with exactly
// {source, commit, branch, license, tier, fetched_at}, a key-set the
// upstream git/git repository itself would have no reason to write about
// itself. A reader must never treat PROVENANCE.md/ATTRIBUTION.md content as
// evidence about the ORIGINAL project's own conventions (licence headers,
// comment style, indentation) -- it documents OUR fetch, not their source.
export function detect(text, ctx = {}) {
  const fm = text.match(/^---\n([\s\S]*?)\n---/);
  if (!fm) return { fired: false, evidence: { hasFrontmatter: false } };
  const keys = [...fm[1].matchAll(/^([a-zA-Z_]+):/gm)].map((m) => m[1]);
  const expected = ["source", "commit", "branch", "license", "tier", "fetched_at"];
  const overlap = expected.filter((k) => keys.includes(k));
  return {
    fired: overlap.length >= 4,
    evidence: { frontmatterKeys: keys, matchedCorpusMetadataKeys: overlap },
  };
}

// sw-source-code-byte-faithful
// A positive ("clean") finding for the 09-source-code family: files fetched
// from raw.githubusercontent.com are copied byte-for-byte, including every
// tab character. Confirmed: github-sqlite-README.md (freshly fetched) and
// the local sqlite_sqlite/README.md differ in 0 bytes (21,165 bytes each,
// `diff` produces no output). This licenses treating indentation, tabs vs
// spaces, and line endings in this family's files as the ORIGINAL author's
// own structure, with no extraction step to distrust.
export function detect(text, ctx = {}) {
  if (typeof ctx.original !== "string") {
    return { fired: false, evidence: { note: "requires ctx.original (the freshly fetched upstream bytes) to compare against" } };
  }
  const identical = text === ctx.original;
  const tabsLocal = (text.match(/\t/g) || []).length;
  const tabsOriginal = (ctx.original.match(/\t/g) || []).length;
  return {
    fired: identical,
    evidence: {
      byteIdentical: identical,
      localLength: text.length,
      originalLength: ctx.original.length,
      tabsInLocal: tabsLocal,
      tabsInOriginal: tabsOriginal,
    },
  };
}

// sw-guardian-clue-line-format
// NOT grounded on the original per-clue data: the Dryad file-download
// endpoint (datadryad.org/api/v2/files/{id}/download) returned HTTP 401
// Unauthorized for this CC0-licensed dataset even without following
// redirects differently; no credential-bypass was attempted, per the "never
// bypass auth" rule. Only the dataset's own self-describing header (fetched
// via Dryad's dataset-metadata API, HTTP 200) and the NeurIPS paper's
// abstract were confirmed live. This detector therefore documents only the
// LOCAL flattening convention's internal consistency, not a verified
// original-vs-extraction comparison. Treat any "rule" built on it as
// UNGROUNDED until someone with Dryad credentials re-runs this check against
// guardian_2020_10_08.json.zip.
export function detect(text, ctx = {}) {
  const lines = text.split("\n");
  const dataLineRe = /\s[—–-]\s.+\(setter:\s*[^)]+\)\.?\s*$/;
  const conforming = lines.filter((l) => dataLineRe.test(l));
  const dashVariants = new Set();
  for (const l of conforming.slice(0, 20000)) {
    const m = l.match(/\s([—–-])\s.+\(setter:/);
    if (m) dashVariants.add(m[1]);
  }
  return {
    fired: conforming.length > 0,
    evidence: {
      totalLines: lines.length,
      conformingLines: conforming.length,
      nonConformingLines: lines.length - conforming.length,
      dashVariantsSeen: [...dashVariants],
      groundedOnOriginal: false,
    },
  };
}

// sw-udhr-corpus-shape
// Provenance mismatch: every un-udhr/*.txt file's own header claims
// "Publisher: Office of the United Nations High Commissioner for Human
// Rights (OHCHR)", but the FILE-SET's shape -- numeric-only identifiers for
// languages lacking a clean code (e.g. udhr-007.txt: "Language: Sãotomense
// (cri)"; udhr-013 through udhr-026: "(Bizisa)/(Jinan)/(Klau)/... (und)"),
// plus deliberate historical-orthography duplicates for a single language
// (udhr-deu_1901.txt vs udhr-deu_1996.txt; udhr-ron_1953/1993/2006.txt) --
// is the distinctive fingerprint of the Unicode Consortium's "UDHR in
// Unicode" project, not of OHCHR's own translations listing. Independently
// confirmed live: unicode.org/udhr/ now states "Effective January 2024, the
// Unicode Consortium is no longer hosting the UDHR in Unicode project" and
// redirects to OHCHR -- so the numbering this corpus mirrors comes from a
// now-discontinued aggregation, one step upstream of the OHCHR attribution
// each file prints. A direct byte-check against OHCHR's own site was
// blocked by a Cloudflare interstitial (both curl, HTTP 403, and the browser
// tool, a "Just a moment..." challenge page) -- no bypass was attempted, so
// this rule's OHCHR half stays UNVERIFIED at the byte level; only the
// Unicode-retirement half is independently confirmed live.
export function detect(text, ctx = {}) {
  const filename = ctx.filename || "";
  const numericId = /^udhr-\d{3}\.txt$/.test(filename);
  const undCode = /\(und\)\s*$/m.test(text.split("\n")[0] || text.slice(0, 120));
  const claimsOHCHR = /Publisher:\s*Office of the United Nations High Commissioner/i.test(text);
  const historicalVariantSuffix = /^udhr-[a-z]+_(1\d{3}|19\d{2}|20\d{2})\.txt$/.test(filename);
  const fired = (numericId || undCode || historicalVariantSuffix) && claimsOHCHR;
  return {
    fired,
    evidence: {
      filename,
      numericOnlyIdentifier: numericId,
      undeterminedLanguageCode: undCode,
      historicalOrthographyVariantSuffix: historicalVariantSuffix,
      claimsOHCHRPublisher: claimsOHCHR,
    },
  };
}
